(window.GIM_TS=window.GIM_TS||{})["Niddah.3"]={"from":72,"a":[["כך היא הלכה לא רק בראיית דם קושי של לידה בשבעת הימים שלאחר אחד עשר ימי זיבה, אלא \u0003אפילו\u0004 ב\u0003ימים ה\u0004באים לאחר שבעת ימי ספירת הנקיות לזיבה ו\u0003ראויין לספירת סתירת זבה.\u0004 שאם היא רואה אף ביום השביעי לספירת ימי נקיות של זיבה, הריהי סותרת את ספירתה ומתחילה שוב בספירת שבעה ימים של נקיות, ולכך דם קושי טהור אף בימים הללו, שהרי אף הוא מכלל זיבותה. ונמצא שאין דם קושי מטמא, אלא כשראתהו בימי נדות.","ודנים בשיטותיהם של לוי ורב, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]\u0006 בדינו של דם קושי, \u0003כמה\u0004 זמן \u0003הוא קשויה? ר'\u0004 \u0003מאיר אומר: ארבעים ו\u0004כן חמשים יום, ומהדברים הללו משמע שלדעת ר' מאיר הריהי טהורה בדם קושי אף במשך ארבעים וחמישים ימים שלפני הלידה הן מזיבות והן מנדות. ומבררים: \u0003בשלמא\u0004 \u0005[זה נוח]\u0006","\u0003ל\u0004שיטת \u0003רב\u0004 הסבור כי דם קושי טהור אף בימים שלאחר אחד עשר יום של ימי זיבה — \u0003משכחת לה\u0004 \u0005[מוצא\u0006 אתה \u0005אותה]\u0006 אפשרות שתהיה טהורה במשך זמן כה רב, ו\u0003כ\u0004הסברו של \u0003רב אדא בר אהבה\u0004 בשיטת רב, שכך הדין אף בימים הראויים לספירה של סתירת זיבה. ומעתה אפשרי הדבר במציאות וכגון שהתחילה לראות בימי זיבותה, ונמשך הדבר ללא ששפתה בינתיים חמישים ימים עד שילדה. ובכל הימים הללו הריהי טהורה. \u0003אלא ל\u0004שיטת \u0003לוי\u0004 הסבור שאין דם קושי טהור בימים שלאחר ימי זיבה, \u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר, שהרי אין אפשרות שתמשיך לראות דם קושי המטהר במשך חמישים יום!","ומשיבים: שכן \u0003אמר לך\u0004 \u0005[\u0006יכול \u0005לומר לך]\u0006 \u0003לוי\u0004 בהסבר הדברים: \u0003מי קתני\u0004 \u0005[האם שנינו]\u0006 בדברי ר' מאיר שהריהי בכל חמישים הימים הללו \u0003\"טהורה בכולן\"\u0004 כלומר, שטהורה מכל הטומאות, הן מטומאת נדה והן מטומאת זיבה? אין זה כך, שהרי אם ראתה דם קושי במשך זמן זה \u0003בימי נדה\u0004 — הריהי טמאה בטומאת \u0003נדה,\u0004 ואין הדברים אמורים אלא אם ראתה \u0003בימי זיבה\u0004 — שהיא \u0003טהורה.\u0004","ומביאים: סוגיה זו ב\u0003לישנא אחרינא אמרי\u0004 \u0005[לשון,\u0006 באופן, \u0005אחר אמרו\u0006 אותה חכמים\u0005],\u0006 וגרסו, \u0003אמר ר'\u0004 \u0003לוי: אין הולד\u0004 (דם קושי הבא מחמת לידה) \u0003מטהר\u0004 (אינו מטמא) \u0003אלא\u0004 רק זה הבא באחד עשר הימים שלאחר ימי נדותה, שהם ה\u0003ימים הראויין להיות בהן זבה גדולה.\u0004 שרק בזו הרואה זיבה שלושה ימים ברציפות (\"זבה גדולה\") אמורים הדברים, מה שאין כן ברואה דם קושי יום אחד או שנים (\"זבה קטנה\") שנטמאת בהם והריהי צריכה לשמור יום נקיות כנגד יום ראייתה. \u0003מאי טעמא\u0004 \u0005[מה הטעם,\u0006 מקור הדין\u0005]?\u0006 שכן \"ואשה כי יזוב זוב \u0003דמה ימים רבים...\u0004 כל ימי זוב טומאתה כימי נדתה תהיה טמאה היא\" (ויקרא טו, כה) \u0003כתיב\u0004 \u0005[נאמר],\u0006 והרי הדברים אמורים ברואה זיבה שלושה ימים. שרק בזו נאמר המיעוט שהינה טמאה מחמת דם עצמה, ואינה נטמאת מחמת דם הבא בשל קישוי לידה.","ואילו \u0003אבא שאול משמיה\u0004 \u0005[בשמו]\u0006 של \u0003רב אמר:\u0004 דם קושי אינו מטמא \u0003אפילו\u0004 ראתה ב\u0003ימים הראויין להיות בהן זבה קטנה, מאי טעמא\u0004 \u0005[מה הטעם,\u0006 מקור הדין\u0005]\u0006 לכך? — \u0003\"ימי\" ו\"כל ימי\" התם כתיבי\u0004 \u0005[שם נאמרים],\u0006 והרי זה בא לרבות דם קושי אף בראייה אחת או שתים, בזבה קטנה.","ומקשים: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005],\u0006 \u0003כמה הוא קשויה? ר'\u0004 \u0003מאיר אומר: אפילו ארבעים וחמשים יום,\u0004 והרי מדברים אלה \u0003קשיא לתרוייהו\u0004 \u0005[קשה לשניהם,\u0006 לר' לוי ולרב\u0005],\u0006 שהרי שניהם סבורים כי רק הרואה דם קושי בתוך אחד עשר הימים הראויים לזיבה טהורה, ומדברי ר' מאיר מבואר שטהורה גם אם המשיכה וראתה דם קושי במשך חמישים ימים! ומשיבים: \u0003מי קתני\u0004 \u0005[האם שנינו]\u0006 בדברי ר' מאיר שבכל חמישים הימים הללו היא \u0003\"טהורה בכולן\"\u0004 (בכל הטומאות, הן מטומאת נדה והן מטומאת זיבה)? אין זה כך, שאם \u0003קשתה\u0004 (ראתה דם קושי) במשך זמן זה \u0003בימי נדתה\u0004 — הריהי טמאה בטומאת \u0003נדה,\u0004 ורק אם ראתה \u0003בימי זיבתה\u0004 — הריהי \u0003טהורה.\u0004","ומביאים עוד מדברי ר' מאיר בדין דם קושי. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 כך \u0003היה ר'\u0004 \u0003מאיר אומר: יש\u0004 ואשה הריהי \u0003מקשה\u0004 (רואה דם מחמת קשי הלידה) בתקופה הנמשכת על פני \u0003מאה וחמשים יום, ואין\u0004 טומאת \u0003זיבה עולה בהן.\u0004 ומפרטים \u0003כיצד\u0004 יתכן הדבר: בתחילה ראתה האשה דם ב\u0003שנים\u0004 ימים ש\u0003בלא עת\u0004 נדות. וכגון שראתה ביום העשירי וביום האחד עשר מאחד עשר הימים הראויים לזיבה, שאין היא נטמאת בנדה בראייה זו, ואינה נעשית בכך זבה גדולה (שהרי לא ראתה אלא יומיים).","\u0003ו\u0004לאחר מכן המשיכה וראתה במשך \u0003שבעה\u0004 הימים הראויים לטומאת \u0003נדה\u0004 (שלאחר תקופת אחד עשר יום הראויים לטומאת זיבה), ואין ראייה זו נחשבת כראייה שלישית לטמאה בזיבה, שהרי חלה בתקופה ימי נדות. \u0003ו\u0004לאחר מכן ראתה שוב דם קושי ב\u0003שנים\u0004 ימים בפרק הזמן \u0003של\u0004 אחד עשר הימים הראויים לזיבה הבאים \u0003אחר\u0004 תקופת שבעת הימים הראויים לטומאת \u0003הנדה.\u0004 הרי עברו עליה אחד עשר יום של ראיית דם קושי, שאין היא נטמאת בו משום זיבה. \u0003ו\u0004לאחר מכן, ביום השנים עשר מתחיל פרק הזמן של \u0003חמשים\u0004 יום, עד הלידה, שבהם אין היא נעשית זבה, שהרי כך הוא הדין \u0003שהולד\u0004 (כלומר, דם קושי של לידה) \u0003מטהר\u0004 (שאינה נטמאת בזיבה על ידו). הרי ששים ואחד יום.","\u0003ו\u0004על אלה יש להוסיף עוד את פרק הזמן בן \u0003שמונים\u0004 יום \u0003של\u0004 טהרה (מטומאת זיבה) שלאחר לידת \u0003נקבה,\u0004 והריהם איפוא ביחד מאה ארבעים ואחד ימים שאין היא נטמאת בזיבה בדם הקושי. \u0003ו\u0004עוד נוסיף על כך את תקופת \u0003שבעה\u0004 הימים הראויים ל\u0003נדה,\u0004 הבאה לאחר ימי הטהרה, \u0003ו\u0004עוד \u0003שנים\u0004 ימים מפרק הזמן \u0003של\u0004 אחד עשר הימים הראויים לזיבה, הבאים ל\u0003אחר\u0004 תקופת הימים הראויים לטומאת \u0003הנדה.\u0004 ונמצא המנין הכולל מסתכם במאה וחמישים ימים, שבהם אין האשה נטמאת בזיבה בראיית דם קושי.","\u0003אמרו לו\u0004 חכמים לר' מאיר בשאלה: \u0003אם כן\u0004 הוא כדבריך אלה, \u0003יש\u0004 אופן שתהיה האשה בגדר \u0003מקשה\u0004 (שאינה נטמאת בזיבה מחמת ראיית דם קושי) \u0003כל ימיה, ואין זיבה עולה בהן.\u0004 שאם לאחר שילדה נקבה נזקקה לבעלה (לאחר ארבעה עשר ימי טומאה וטבילה) והתעברה שוב והמשיכה לראות דם בכל ימי הטהרה ולאחר שתמו שמונים ימי הלידה המשיכה וראתה דם בשבעת ימי הנדה שלאחריהם ובשני הימים הראשונים של ימי הזיבה, ולאחר מכן אחזוה צירי לידה וראתה דם קושי במשך חמישים יום, ולאחרים הפילה נקבה, ונזקקה והתעברה שוב בתוך שמונים ימי הלידה, וחוזר חלילה. וכך כל ימיה תימצא כמי שאינה נטמאת בזיבה, מחמת דם קשי לידה!","\u0003אמר להן\u0004 ר' מאיר בדחיית דבריהם: \u0003מאי דעתייכו\u0004 \u0005[מה דעתכם]\u0006 כששאלתם כן, \u0003משום\u0004 לידת \u0003נפלים\u0004 (שלא השלימה האשה את הריונה, והפילה את ולדה), ואולם כלל הוא כי \u0003אין\u0004 נוהג דין דם \u0003קושי לנפלים.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003יש\u0004 ואשה \u0003רואה\u0004 דם מחמת קשי לידה, \u0003מאה יום ואין\u0004 טומאת \u0003זיבה עולה בהן.\u0004 ומפרטים \u0003כיצד\u0004 אפשרי דבר זה: ראתה ב\u0003שנים\u0004 ימים ש\u0003בלא עת\u0004 נדות, וכגון שראתה ביום העשירי וביום האחד עשר מאחד עשר ימי זיבה, שאינה נטמאת בנדה בראייה זו, \u0003ו\u0004לאחר מכן המשיכה וראתה במשך \u0003שבעה\u0004 ימים הראויים לטומאת \u0003נדה.\u0004 \u0003ו\u0004לאחר מכן ראתה שוב דם קושי ב\u0003שנים\u0004 ימים בפרק הזמן \u0003של\u0004 אחד עשר הימים הראויים לזיבה הבאים \u0003אחר\u0004 תקופת שבעת הימים הראויים לטומאת \u0003הנדה.\u0004 \u0003ו\u0004על אלה יש להוסיף עוד את פרק הזמן בן \u0003שמונים\u0004 יום \u0003של\u0004 טהרה (מטומאת זיבה) שלאחר לידת \u0003נקבה.\u0004 \u0003ו\u0004עוד נוסיף על כך את תקופת \u0003שבעה\u0004 הימים הראויים ל\u0003נדה,\u0004 הבאה לאחר ימי הטהרה, \u0003ו\u0004עוד \u0003שנים\u0004 ימים מפרק הזמן \u0003של\u0004 אחד עשר הימים הראויים לזיבה, הבאים ל\u0003אחר\u0004 תקופת הימים הראויים לטומאת \u0003הנדה.\u0004 ונמצא שהמנין הכולל הוא מאה ימים.","ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה הוא משמיע לנו]?\u0006 — \u0003לאפוקי\u0004 \u0005[להוציא,\u0006 לשלול] \u0003מ\u0004דעת \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 כי \u0003אי אפשר לפתיחת הקבר\u0004 (הרחם) \u0003בלא דם,\u0004 שלשיטה זו אם ילדה אשה (לאחר שראתה בשני הימים שלאחר הנדה) — ברור הוא שראתה דם גם ביום השלישי שלפני הלידה, עם פתיחת הרחם, והריהי איפוא רואה שלושה ימים רצופים בימי זיבה, ונטמאה בזיבה. לכך \u0003קא משמע לן\u0004 \u0005[הוא משמיע לנו]\u0006 ש\u0003אפשר לפתיחת הקבר בלא דם,\u0004 ואם לא ראתה ביום השלישי שלפני הלידה, ולאחר מכן ילדה — אין היא נעשית זבה.","שנינו עוד במשנתנו כי \u0003ר' יהודה אומר\u0004 ש\u0003דיה\u0004 לאשה זו הרואה דם קושי, שאינה מטמאה בזיבה בחודש האחרון להריונה (\"חדשה\") בלבד. ובענין זה \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003ר' יהודה אומר משום\u0004 \u0005[בשם]\u0006 \u0003ר' טרפון: דיה חדשה\u0004 בלבד. \u0003ויש בדבר\u0004 זה צד \u0003להקל,\u0004 שלא תטמא בזיבה, \u0003ו\u0004יש בו צד \u0003להחמיר,\u0004 שתטמא בזיבה.","ומסביר: \u0003כיצד\u0004 הוא הדבר? אם \u0003קשתה\u0004 (ראתה דם קושי) \u0003שנים\u0004 הימים ש\u0003בסוף\u0004 החודש ה\u0003שמיני\u0004 להריונה, \u0003ו\u0004לאחר מכן עוד יום \u0003אחד בתחלת\u0004 החודש ה\u0003תשיעי\u0004 להריונה, \u0003ואפילו\u0004 אם לאחר מכן מיד \u0003בתחלת\u0004 החודש ה\u0003תשיעי\u0004 היא \u0003ילדה\u0004 — שני הימים שראתה בהם בחודש השמיני, הריהם ימי זיבה, ומצטרף אליהם היום השלישי (אף שחל בחודש התשיעי להריונה), ולכך \u0003הרי זו\u0004 נחשבת כ\u0003יולדת בזוב.\u0004","\u0003אבל\u0004 יש בדבר גם צד להקל, וכגון ש\u0003קשתה יום אחד בסוף\u0004 החודש ה\u0003שמיני ו\u0004לאחר מכן ראתה דם קושי ב\u0003שתים\u0004 ימים ש\u0003בתחלת\u0004 החודש ה\u0003תשיעי, ואפילו\u0004 רק \u0003בסוף\u0004 החודש ה\u0003תשיעי ילדה\u0004 — \u0003אין זו\u0004 נחשבת כ\u0003יולדת בזוב,\u0004 וטהורה היא.","\u0003אמר רב אדא בר אהבה: שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 \u0003ר' יהודה\u0004 כי \u0003שיפורא גרים\u0004 \u0005[השופר,\u0006 קול התקיעה בעת קידוש החודש, הוא ה\u0005גורם],\u0006 שמשעה שהחל החודש התשיעי להריונה, שוב אין הדם שרואה בו מטמא. ושואלים: \u0003איני\u0004 \u0005[האמנם כן]\u0006 הוא שמשך כל החודש התשיעי להריון הריהו הזמן שעומדת היא בו ללדת (ולכך הדם שרואה, נחשב כדם קושי), \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר שמואל\u0004 כי \u0003אין\u0004 ה\u0003אשה מתעברת ויולדת אלא ל\u0004אחר שעברו \u0003מאתים ושבעים ואחד יום\u0004 מאז התעברה, שהם תשעה חודשים מלאים, \u0003או למאתים ושבעים ושנים יום, או למאתים ושבעים ושלשה.\u0004 \u0003אבל לא לפני כן, אף שהיא בחודש התשיעי להריונה! ומשיבים:\u0004","\u0003הוא,\u0004 שמואל, ש\u0003אמר\u0004 כן, הריהו סבור \u0003כ\u0004דעתם של ה\u0003חסידים הראשונים, דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003חסידים הראשונים לא היו משמשין מטותיהן אלא\u0004 רק \u0003ב\u0004יום ה\u0003רביעי בשבת,\u0004 ועשו כן כדי \u0003שלא יבואו נשותיהן\u0004"],["\u0003לידי חלול שבת.\u0004 שהרי אילו היו משמשים בימים ראשון או שני או שלישי בשבוע — עלולה האשה ללדת ביום השבת. שהלידה תהיה מאתים ושבעים ואחד (או מאתים ושבעים ושנים או מאתים שבעים ושלושה ימים) לאחר התשמיש. ולפי החשבון נמצא שאזי יחול יום הלידה ביום השבת. ותוהים: אם זהו טעמם של החסידים הראשונים, מדוע לא היו משמשים אלא \u0003ברביעי\u0004 בשבוע בלבד, \u0003ותו\u0004 \u0005[ויותר,\u0006 בשאר ימות השבוע\u0005]\u0006 \u0003לא\u0004 היו משמשים, והרי אף אם ישמשו בימים חמישי וששי ושבת לא יבואו בכך לידי חילול שבת? ומתרצים: \u0003אימא\u0004 \u0005[אמור]\u0006 בגירסת דברי הברייתא: חסידים הראשונים לא היו משמשים מיטותיהם אלא \u0003מרביעי ואילך.\u0004","ובהסבר מנהגם זה של החסידים הראשונים, \u0003אמר מר זוטרא: מאי טעמייהו\u0004 \u0005[מה טעמם,\u0006 המקור\u0005]\u0006 לסברתם של \u0003חסידים הראשונים\u0004 שאין הלידה אלא לאחר מאתים ושבעים ואחד ימים מזמן התשמיש — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בבועז ורות \"ויבא אליה ויתן [ה'] \u0003לה הריון\"\u0004 (רות ד, יג), חשבון אותיות \u0003\"הריון\" בגימטריא\u0004 — \u0003מאתן ושבעים וחד הוו\u0004 \u0005[מאתים ושבעים ואחד הם].\u0006","\u0003אמר מר זוטרא: אפילו ל\u0004שיטת \u0003מאן דאמר\u0004 \u0005[מי שאומר,\u0006 כשמואל וחסידים הראשונים\u0005]\u0006 שהאשה ה\u0003יולדת לתשעה\u0004 חודשים להריונה — \u0003אינה יולדת למקוטעים\u0004 (בחלק החודש התשיעי, אלא רק לאחר שתם החודש התשיעי), אבל האשה ה\u0003יולדת לשבעה\u0004 חודשים — \u0003יולדת\u0004 אף \u0003למקוטעים.\u0004 וראיה לדבר, \u0003ש\u0004כן \u0003נאמר\u0004 בלידתו של שמואל הנביא \u0003\"ויהי לתקפות הימים ותהר חנה ותלד בן\"\u0004 (שמואל א א, כ). שחלפו עליה בהריונה מספר \"תקופות\" (פרקי זמן של שלושה חודשים כל אחד), והרי \u0003מיעוט \"תקפות\"\u0004 — הוא \u0003שנים\u0004 שהם ששה חודשים, ו\u0003מיעוט \"ימים\"\u0004 — הריהם \u0003שנים.\u0004 ונמצא שנולד שמואל למקוטעים, בתחילת החודש השביעי.","עוד שנינו במשנתנו כי \u0003ר' יוסי ור' שמעון אומרים\u0004 ש\u0003אין\u0004 דם \u0003קושי\u0004 מטהר \u0003יותר משתי שבתות\u0004 (שבועות) לפני הלידה. ובהסבר הדברים \u0003אמר שמואל: מאי טעמייהו דרבנן\u0004 \u0005[מה טעמם,\u0006 מקורם, \u0005של חכמים\u0006 אלה\u0005]\u0006 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 באשה היולדת נקבה \u0003\"וטמאה שבעים כנדתה\".\u0004 ויקרא יב, ה), להורות שתהא זו טמאה \u0003כ\u0004טומאת \u0003נדתה ולא כ\u0004טומאת \u0003זיבתה,\u0004 ו\u0003מכלל\u0004 הדברים יש להסיק כי \u0003זיבתה\u0004 בדם קושי הריהי \u0003טהורה, וכמה\u0004 זמן היא טהורה? \u0003שבועים.\u0004","ועוד בענין דם קושי שאינו מטמא בזיבה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003יש\u0004 אשה ה\u0003מקשה עשרים וחמשה יום\u0004 לפני הלידה, \u0003ואין\u0004 טומאת \u0003זיבה עולה בהן\u0004 לטמאה. ומפרטים: \u0003כיצד\u0004 הוא? — כגון שראתה דם קושי \u0003שנים\u0004 ימים \u0003בלא עת\u0004 (שלא בזמן) הראוי לנדות, אלא בתקופת אחד עשר הימים הראויים לזיבה, \u0003ו\u0004לאחר מכן המשיכה וראתה דם קושי ב\u0003שבעה\u0004 הימים של תקופת ה\u0003נדה, ו\u0004לאחר מכן ראתה ב\u0003שנים\u0004 ימים \u0003שלאחר\u0004 תקופת ה\u0003נדה, ו\u0004המשיכה וראתה \u0003ארבעה עשר\u0004 ימים שבסמוך ללידה, \u0003שהולד\u0004 (שהלידה) \u0003מטהר\u0004 את כל הדם שרואה באותם הימים.","\u0003ואי אפשר\u0004 (אין אופן) \u0003שתתקשה\u0004 האשה \u0003עשרים וששה יום בלא ולד\u0004 (לידה), \u0003ולא תהא יולדת בזוב\u0004 (נטמאת בזיבה). שהרי בתוך פרק זמן של עשרים וששה ימים (ובלא שבעת ימי נדה וארבעה עשר הימים שלפני הלידה) ישנם חמישה ימים, וראיית שלושה ימים רצופים בהם, מביאתה לכלל זיבה.","ותוהים על האמור בברייתא \u0003\"בלא ולד\",\u0004 שהרי אם ראתה בלא ולד, \u0003בתלתא נמי סגי\u0004 \u0005[בשלושה\u0006 ימים שלאחר תקופת הנדה \u0005גם כן מספיק]!\u0006 \u0003אמר רב ששת, אימא\u0004 \u0005[אמור]\u0006 כך בלשון הברייתא: \u0003\"במקום שיש ולד\".\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: והא\u0004 \u0005[והרי] \"\u0006\u0003בלא ולד\" קתני\u0004 \u0005[\u0006התנא \u0005שונה]!\u0006","\u0003אלא אמר רבא, הכי קאמר\u0004 \u0005[כך\u0006 התנא \u0005אומר]:\u0006 \u0003אי אפשר שתתקשה עשרים וששה יום במקום שיש ולד ולא תהא יולדת בזוב, ובמקום שאין ולד אלא נפל\u0004 — \u0003בתלתא נמי הויא\u0004 \u0005[בשלושה גם כן הריהי]\u0006 \u0003זבה, מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — משום ש\u0003אין\u0004 דין דם \u0003קושי\u0004 נוהג \u0003לנפלים.\u0004","האשה המעוברת \u0003המקשה\u0004 ללדת את העובר שבמעיה, והריהי בתקופת ימים ש\u0003בתוך שמונים\u0004 הימים לאחר לידתה \u0003של נקבה.\u0004 וכגון שהתעברה בימי הטוהר ללידתה נקבה (ששים וששה הימים שלאחר ארבע עשרה ימי טומאה), ועומדת עתה להפיל ולד זה. או שהיתה מעוברת בתאומים, זכר ונקבה, ותחילה יצאה הנקבה, ועתה העובר השני שוהה מלצאת — \u0003כל\u0004 ה\u0003דמים שהיא רואה\u0004 הריהם \u0003טהורין,\u0004 שהרי ששים וששה הימים הללו הינם ימי טהרה, שהדמים שרואה בהם אינם מטמאים. ועד מתי היא טהורה — \u0003עד שיצא הולד,\u0004 שביציאתו נטמאת טומאת לידה. \u0003ו\u0004אילו \u0003ר' אליעזר מטמא\u0004 דם קושי זה.","\u0003אמרו לו\u0004 חכמים (המטהרים) \u0003לר' אליעזר\u0004 (המטמא): \u0003ו\u0004הלא ממידת קל וחומר נלמד שדם קושי זה הריהו טהור, שהרי \u0003מה במקום שהחמיר\u0004 הכתוב \u0003ב\u0004דין \u0003דם השופי\u0004 (דם שאינו דם קושי), בשאר יולדות הרואות בימים שלאחר ימי טוהר, שמטמא אותן — \u0003היקל\u0004 בהן \u0003ב\u0004רואות \u0003דם הקושי.\u0004 ב\u0003מקום שהיקל\u0004 הכתוב \u0003ב\u0004דין \u0003דם השופי,\u0004 בימי טוהר שלאחר הלידה, שאינו מטמא את היולדת — \u0003אינו דין שנקל\u0004 בו \u0003ב\u0004רואות \u0003דם הקושי?\u0004","\u0003אמר להן\u0004 ר' אליעזר לחכמים בתשובה: כלל הוא בדרכי לימוד קל וחומר ש\u0003דיו לבא מן הדין\u0004 (הדבר הנלמד במידת קל וחומר, כדם קושי של ימי טוהר) \u0003להיות\u0004 דינו \u0003כנדון\u0004 (הדבר המלמד במידת קל וחומר, כדם קושי של לפני לידה). ולענייננו יש לומר: שלא יהא דינו של דם הקושי בימי טוהר אלא כדינו של דם קושי בימים שלאחר ימי טוהר. \u0003ממה היקל עליה,\u0004 על האשה הרואה דם קושי בימים שלפני לידה — רק \u0003מטומאת זיבה, אבל טמאה\u0004 היא \u0003טומאת נדה,\u0004 שאף דם קושי שבימי טוהר מטמא טומאת נדה.","שנינו במשנתנו שנחלקו חכמים ור' אליעזר בדין דם קושי הנראה בתוך שמונים יום ללידת נקבה. ומביאים עוד מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: נאמר בענין ימי הטהרה של האשה היולדת נקבה \"וששים יום וששת ימים תשב על דמי טהרה\" (ויקרא יב, ה). ובאה המלה \u0003\"תשב\"\u0004 היתירה \u0003לרבות\u0004 את האשה \u0003המקשה בתוך שמונים\u0004 יום \u0003של\u0004 היולדת \u0003נקבה, שכל דמים שהיא רואה\u0004 — הריהם \u0003טהורין, עד שיצא הולד.\u0004 \u0003ור' אליעזר מטמא.\u0004","\u0003אמרו לו\u0004 חכמים \u0003לר' אליעזר: ו\u0004הלא קל וחומר הוא זה, \u0003מה במקום שהחמיר\u0004 בו הכתוב לטמא \u0003ב\u0004רואה דם מתוך \u0003שופי שלפני\u0004 יציאת \u0003הולד,\u0004 שהריהו טמא בזיבה — \u0003היקל\u0004 עליו הכתוב \u0003ב\u0004רואה דם מתוך \u0003שופי שלאחר\u0004 יציאת \u0003הולד,\u0004 ובתוך ימי טוהר, שאין הוא מטמא בזיבה. \u0003מקום שהיקל\u0004 בו הכתוב \u0003ב\u0004רואה דם מחמת \u0003קושי שלפני הולד,\u0004 שאינו מטמא בזיבה — \u0003אינו דין שנקל בקושי שלאחר הולד,\u0004 שבתוך ימי טוהר, שאף הוא אינו מטמא בזיבה!","\u0003אמר להם\u0004 ר' אליעזר לחכמים בתשובה: כלל הוא בדברים הנלמדים בקל וחומר כי \u0003דיו לבא מן הדין\u0004 (כדם קושי שבימי טוהר) \u0003להיות כנדון\u0004 (כדם קושי שלפני הלידה). ומעתה נאמר: \u0003ממה היקל עליה\u0004 הכתוב בדם קושי שלפני הלידה — \u0003מטומאת זיבה, אבל\u0004 הריהי \u0003מטמאה טומאת נדה.\u0004 מעתה נאמר, כי אף דם קושי של ימי טוהר מטמא בנדה.","\u0003אמרו לו\u0004 חכמים לר' אליעזר במענה לדבריו: \u0003הרי אנו משיבין לך לשון\u0004 (למדים קל וחומר באופן) \u0003אחר,\u0004 שנלמד מדם שופי שלאחר הלידה לעניינו של דם קושי שלאחר הלידה, ובאופן זה: \u0003ומה במקום שהחמיר\u0004 הכתוב \u0003ב\u0004דם \u0003שופי שלפני הולד,\u0004 שנטמאת בו — \u0003היקל ב\u0004דם \u0003קושי ש\u0004בא עמו, שכל דם שתראה מחמת קושי הלידה בימים שלפני הלידה אינו מטמא. מעתה, ב\u0003מקום שהיקל\u0004 הכתוב \u0003ב\u0004דם \u0003שופי שלאחר הולד,\u0004 שאינו מטמא — \u0003אינו דין שנקל ב\u0004דם \u0003קושי שעמו,\u0004 שאף הוא אינו מטמא!","\u0003אמר להם\u0004 ר' אליעזר לחכמים בתשובה: \u0003אפילו אתם משיבין\u0004 לי \u0003כל היום כולו\u0004 בדרשות קל וחומר — כלל הוא כי \u0003דיו לבא מן הדין להיות כנדון,\u0004 ומעתה יש לומר: \u0003ממה היקל עליה\u0004 בימי טוהר יותר מאשר בימים שלפני הלידה — \u0003מטומאת זיבה\u0004 שאינה נטמאת בה בימי טוהר, \u0003אבל מטמאה טומאת נדה.\u0004 מעתה אף בדם קושי שבימי טוהר, אין הוא מטמא אלא לענין זיבה ולא לענין נדה.","\u0003אמר רבא: בהא זכינהו\u0004 \u0005[בזאת,\u0006 בדברים הבאים, \u0005ניצחם]\u0006 \u0003ר' אליעזר לרבנן\u0004 \u0005[את חכמים],\u0006 שכך אמר להם: \u0003לאו אמריתו\u0004 \u0005[\u0006האם \u0005אין אתם אומרים]\u0006 בטעם הדבר שאין האשה נטמאת בדם קושי שלפני הלידה — משום שנאמר \"ואשה כי יזוב זוב \u0003דמה\"\u0004 (שם טו, כה), ומלשון \"דמה\" נלמד שאין האשה נטמאת אלא ב\u0003דמה\u0004 הבא \u0003מחמת עצמה, ולא\u0004 בדם הבא \u0003מחמת ולד.\u0004 מעתה, \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 יש לומר בנאמר בטומאת הזיבה \u0003\"וטהרה ממקור דמיה\"\u0004 (שם יב, ז) — דווקא מ\u0003דמיה\u0004 הבאים \u0003מחמת עצמה, ולא\u0004 מדמים הבאים \u0003מחמת ולד.\u0004 ונלמד מכאן כי דם קושי בימי טוהר הריהו טמא.","ושואלים על דברי ר' אליעזר: \u0003אימא\u0004 \u0005[אמור]:\u0006 שאם ראתה דם קושי \u0003בימי נדה\u0004 (בתקופת שבעה ימים שבימי טוהר) — הריהי טמאת \u0003נדה,\u0004 ואולם לאחר שטבלה ונטהרה מנדתה, אם ראתה דם לאחר מכן \u0003בימי זיבה\u0004 שבימי הטוהר — \u0003טהורה!\u0004 ומשיבים: אין לומר כן, כיון ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0005\"תשב\" — הרי זה מורה שיש דין\u0006 \u0003ישיבה אחת ל\u0004כל הדמים \u0003כולן\u0004 שרואה בימי טוהר, שכולם טהורים הם.","ב\u0003כל אחד עשר יום\u0004 שלאחר שבעת ימי נדותה, שהם הימים הראויים לזיבתה, הרי האשה \u0003בחזקת טהרה,\u0004 שאין דרכה לראות דם בימים הללו."],["ובשבעת ימי נדותה, שאין היא מוחזקת בהם כטהורה. האשה ש\u0003ישבה לה\u0004 בתוך שבעת ימי נדותה \u0003ולא בדקה\u0004 את עצמה בכל בוקר וערב אם ראתה דם ונטמאה בו, כנכון לעשות לאשה העוסקת בטהרות (כמבואר במשנה לעיל יא,א). בין אם לא בדקה עצמה משום ש\u0003שגגה\u0004 (שלא ידעה שכך הוא הדין), או משום ש\u0003נאנסה,\u0004 שלא יכלה לבדוק עצמה, או אפילו משום ש\u0003הזידה\u0004 \u0003ולא בדקה\u0004 עצמה — הריהי \u0003טהורה.\u0004 שכן אין היא נחשבת טמאה אלא אם כן בדקה עצמה ומצאה שנטמאה.","אכן אם \u0003הגיע שעת וסתה,\u0004 שביום זה חייבת לבדוק עצמה אם לא נטמאה בו, שהרי חזקה היא כי אורח נשים בזמנו בא, \u0003ולא בדקה\u0004 עצמה — \u0003הרי זו טמאה.\u0004 \u0003ר'\u0004 \u0003מאיר אומר: אם היתה\u0004 האשה \u0003במחבא\u0004 (מסתור מפני הסכנה), \u0003והגיע שעת וסתה, ולא בדקה\u0004 עצמה — \u0003הרי זו טהורה,\u0004 וטעם הדבר: \u0003מפני ש\u0004ה\u0003חרדה מסלקת את הדמים.\u0004 והחרדה גורמת שלא תראה דם.","\u0003אבל\u0004 בשבעת \u0003ימי\u0004 נקיות של \u0003הזב והזבה,\u0004 שלא בדקו עצמם בכל יום ויום, \u0003ו\u0004כן ה\u0003שומרת יום כנגד יום\u0004 (שראתה יום אחד או יומים בימי הזיבה, שדינה כ\"זבה קטנה\" והיא שומרת את היום השלישי בטהרה, שאם תטבול ולא תראה בו, הריהי טהורה בערב), שלא בדקה עצמה — \u0003הרי אלו בחזקת טומאה,\u0004 שהרי הוחזקו אלה בראיית דם.","שנינו במשנתנו כי במשך כל אחד עשר הימים שלאחר שבעת ימי נדותה, הראויים לזיבתה, הריהי בחזקה טהורה. ומבררים: \u0003למאי הלכתא\u0004 \u0005[למה,\u0006 לענין איזו \u0005הלכה]\u0006 הושמעו הדברים? \u0003אמר רב יהודה: לומר שאינה צריכה בדיקה.\u0004 ושואלים: \u0003והא מדקתני סיפא\u0004 \u0005[והרי מ\u0006מה \u0005ששנינו\u0006 ב\u0005סוף\u0006 המשנה\u0005]\u0006 \u0003\"ישבה ולא בדקה\u0004 — טהורה\", \u0003מכלל\u0004 \u0005[מכאן]\u0006 שרק בדיעבד הריהי טהורה, ואולם \u0003לכתחלה בעיא\u0004 \u0005[צריכה]\u0006 \u0003בדיקה!\u0004","ומשיבים: \u0003סיפא אתאן\u0004 \u0005[סוף\u0006 המשנה \u0005בא]\u0006 לא לענין אחד עשר הימים הללו, אלא \u0003ל\u0004ענין האשה ב\u0003ימי נדה, והכי קאמר\u0004 \u0005[וכך הוא אומר]:\u0006 \u0003כל אחד עשר\u0004 הללו שלאחר ימי הנדות, הריהי \u0003בחזקת טהרה\u0004 — \u0003ו\u0004לכך היא \u0003לא בעיא\u0004 \u0005[אינה צריכה]\u0006 \u0003בדיקה, אבל בימי נדתה\u0004 — הריהי \u0003בעיא\u0004 \u0005[צריכה]\u0006 \u0003בדיקה.\u0004 ואם \u0003ישבה ולא בדקה,\u0004 או ש\u0003שגגה,\u0004 או ש\u0003נאנסה,\u0004 או ש\u0003הזידה ולא בדקה\u0004 — הריהי \u0003טהורה.\u0004","\u0003רב חסדא אמר\u0004 תירוץ אחר: \u0003לא צריכא\u0004 \u0005[נצרך]\u0006 לומר כן \u0003אלא ל\u0004שיטת \u0003ר' מאיר,\u0004 ש\u0003אמר\u0004 כי \u0003אשה שאין לה וסת אסורה לשמש\u0004 עם בעלה, מחשש שמא תראה בשעת תשמיש. ולכך אמרה משנתנו כי \u0003הני מילי\u0004 \u0005[אלה הדברים]\u0006 אמורים דווקא \u0003בימי נדתה\u0004 (הימים שבהם ראויה היא להיות נדה, אם תראה בהם), שאז יש מקום לחשש זה, \u0003אבל בימי זיבתה\u0004 — אף לדעת ר' מאיר הריהי מותרת בתשמיש, שכן היא \u0003בחזקת טהרה קיימא\u0004 \u0005[עומדת].\u0006","ושואלים על הסברו זה של רב חסדא: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 הוא, שאף לדעת ר' מאיר ישנם ימים שמותרת האשה שאין לה וסת לשמש עם בעלה, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003אמר ר'\u0004 \u0003מאיר\u0004 בדינה של זה ש\u0003יוציא\u0004 (יגרשנה) בעלה \u0003ולא יחזיר\u0004 אותה \u0003עולמית\u0004 (לעולם), אף אם יהיה לה לאחר מכן וסת. והרי יכול הוא בימים מסויימים לשמש אתה? ומשיבים: טעם הדבר שעליו לגרשה, משום החשש \u0003דלמא אתיא לקלקולא\u0004 \u0005[שמא תבוא לקלקול,\u0006 לראיית דם\u0005]\u0006 בשעת תשמיש \u0003בימי נדה.\u0004","ומקשים שוב על הסברו של רב חסדא: כיצד הוא מעמיד את דברי משנתנו באשה שאין לה וסת, ו\u0003הא מדקתני סיפא\u0004 \u0005[הרי מ\u0006מה \u0005ששנינו\u0006 ב\u0005סוף\u0006 המשנה\u0005]\u0006 \u0003\"הגיע שעת וסתה ולא בדקה\u0004 — טהורה\", \u0003מכלל\u0004 \u0005[מכאן]\u0006 נלמד ש\u0003באשה שיש לה וסת עסקינן\u0004 \u0005[עוסקים אנו]!\u0006 ומשיבים: \u0003חסורי מחסרא, והכי קתני\u0004 \u0005[חסרים\u0006 הם דברי המשנה, \u0005וכך\u0006 יש \u0005לשנות\u0006 בה\u0005]:\u0006 \u0003כל אחד עשר\u0004 שלאחר ימי הנדות הריהי \u0003בחזקת טהרה, ושריא\u0004 \u0005[ומותרת]\u0006 \u0003ל\u0004שמש עם \u0003בעלה, ו\u0004אילו \u0003בימי נדה\u0004 הבאים אחריהם — הריהי \u0003אסורה\u0004 לשמש עם בעלה (כשיטת ר' מאיר).","\u0003במה דברים אמורים\u0004 — דווקא \u0003באשה שאין לה וסת,\u0004 שבה יש מקום לחשש זה. \u0003אבל\u0004 באשה ש\u0003יש לה וסת\u0004 — הריהי \u0003מותרת\u0004 לשמש עם בעלה, \u0003ו\u0004לענין טהרות שהיא עוסקת בהן הריהי \u0003צריכה בדיקה.\u0004 ברם אם \u0003ישבה ולא בדקה,\u0004 או ש\u0003שגגה,\u0004 או ש\u0003נאנסה,\u0004 או ש\u0003הזידה ולא בדקה\u0004 — הריהי \u0003טהורה.\u0004 ואולם אם \u0003הגיע שעת וסתה ולא בדקה\u0004 — הריהי \u0003טמאה.\u0004","וחוזרים ושואלים על הסברו זה של רב חסדא המעמיד את דברי משנתנו כר' מאיר: \u0003הא מדסיפא\u0004 \u0005[הרי מ\u0006תוך \u0005שהסוף\u0006 של המשנה\u0005]\u0006 הוא שיטת \u0003ר' מאיר\u0004 — מכאן נלמד כי ה\u0003רישא לאו\u0004 \u0005[תחילת\u0006 המשנה היא \u0005לא]\u0006 כשיטת \u0003ר' מאיר!\u0004 ומשיבים: כי כל המשנה \u0003כולה ר' מאיר היא, והכי קאמר\u0004 \u0005[וכך הוא אומר]:\u0006 \u0003אם לא היתה במחבא, והגיע שעת וסתה ולא בדקה\u0004 — הריהי \u0003טמאה, ש\u0004כן \u0003ר' מאיר אומר, אם היתה במחבא והגיע שעת וסתה ולא בדקה\u0004 — הריהי \u0003טהורה,\u0004 וטעם הדבר: מפני \u0003ש\u0004ה\u0003חרדה מסלקת את הדמים.\u0004","\u0003רבא אמר\u0004 הסבר אחר לתחילת משנתנו. \u0003לומר\u0004 (ללמדנו) \u0003ש\u0004אם ראתה האשה דם באותם אחד עשר יום של ימי זיבה — בחזקת טהורה היא, ולכך היא \u0003אינה מטמאה\u0004 את כל הטהרות שנגעה בהן במשך \u0003מעת לעת\u0004 (היממה) שקדמה לראייתה זו. שאנו תולים שראתה רק עתה, ולא לפני כן.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו כי \u0003הנדה, ו\u0004כן \u0003הזבה, והשומרת יום כנגד יום, והיולדת\u0004 שראו דם — \u0003כולן מטמאות\u0004 למפרע \u0003מעת לעת.\u0004 הרי שאף שראייה זו של הזבה ושל השומרת יום כנגד יום, היא בתוך אחר עשר ימי זיבה — הריהן מטמאות מעת לעת. ושלא כהסברו של רבא! ומסכמים: אכן זו היא \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על דברי רבא, ונדחו דבריו.","ומביאים הסבר נוסף בדברי משנתנו של \u0003רב הונא בר חייא\u0004 ש\u0003אמר\u0004 בשם \u0003שמואל:\u0004 \u0003לומר\u0004 (ללמדנו) \u0003ש\u0004האשה \u0003אינה קובעת לה וסת בתוך ימי זיבתה.\u0004 שאין הראייה שראתה בימים הללו מצטרפת לשתי ראיות אחרות שראתה, לקבוע על פי הראיות הללו את מועד וסתה. ומוסרים כי \u0003אמר רב יוסף,\u0004 כשנאמרו דברים אלה לפניו: \u0003לא שמיע\u0004 \u0005[נשמעה,\u0006 נמסרה\u0005]\u0006 \u0003לי\u0004 משמואל רבי \u0003הא שמעתתא\u0004 \u0005[הלכה זו].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: את\u0004 \u0005[אתה\u0006 עצמך\u0005]\u0006 \u0003אמרת\u0004 את ההלכה הזו \u0003ניהלן\u0004 \u0005[לנו],\u0006 \u0003ואהא\u0004 \u0005[ועל\u0006 ענין \u0005זה]\u0006 \u0003אמרת לן\u0004 \u0005[לנו]:\u0006 אם \u0003היתה\u0004 האשה \u0003למודה\u0004 (רגילה) \u0003להיות רואה\u0004 דם בכל \u0003יום חמשה עשר (יום),\u0004 והרי זה יום וסתה הקבוע, \u0003ושינתה\u0004 וראתה \u0003ליום עשרים\u0004 — הן ביום \u0003זה\u0004 (חמישה עשר) \u0003ו\u0004הן ביום \u0003זה\u0004 (עשרים) הריהם \u0003אסורין לשמש,\u0004 שיש לחשוש בשני הימים הללו שהם ימי וסתה. וכן אם \u0003שינתה פעמים ליום עשרים\u0004 — עדיין הן ביום \u0003זה\u0004 (חמישה עשר), יום וסתה הקבוע, \u0003ו\u0004הן ביום \u0003זה\u0004 (עשרים) הריהם \u0003אסורין\u0004 לשמש. עד שתראה פעם נוספת שלישית ליום עשרים, ותקבע בו את יום וסתה.","\u0003ו\u0004על כך \u0003אמרת לן עלה\u0004 \u0005[לנו עליה]\u0006 שכך \u0003אמר רב יהודה, אמר שמואל: לא שנא\u0004 \u0005[לא שנו]\u0006 בדבר זה של וסת קבוע בהפלגה של חמישה עשר ימים, \u0003אלא\u0004 ביום \u0003חמשה עשר לטבילתה, שהן עשרים ושנים\u0004 ימים \u0003לראיתה, דהתם\u0004 \u0005[ששם,\u0006 באופן זה\u0005]\u0006 \u0003בימי נדתה קאי לה\u0004 \u0005[עומדת היא],\u0006 \u0003אבל חמשה עשר לראיתה,\u0004 ש\u0003בימי זיבתה קאי\u0004 \u0005[עומדת]\u0006 היא — \u0003לא קבעה\u0004 בכך וסת קבועה.","ודנים עוד בענין זה שאין קביעת וסת בימי זיבה. \u0003אמר רב פפא, אמריתא לשמעתא קמיה\u0004 \u0005[אמרתי את ההלכה\u0006 הזו \u0005לפני]\u0006 \u0003רב יהודה מדסקרתא\u0004 ושאלתיו בבירורם של דברים: האם הכוונה היא כי דווקא לענין \u0003מקבע\u0004 \u0005[לקבוע\u0006 וסת\u0005]\u0006 היא \u0003לא קבעה\u0004 \u0005[אינה קובעת],\u0006 ואין צורך בראיית שלוש פעמים במועד אחר כדי לעוקרו. ואולם לענין \u0003מיחש\u0004 \u0005[חשש]\u0006 \u0003מהו\u0004 הדין \u0003דניחוש\u0004 \u0005[שנחשוש]\u0006 \u0003לה\u0004 לראייה זו כפעם אחת, וכדין הוסת שאינו קבוע?","\u0003אישתיק\u0004 \u0005[שתק]\u0006 רב יהודה מדסקרתא \u0003ולא אמר ליה\u0004 \u0005[לו\u0006 לרב פפא\u0005]\u0006 \u0003ולא מידי\u0004 \u0005[דבר].\u0006 כיון שכך, \u0003אמר רב פפא: נחזי אנן\u0004 \u0005[נראה אנחנו],\u0006 שכן שנינו: \u0003היתה למודה להיות רואה ליום חמשה עשר, ושינתה ליום עשרים\u0004 — \u0003זה וזה אסורין.\u0004"],["\u0003ו\u0004בהסבר דברי המשנה הללו \u0003אמר רב יהודה, אמר שמואל: לא שנא\u0004 \u0005[אינו שונה]\u0006 דין זה במי שהיתה רגילה לראות ליום חמישה עשר \u0003אלא\u0004 כאשר רגילה היתה אשה זו לראות ביום \u0003חמשה עשר ל\u0004יום \u0003טבילתה, שהן,\u0004 הימים מראייתה הקודמת לראייתה זו, עולים ל\u0003עשרים ושנים\u0004 יום \u0003לראייתה\u0004 (שהרי עברו שבעה ימים של נדות מיום שראתה עד יום שטבלה). \u0003ו\u0004כן מה ששנינו במשנה ש\u0003שינתה\u0004 ליום עשרים הכוונה היא שראתה \u0003ליום\u0004 עשרים מיום הטבילה, שמראייתה הקודמת לראייתה זו הם \u0003עשרים ושבעה\u0004 יום, ולא עשרים ושנים יום כהרגלה עד כה. ומעתה יימצא איפוא, \u0003דכי הדרי ואתו עשרין ותרתי\u0004 \u0005[שכאשר יחזרו ויבואו עשרים ושנים]\u0006 הימים של הפלגה מראייה לראייה, כדרך שהיא רגילה בא — היא \u0003קיימא\u0004 \u0005[עומדת]\u0006 \u0003לה בתוך\u0004 אחד עשר \u0003ימי זיבתה.\u0004 \u0003ו\u0004לענייננו: \u0003קתני\u0004 \u0005[שנינו]\u0006 במשנה זו כי הן יום \u0003זה\u0004 (של הפלגת עשרים ושנים ימים) \u0003ו\u0004הן יום \u0003זה\u0004 (של הפלגת עשרים ושבעה ימים) \u0003אסורין,\u0004 הגם שיום עשרים ושנים חל בימי זיבתה — \u0003אלמא דחיישינן\u0004 \u0005[הרי מכאן שחוששים אנו]\u0006 \u0003לה\u0004 לראייה שבימי הזיבה, וכדין וסת שאינו קבוע. \u0003ו\u0004מסבירים את הוכחתו זו של רב פפא: שכן \u0003קסבר\u0004 \u0005[סבור]\u0006 \u0003רב פפא\u0004 כי את מנין הימים של \u0003עשרין ותרתין\u0004 \u0005[עשרים ושנים]\u0006 ימי ההפלגה הללו — \u0003מעשרין ותרתין מנינן\u0004 \u0005[מ\u0006יום ה\u0005עשרים ושנים\u0006 שקדם לו \u0005אנו מונים],\u0006 בעוד שאת מנין הימים של טומאת \u0003נדה ופתחה\u0004 (שבעת ימי נדותה) — \u0003מ\u0004יום ה\u0003עשרין\u0004 \u0005[עשרים]\u0006 \u0003ושבעה מנינן\u0004 \u0005[מונים אנו],\u0006 שכן אין האשה פותחת במנין ימי נדותה אלא לאחר שראתה דם, ואשה זו לא ראתה אלא ביום העשרים ושבעה. ומעתה נמצא שיום הפלגת עשרים ושנים (מיום עשרים ושנים הקודם) הריהו חל בתוך ימי זיבתה. ואולם בדבר זה עצמו \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע\u0004 בשאלה \u0003לרב פפא: ממאי\u0004 \u0005[ממה,\u0006 מנין לנו שכך הוא המנין\u0005]?\u0006 \u0003דלמא\u0004 \u0005[שמא]\u0006 גם את מנין ימי ההפלגה של \u0003עשרין ותרתין\u0004 \u0005[עשרים ושנים]\u0006 ימים, \u0003נמי מעשרין ושבעה מנינן\u0004 \u0005[גם כן מ\u0006יום \u0005עשרים ושבעה אנו מונים],\u0006 ובאופן זה, \u0003דכי הדרי ואתו עשרין ותרתין\u0004 \u0005[שכאשר יחזרו ויבואו עשרים ושנים\u0006 ימי הפלגה אלה\u0005]\u0006 — נמצא שאשה זו \u0003קיימא\u0004 \u0005[עומדת]\u0006 \u0003לה בתוך ימי נדותה,\u0004 ולא בתוך ימי זיבתה. ואין להוכיח ממשנה זו לענין וסת בימי הזיבה. ומוסיף רב הונא בנו של רב יהושע לשאלתו: \u0003והכי נמי מסתברא\u0004 \u0005[וכך גם כן מסתבר]\u0006 לומר בכוונת דברי המשנה הללו. \u0003דאי לא תימא הכי\u0004 \u0005[ש\u0006הרי \u0005אם לא תאמר כך]\u0006 שמונים אנו את מנין ימי ההפלגה הללו מזמן שראתה, \u0003האי תרנגולתא\u0004 \u0005[זו התרנגולת]\u0006 המטילה ביצים, שהיתה רגילה \u0003דרמיא יומא וכבשה יומא\u0004 \u0005[שמטילה יום וכובשת\u0006 עוצרת מלהטיל \u0005יום],\u0006 \u0003ורמיא יומא וכבשה יומא\u0004 \u0005[ומטילה יום וכובשת יום],\u0006 וכגון שהיתה מטילה ביום ראשון, ועוצרת ביום השני, ומטילה שוב ביום השלישי בשבוע וכן הלאה. \u0003ו\u0004לאחר מכן שינתה את הרגלה, ולאחר שהטילה כדרכה בימים ראשון ושלישי בשבוע \u0003כבשה תרי יומי ורמיא חד יומא\u0004 \u0005[עצרה שני ימים, והטילה יום אחד],\u0006 שעצרה ביום הרביעי וביום החמישי, והטילה בששי, ומעתה נשאל:","","","","","\u0003כי הדרה נקטה\u0004 \u0005[כאשר\u0006 היא \u0005חוזרת אוחזת\u0006 במנהגה הקודם ומטילה יום ועוצרת יום\u0005],\u0006 כיצד היא תנהג, האם \u0003כדלקמיה נקטה\u0004 \u0005[כמה שלפניה,\u0006 כסדר הנפתח עתה היא \u0005אוחזת]\u0006 ולא תטיל בשבת (וכהרגלה שהריהי מטילה יום ועוצרת יום, וכיון שהטילה ביום ששי — לא תטיל בשבת). \u0003או\u0004 שמא הריהי \u0003כדמעיקרא נקטה\u0004 \u0005[כמו בתחילה,\u0006 כסדר הימים שהיתה רגילה בו בעבר, היא \u0005אוחזת],\u0006 שתטיל אף ביום שבת? \u0003על כרחך\u0004 ודאי ש\u0003כ\u0004סדר \u0003דלקמיה נקטה\u0004 \u0005[שלפניה אוחזת].\u0006 וכן הוא באשה זו, שמונה את ימי וסתה לא מזמן שהיתה רגילה לראות בו, אלא מהזמן שראתה בו ממש! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא\u0004 לרב הונא בנו של רב יהושע בדחיית דבריו: \u0003אלא\u0004 הלכה \u0003הא\u0004 \u0005[זו]\u0006 ש\u0003אמר ריש לקיש\u0004 כי \u0003אשה קובעת לה וסת בתוך ימי זיבתה, ואין אשה קובעת לה וסת בתוך ימי נדותה, ו\u0004אילו \u0003ר' יוחנן אמר אשה קובעת לה וסת בתוך ימי נדותה, היכי דמי\u0004 \u0005[כיצד המדובר]?\u0006","","והרי לא ראתה את כל ראיותיה בימי נדותה (שכן בכגון זה הכל מודים שאין האשה קובעת וסת בכך, ראה לעיל יא,א), אלא \u0003לאו\u0004 \u0005[האם לא]\u0006 המדובר \u0003כגון דחזאי\u0004 \u0005[שראתה]\u0006 פעם ראשונה ב\u0003ריש ירחא\u0004 \u0005[ראש חודש,\u0006 בא' בחודש\u0005],\u0006 \u0003ו\u0004לאחר מכן ראתה שוב ב\u0003חמשא בירחא\u0004 \u0005[בחמישה\u0006 בה' \u0005ב\u0006אותו \u0005חודש],\u0006 ובימי נדתה. \u0003ו\u0004לאחר מכן שוב ראתה בחודש הבא ב\u0003ריש ירחא\u0004 \u0005[ראש חודש,\u0006 ביום א' בו\u0005],\u0006 \u0003ו\u0004חזרה וראתה באותו חודש בימי נדתה ב\u0003חמשא בירחא\u0004 \u0005[בחמישה,\u0006 בה' \u0005בחודש],\u0006 \u0003והשתא\u0004 \u0005[ועתה,\u0006 בחודש השלישי\u0005]\u0006 אמנם \u0003חזאי בחמשא בירחא\u0004 \u0005[ראתה בחמישה,\u0006 ביום ה' \u0005בחודש], ו\u0006אילו \u0003בריש ירחא\u0004 \u0005[בראש חודש]\u0006 \u0003לא חזאי\u0004 \u0005[ראתה].\u0006 הרי זו איפוא וסת לימי החודש (שכן ראתה שלוש פעמים בה' בחודש). \u0003ו\u0004באופן זה \u0003קאמר\u0004 \u0005[הוא,\u0006 ר' יוחנן \u0005אומר]\u0006 כי \u0003אשה קובעת לה וסת בתוך ימי נדותה,\u0004 אף שהראייה שראתה ביום ה' שבחודש השלישי לא היתה בימי נדותה (שהרי לא ראתה בא' בחודש השלישי), מכל מקום נחשב הדבר כשלוש ראיות של ימי נדות — \u0003אלמא\u0004 \u0005[מכאן נסיק]\u0006 כי \u0003מריש ירחא מנינא\u0004 \u0005[מראש חודש מונים אנו],\u0006 אף שבראש חודש לא ראתה בפועל. ומכאן יש ללמוד גם לענין וסת הפלגה שמונים לא מיום שראתה בפועל אלא מיום שרגילה היתה לראות בו! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב הונא בנו של רב יהושע לרב פפא בדחיית דבריו: \u0003לא,\u0004 כך המדובר במקרה זה, אלא \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר'\u0004 \u0003יוחנן:\u0004 מדובר במקרה \u0003כגון דחזאי ריש ירחא\u0004 \u0005[שראתה\u0006 ב\u0005ראש חודש]\u0006 זה, \u0003ו\u0004חזרה וראתה בחודש הבא ב\u0003ריש ירחא\u0004 \u0005[\u0006ב\u0005ראש חודש],\u0006 \u0003ו\u0004שוב ראתה בחודש השני ב\u0003עשרין וחמשה בירחא\u0004 \u0005[עשרים וחמישה בחודש],\u0006 \u0003ו\u0004ראתה בחודש השלישי ב\u0003ריש ירחא\u0004 \u0005[ראש חודש],\u0006 שחל בתוך ימי נדתה. וסבור ר' יוחנן שהיא בתוך ימי נדתה, מכל מקום קובעת וסת על סמך ראייתה בראש החודש, משום \u0003דאמרינן\u0004 \u0005[שאומרים אנו]\u0006 בהסבר הראיה שראתה כבר בכ\"ה בחודש שאירע כן כי \u0003דמי יתירי\u0004 \u0005[דמים יתירים]\u0006 \u0003הוא דאתוספו\u0004 \u0005[שנוספו]\u0006 \u0003בה,\u0004 ולכך לא בטל יום וסתה שהוא בראש חודש.","","","ומוסרים: \u0003וכן כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין וכל נחותי ימא\u0004 \u0005[יורדי הים]\u0006 מארץ ישראל לבבל, והביאו עימם מדברי תורתו של ר' יוחנן, \u0003אמרוה\u0004 להלכה זו של ר' יוחנן, \u0003כ\u0004הסברו של \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע.\u0004",""],["הולד שנולד שלא כדרך הלידה הרגילה, דרך הרחם, אלא כ\u0003יוצא דופן\u0004 הרחם (לאחר חיתוכה) — אין דינו כילוד הרגיל לענין ישיבת ימי טומאה וטהרה עליו, ש\u0003אין יושבין עליו ימי טומאה וימי טהרה.\u0004 \u0003ו\u0004כמו כן \u0003אין חייבין עליו קרבן\u0004 יולדת, ככל אשה היולדת כדרך הלידה הרגילה. \u0003ר' שמעון אומר: הרי זה\u0004 נחשב \u0003כ\u0004כל \u0003ילוד\u0004 רגיל, ויושבים עליו ימי טומאה וימי טהרה, ומביאה עליו אמו קרבן יולדת.","ובדין טומאת הנדה וטומאת הזב ובעל קרי, \u0003כל הנשים מטמאות\u0004 (נטמאות) \u0003ב\u0004יציאת הדם ממקורו וכניסתו ל\u0003בית החיצון\u0004 (בית הערוה), אף שלא יצא אל מחוץ לגוף האשה, \u0003ש\u0004כך \u0003נאמר\u0004 בטומאת הנדה \u0003\"דם יהיה זבה בבשרה\u0004 שבעת ימים תהיה בנדתה\" (ויקרא טו, יט), ללמדנו, שאף שדם נדתה עדיין בתוכה (\"בבשרה\") חלה עליה טומאת נדה. \u0003אבל\u0004 שלא כדינה של הנדה, \u0003הזב ובעל קרי אינן מטמאין\u0004 (נטמאים) \u0003עד\u0004 (טרם) \u0003שתצא טומאתן\u0004 (זיבתו של הזב או קריו של בעל הקרי) \u0003לחוץ\u0004 מגופם.","ובדינו של בעל הקרי, \u0003היה אוכל בתרומה ו\u0004בתוך אכילתו \u0003הרגיש שנזדעזעו אבריו\u0004 (נסער גופו מתוך שנעקרה ממנו שכבת זרע), והרי בעל קרי מטמא את התרומה, ותיטמא איפוא התרומה שבפיו, ויצטרך לפולטה מפיו ולאבדה בכך. מה יעשה? — \u0003אוחז\u0004 בחוזקה \u0003באמה\u0004 (אבר זכרותו) כדי למנוע את פליטת הקרי אל מחוץ לגופו, וממהר \u0003ובולע את התרומה\u0004 כל עוד לא יצאה ועודנו טהור. \u0003ו\u0004עוד הלכה בדיני הזב ובעל הקרי: הזיבה והקרי \u0003מטמאין\u0004 את האדם שממנו יצאו \u0003בכל\u0004 שיעור \u0003שהוא,\u0004 ו\u0003אפילו\u0004 הרי זו טיפה זעירה שגודלה \u0003כעין\u0004 (כגון) גרגיר צמח \u0003החרדל ו\u0004אפילו \u0003ב\u0004שיעור \u0003פחות מכן.\u0004","במשנתנו נחלקו חכמים בדינו של הולד הנולד דרך הדופן, אם הריהו כולד רגיל לענין ימי טומאה וטהרה והבאת קרבן יולדת. ובהסבר השיטות, \u0003אמר ר'\u0004 \u0003מני בר פטיש: מאי טעמייהו דרבנן\u0004 \u0005[מה טעמם של חכמים]\u0006 הסבורים שאין נוהגים ביוצא דופן דיני היולדת ולד רגיל, שכן \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 בפרשת האשה היולדת \u0003\"אשה כי תזריע וילדה זכר\"\u0004 (ויקרא יב, ב) — \u0003עד שתלד\u0004 (שיצא הולד ממנה) \u0003במקום שהיא מזרעת\u0004 (מקבלת את הזרע ממנו נוצר העובר, ולא דרך הדופן).","\u0003ו\u0004אילו \u0003ר' שמעון\u0004 סבור שאף היולדת דרך דופן הריהי ככל אשה היולדת, מה לומד הוא מכתוב זה? \u0003ההיא\u0004 \u0005[אותו]\u0006 כתוב בא ללמדנו שחלים עליה דיני היולדת הרגילה \u0003אפילו\u0004 במקרה ש\u0003לא ילדה\u0004 ולד שלם, \u0003אלא\u0004 שנימוח הולד, והרי הוא \u0003כעין שהזריעה\u0004 כזרע בלבד — \u0003אמו טמאה לידה\u0004 ויושבת עליו ימי טומאה וימי טהרה, כשאר היולדות.","\u0003ו\u0004מעתה לבירור שיטת \u0003ר' שמעון\u0004 שבמשנתנו, \u0003מאי טעמיה\u0004 \u0005[מה טעמו]?\u0006 \u0003אמר ריש לקיש: אמר קרא\u0004 \u0005[המקרא]\u0006 בפרשת האשה היולדת \"ואם נקבה \u0003תלד\u0004 וטמאה שבועיים כנדתה\" (שם ה) — מקרא יתר זה (\"תלד\") בא \u0003לרבות\u0004 בדיני היולדת אף את היולדת \u0003יוצא דופן.\u0004","\u0003ו\u0004אילו \u0003רבנן\u0004 \u0005[חכמים],\u0006 מה הם לומדים מהמלה \"תלד\"? לדעתם \u0003האי מבעי ליה\u0004 \u0005[\u0006מקרא \u0005זה צריך אותו]\u0006 לענין אחר, \u0003לרבות\u0004 בדיני הלידה אף את היולדת ולד שהוא \u0003טומטום ו\u0004כן היולדת \u0003אנדרוגינוס.\u0004 ונדרש לכך לימוד מיוחד, משום \u0003דסלקא דעתך אמינא\u0004 \u0005[שהיה עולה\u0006 על \u0005דעתך לומר]\u0006 כי בדין היולדת \"וילדה \u0003זכר...\u0004 \u0003ו\u0004אם \u0003נקבה\u0004 תלד\" \u0003כתיב\u0004 \u0005[נאמר],\u0006 והרי זה מלמד שדיני היולדת אמורים דווקא ביולדת \u0003זכר ודאי, נקבה ודאית, ולא\u0004 ביולדת \u0003טומטום ואנדרוגינוס\u0004 לכן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 הכתוב הנוסף \"תלד\", שאף היולדת טומטום והאנדרוגינוס בכלל דיני היולדת.","ושואלים: \u0003ור' שמעון,\u0004 מנין לו דין זה? \u0003נפקא ליה\u0004 \u0005[יוצא,\u0006 נלמד \u0005לו]\u0006 דין זה \u0003מ\u0004תוך מה \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003בר ליואי.\u0004 \u0003דתני\u0004 \u0005[ש\u0006כן \u0005שנה]\u0006 \u0003בר ליואי:\u0004 נאמר בדין קרבן האשה היולדת \"ובמלאת ימי טהרה לבן או לבת\", ומתוך שלא אחז הכתוב בלשון \"זכר או נקבה\", הרי זה בא ללמד: \u0003\"לבן\"\u0004 — \u0003לבן מכל מקום,\u0004 ואף טומטום או אנדרוגינוס בכלל. וכיוצא בו, \u0003\"לבת\"\u0004 — \u0003לבת מכל מקום.\u0004","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 שלמדו דין הטומטום והאנדרוגינוס מהכתוב \"תלד\", מה למדים הם מהכתוב \"לבן או לבת\"? לדעתם \u0003האי מבעי ליה\u0004 \u0005[\u0006מקרא \u0005זה צריך אותו]\u0006 ללמדו דין אחר בדיני היולדת, \u0003לחייב\u0004 קרבן לידה נפרד \u0003על כל בן ובן\u0004 שילדה, שאין היא יכולה להביא קרבן אחד על בן זה שילדה עתה, ועל בן שנולד לה לאחר שהשלימה ימי טהרתה. \u0003ו\u0004בדומה לכך, \u0003לחייב\u0004 קרבן לידה נפרד \u0003על כל בת ובת\u0004 שילדה.","ושואלים: \u0003ור' שמעון\u0004 שלמד דין אחר מהכתוב \"לבן או לבת\", מנין למד הוא דין זה לחייב על כל בן ובן ועל כל בת ובת? ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא,\u0006 נלמד \u0005לו]\u0006 דין זה \u0003מ\u0004תוך מה \u0003דתני\u0004 \u0005[ששנה]\u0006 ה\u0003תנא קמיה\u0004 \u0005[חוזר המשניות לפני]\u0006 \u0003רב ששת:\u0004 נאמר בענין קרבן היולדת \u0003\"זאת תורת הילדת\"\u0004 (שם ז), ולשון כוללת זו (\"תורת היולדת\") \u0003מלמד שמביאה\u0004 היולדת \u0003קרבן אחד\u0004 אף \u0003על ולדות הרבה\u0004 שילדה. ויש לברר: \u0003יכול\u0004 ש\u0003תביא\u0004 היולדת קרבן אחד שיעלה לה \u0003על\u0004 ה\u0003לידה ועל זיבה כאחת?\u0004","ותוהים על עצם השאלה: \u0003אלא\u0004 מעתה תאמר שאף ה\u0003יולדת\u0004 ש\u0003אכלה דם, ו\u0004ה\u0003יולדת\u0004 ש\u0003אכלה חלב, בחד\u0004 \u0005[באחד]\u0006 \u0003קרבן\u0004 שהיא מביאה על לידתה \u0003תסגי\u0004 \u0005[תסתפק]\u0006 \u0003לה?\u0004","\u0003אלא\u0004 מסבירים שכך היתה השאלה: \u0003יכול תביא\u0004 היולדת קרבן לידה אחד \u0003על לידה שלפני מלאת\u0004 ימי טהרתה (שילדה בתוך תקופה זו) \u0003ועל לידה\u0004 נוספת \u0003ש\u0004ילדה \u0003לאחר מלאת\u0004 ימי טהרתה, \u0003כאחת,\u0004 שהרי זה וזה מחייבה בקרבן לידה? \u0003תלמוד לומר \"זאת\u0004 תורת היולדת\", למעט, שמביאה רק קרבן אחד במקרה זה. ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 שלמדו דין זה מ\"לבן או לבת\", מדוע אינם למדים זאת מהכתוב \"זאת\"? ומשיבים: \u0003אף על גב דכתיב\u0004 \u0005[אף על פי שנאמר]\u0006 \u0003\"זאת\"\u0004 עדיין \u0003איצטריך\u0004 \u0005[נצרך]\u0006 לימוד נוסף, מן הכתוב \u0003\"לבן או לבת\",\u0004 שכן","\u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה\u0006 על \u0005דעתך לומר]\u0006 שדין זה אמור רק \u0003בתרי עיבורי\u0004 \u0005[בשני עיבורים,\u0006 הריונות\u0005],\u0006 \u0003(דחד הוי\u0004 \u0005[שאחד היה]\u0006 \u0003נפל),\u0004 שילדה, וחזרה והתעברה בתוך ימי טהרתה, וילדה לאחר ימי טהרתה. שבמקרה זה צריכה האשה להביא על כל לידה קרבן בפני עצמו. \u0003אבל ב\u0004מקרה של \u0003חד עבורא\u0004 \u0005[עיבור אחד],\u0006 שנולדו הילדים בהפרש זמן ניכר, שנולד השני לאחר שמלאו ימי טהרתה ללידת הראשון, \u0003כגון\u0004 לידתם של האחים \u0003יהודה וחזקיה בני ר'\u0004 \u0003חייא,\u0004 שהשני נולד שלושה חודשים לאחר הראשון, \u0003אימר\u0004 \u0005[אמור]\u0006 כי \u0003בחד\u0004 \u0005[באחד]\u0006 \u0003קרבן סגי\u0004 \u0005[תסתפק]\u0006 \u0003לה\u0004 — \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 הכתוב \"לבן או לבת\", שחייבת להביא קרבן נפרד על כל לידה ולידה, אף במקרה כזה.","ובבירור שיטת ר' שמעון \u0003אמר ר'\u0004 \u0003יוחנן: ומודה ר'\u0004 \u0003שמעון\u0004 שאף שלענין היולדת, נחשבת לידה דרך דופן כלידה, אולם הולד היוצא דופן \u0003בקדשים\u0004 — \u0003שאינו קדוש\u0004 קדושת הגוף, אלא בקדושת דמים בלבד. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003גמר\u0004 \u0005[למד]\u0006 לשון \u0003לידה\u0004 שנאמר בקדשים (\"שור או כשב או עז כי יולד... ומיום השמיני והלאה ירצה לקרבן\". ויקרא כב, כז—כח), מלשון \u0003לידה, מ\u0004האמור ב\u0003בכור\u0004 (\"כל הבכור אשר יולד\". דברים טו, יט). \u0003מה התם\u0004 \u0005[שם,\u0006 בבכור\u0005]\u0006 אמרה תורה שאין הבכור מתקדש אלא כאשר הוא פטר רחם (יוצא מרחם אמו), (\"והעברת כל \u0003פטר רחם\u0004 לה' \". שמות יג, יב), \u0003אף כאן\u0004 בקדשים — אין הולד מתקדש אלא אם כן הוא \u0003פטר רחם,\u0004 ואילו היוצא דופן, אינו בכלל זה.","ושואלים: \u0003ולגמר\u0004 \u0005[וילמד]\u0006 ר' שמעון באופן שונה, מתוך השוואת הלשונות \u0003לידה לידה,\u0004 ואולם \u0003מ\u0004לידת \u0003אדם.\u0004 ויסיק כך: \u0003מה התם\u0004 \u0005[שם]\u0006 בלידת אדם — אף \u0003יוצא דופן\u0004 נחשב כילוד, \u0003אף כאן\u0004 בקדשים — ייחשב ה\u0003יוצא דופן\u0004 כילוד!","ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 כי \u0003מבכור הוה ליה למילף\u0004 \u0005[היה לו\u0006 לר' שמעון \u0005ללמוד]\u0006 את דין יוצא דופן בקדשים, \u0003שכן\u0004 עדיף ללמוד לענין שנאמר בו \u0003\"אמו\"\u0004 (בבכור — \"שבעת ימים יהיה עם אמו\", שמות כב, כט) \u0003מ\u0004ענין שאף בו נאמר \u0003\"אמו\"\u0004 (בקדשים — \"והיה שבעת ימים תחת אמו\", ויקרא כב, כז). ושואלים על כך: \u0003אדרבה\u0004 \u0005[להיפך],\u0006 \u0003מ\u0004לידה האמורה ב\u0003אדם הוה ליה למילף\u0004 \u0005[היה לו ללמוד],\u0006 \u0003שכן\u0004 ראוי ללמוד לידה האמורה בקדשים הכוללת גם לידת \u0003פשוט\u0004 (שאינו בכור), \u0003מ\u0004דיני לידה האמורה באדם שהריהי נוהגת בכל לידה שהיא, בין בכור ובין \u0003פשוט!\u0004","ומשיבים: \u0003אלא,\u0004 דווקא \u0003מ\u0004לידה האמורה ב\u0003בכור הוה ליה למילף\u0004 \u0005[היה לו ללמוד],\u0006 \u0003שכן\u0004 יש צדדים משותפים רבים בין קדשים ובין בכור: שבשניהם נאמרה בלידה הלשון \u0003אם;\u0004 ושניהם עוסקים בעניין זהה, ב\u0003בהמת קדשים;\u0004 ובשניהם נוהג דין \u0003פגול\u0004 ודין \u0003נותר ו\u0004דין \u0003טמא.\u0004","ודוחים: \u0003אדרבה\u0004 \u0005[להיפך],\u0006 \u0003מ\u0004לידה האמורה ב\u0003אדם הוה ליה למילף\u0004 \u0005[היה לו ללמוד],\u0006 \u0003שכן\u0004 יש צדדים משותפים לשניהם: שבלידת קדשים עניינה, זה שאינו בכור אלא \u0003פשוט,\u0004 ואף בלידת אדם עניינה אף בפשוט; וכמו כן, בין לידת קדשים ובין לידת אדם עניינם זכר ונקבה, ואילו בכור אינו אלא \u0003זכר\u0004 בלבד; וכמו כן בין לידת קדשים ובין לידת אדם עניינם דבר שאינו מתקדש מעצמו, ואילו בכור הריהו \u0003קדוש\u0004 מעצם היוולדו; וכן, שבין לידת קדשים ובין לידת אדם אינם מתנות כהונה, ואילו הבכור הריהו מכלל הניתנים \u0003במתנה\u0004 לכהן! ודוחים: \u0003הנך\u0004 \u0005[אלו]\u0006 הצדדים המשותפים ללידת קדשים ולידת בכור \u0003נפישן\u0004 \u0005[מרובים].\u0006 יותר מהצדדים המשותפים ללידת קדשים ולידת אדם.","\u0003אמר רב חייא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב הונא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: תניא דמסייע ליה\u0004 \u0005[שנויה\u0006 ברייתא \u0005שמסייעת לו]\u0006 \u0003לר' יוחנן.\u0004 ששנינו, \u0003ר' יהודה אומר:\u0004 נאמר בדין העולה \u0003\"זאת תורת העלה היא העלה\"\u0004 (ויקרא ו, ב) — \u0003הרי אלו שלשה מיעוטין,\u0004"],["\u0003פרט ל\u0004זו ש\u0003נשחטה בלילה, ו\u0004פרט לזו \u0003שנשפך דמה, ו\u0004לזו \u0003שיצא דמה חוץ לקלעים\u0004 — \u0003ש\u0004כל אחת מאלה, גם \u0003אם עלתה\u0004 למזבח, אינה מוקרבת, אלא \u0003תרד.\u0004","\u0003ר'\u0004 \u0003שמעון אומר:\u0004 כך יש לדרוש כתוב זה: מן האמור \u0003\"עלה\"\u0004 — \u0003אין לי\u0004 ללמוד שאם עלתה על המזבח לא תרד \u0003אלא\u0004 דווקא \u0003עולה כשרה, מנין לרבות\u0004 אף זו \u0003שנשחטה בלילה, ושנשפך דמה, ו\u0004כן זו \u0003שיצא דמה חוץ לקלעים, ו\u0004בשר קרבן \u0003הלן\u0004 מחוץ למזבח, \u0003ו\u0004הקרבן \u0003היוצא\u0004 אל מחוץ לעזרה וחזר והועלה על המזבח, \u0003ו\u0004הקרבן \u0003הטמא, ו\u0004בשר \u0003ה\u0004קרבן ש\u0003נותר\u0004 אחר זמן אכילתו הראוי, \u0003ו\u0004הקרבן \u0003שנשחט\u0004 במחשבה שייאכל \u0003חוץ לזמנו\u0004 הראוי, \u0003ו\u0004כן זה שנשחט במחשבה לאוכלו \u0003חוץ למקומו\u0004 הראוי,","\u0003ו\u0004כן זה \u0003שקבלו פסולין וזרקו את דמן, וה\u0004קרבנות שדמיהם צריכים להיות \u0003נתנין למעלה\u0004 מחוט הסיקרא שבאמצע המזבח, \u0003שנתנן למטה\u0004 מחוט הסיקרא, \u0003ו\u0004כן \u0003ה\u0004קרבנות שדמיהם צריכים להיות \u0003נתנין למטה שנתנן למעלה, והנתנין בחוץ שנתנן בפנים, והנתנין בפנים שנתנן בחוץ, ו\u0004קרבן \u0003הפסח ו\u0004קרבן \u0003החטאת ששחטן שלא לשמן, מנין\u0004 שאף כל אלו, אם עלו — לא ירדו?","\u0003תלמוד לומר \"זאת תורת העלה\"\u0004 (ויקרא ו, ב), \u0003ריבה תורה אחת לכל העולין\u0004 על המזבח, אף שנפסלו — \u0003שאם עלו, לא ירדו.\u0004","\u0003יכול שאני מרבה\u0004 בדין זה אף \u0003את\u0004 בהמת הקרבן שהיה \u0003רובע\u0004 את האשה, \u0003ו\u0004את הקרבן \u0003הנרבע, ו\u0004את \u0003ה\u0004קרבן שהוא \u0003מוקצה\u0004 (מיוחד) לעבודה זרה, \u0003ו\u0004את הנעבד בפועל לעבודה זרה, \u0003ו\u0004זה שניתן \u0003כאתנן\u0004 (תשלום לזונה), \u0003ו\u0004כן \u0003ה\u0004קרבן ששימש כ\u0003מחיר\u0004 של כלב, \u0003והכלאים\u0004 (הבא משני בעלי חיים), \u0003והטרפה, ויוצא דופן? תלמוד לומר \"זאת\"\u0004 למעט את אלו.","\u0003ו\u0004שואלים: \u0003מה ראית\u0004 (מדוע העדפת) \u0003לרבות\u0004 דווקא \u0003את אלו\u0004 (שנשחטה בלילה, ושנשפך דמה וכו') \u0003ולהוציא את אלו\u0004 (רובע, נרבע וכו'), ולא להיפך,"],["\u0003אחר שריבה הכתוב\u0004 פסולים מסויימים שאם עלו לא ירדו, \u0003ומיעט\u0004 פסולים אחרים שאין הם בכלל זה, ולא נאמר במפורש מיהם! ומשיבים: \u0003אמרת\u0004 כי \u0003מרבה אני\u0004 דווקא \u0003את אלו\u0004 (שנשחטה בלילה, שנשפך דמה וכו') שאם עלו לא ירדו — \u0003ש\u0004בכל אלה \u0003היה פסולן\u0004 רק משנכנסו \u0003בקדש\u0004 (במקדש), בעבודה במקדש. \u0003ומוציא אני\u0004 מכלל אלו שאם עלו לא ירדו \u0003את אלו\u0004 (הרובע, הנרבע וכו') — \u0003שלא היה פסולן בקדש,\u0004 אלא עוד לפני שנכנסו למקדש.","\u0003קתני מיהת\u0004 \u0005[על כל פנים שנינו]\u0006 בדברי ר' שמעון אלה אף את ה\u0003יוצא דופן\u0004 בין אלה ש\u0003לא\u0004 קרבים, אף אם עלו. \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה ל\u0003יוצא דופן\u0004 של \u0003קדשים,\u0004 והרי זו איפוא ראיה לדברי ר' יוחנן שמודה ר' שמעון שיוצא דופן פסול בקדשים. \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של רב נתן: לא, הכוונה ל\u0003יוצא דופן\u0004 של \u0003בכור,\u0004 שאינו מתקדש אלא אם כן הוא בכלל \"פטר רחם\". ואין אם כן ראיה לדברי ר' יוחנן בשיטת ר' שמעון, ולדעת ר' שמעון אם כן יוצא דופן בקדשים הריהו קדוש.","ותוהים על כך: והרי אין למדים שיוצא דופן ב\u0003בכור\u0004 אינו קדוש מהכתוב \"זאת\" שבפסוק \"זאת תורת העולה\" (ויקרא ו, ב), אלא \u0003מ\u0004האמור בדין הבכור עצמו \"והעברת כל \u0003פטר רחם\u0004 לה' \" (שמות יג, יב) \u0003נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005]\u0006 דינו!","ומשיב על כך רב הונא בנו של רב נתן: \u0003אלא מאי\u0004 \u0005[מה]\u0006 תאמר, שהכוונה בדברי ר' שמעון בברייתא זו, היא למעט יוצא דופן של \u0003קדשים?\u0004 והרי דבר זה \u0003מ\u0004ההיקש \u0003\"אמו\"\u0004 (האמור בבכור — \"שבעת ימים יהיה עם אמו\", שמות כב, כט), \u0003\"אמו\"\u0004 (האמור בקדשים — \"והיה שבעת ימים תחת אמו\", ויקרא כב, כז) \u0003נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005]!\u0006","ומשיבים על דבריו אלו: \u0003האי מאי\u0004 \u0005[זה מהו]?\u0006 \u0003אי אמרת בשלמא\u0004 \u0005[נוח\u0006 הדבר \u0005אם אומר אתה]\u0006 שדברי ר' שמעון אלו שבברייתא הם ביוצא דופן של \u0003קדשים\u0004 — \u0003היינו דאצריכי תרי קראי\u0004 \u0005[זהו\u0006 הטעם \u0005שנצרכים שני מקראות],\u0006 \u0003חד\u0004 \u0005[\u0006מקרא \u0005אחד]\u0006 — \u0003לבהמת חולין דאוליד\u0004 \u0005[שילדה]\u0006 \u0003דרך דופן, ואקדשה\u0004 \u0005[והקדישה]\u0006 בעליה את הולד, ללמדנו שאינו קדוש.","\u0003וחד\u0004 \u0005[ו\u0006מקרא \u0005אחד]\u0006 — \u0003לבהמת קדשים דאוליד\u0004 \u0005[שילדה]\u0006 \u0003דרך דופן,\u0004 שאין הולד הזה קדוש, \u0003וקסבר\u0004 \u0005[וסבור הוא]\u0006 ר' שמעון ככלל כי \u0003ולדות קדשים בהוייתן\u0004 (בהתהוותם, ביציאתם מרחם אמם) \u0003הן קדושים,\u0004 ואילו יוצא דופן של בהמת קדשים, אינו קדוש. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שר' שמעון בברייתא זו מדבר על יוצא דופן של \u0003בכור\u0004 — \u0003מ\"פטר רחם\" נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005]\u0006 דינו, ואין צורך בכתוב נוסף להשמיענו דין זה!","ומסכמים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם מסתבר]\u0006 לומר שדברי ר' שמעון שבברייתא עוסקים בולדות קדשים, שכן יש צורך בשני מקראות בעניינם של אלו, \u0003מדקתני\u0004 \u0005[מ\u0006מה \u0005ששנינו]\u0006 עוד באותה ברייתא \u0003הרובע והנרבע והמוקצה והנעבד והכלאים,\u0004 ויש לשאול בכל אלה: וכי","\u0003הני מהכא נפקא\u0004 \u0005[אלו מכאן\u0006 דינם \u0005יוצא,\u0006 נלמד\u0005]\u0006 שהם פסולים, והלא \u0003מהתם נפקא\u0004 \u0005[משם יוצא,\u0006 נלמד\u0005]\u0006 דינם, ממה שנאמר בכתוב \"אדם כי יקריב מכם קרבן לה' מן הבהמה מן הבקר ומן הצאן תקריבו את קרבנכם\" (ויקרא א, ב), ונדרשו פרטי הדברים כך: \u0003\"מן הבהמה\"\u0004 — \u0003להוציא\u0004 (למעט) את \u0003הרובע והנרבע,\u0004 שהוא פסול לקרבן. \u0003\"מן הבקר\"\u0004 — \u0003להוציא את הנעבד.\u0004 \u0003\"מן הצאן\"\u0004 — \u0003להוציא את המוקצה.\u0004 ומה שנאמר \u0003\"ומן הצאן\"\u0004 בתוספת וא\"ו — \u0003להוציא את הנוגח\u0004 שהמית אדם בנגיחתו.","\u0003ותו\u0004 \u0005[ועוד]\u0006 יש לשאול: וכי \u0003כלאים\u0004 הנזכרים אף הם בדברי ר' שמעון שבברייתא \u0003מהכא נפקא\u0004 \u0005[מכאן יוצא,\u0006 נלמד דינם\u0005]\u0006 שהם פסולים, והלא \u0003מהתם נפקא\u0004 \u0005[משם,\u0006 ממקום אחר \u0005יוצא,\u0006 נלמד\u0005]\u0006 דינם, וכמו ששנינו: \u0003\"שור או כשב או עז...\u0004 ומיום השמיני והלאה ירצה לקרבן\" (שם כב, כז), ולמדנו מפרטי הדברים שבכתוב: \u0003\"שור\"\u0004 — \u0003פרט לכלאים\u0004 (הבא משני מיני בעלי חיים). \u0003\"או עז\"\u0004 — \u0003פרט לנדמה\u0004 (הנולד לעיזים, ונראה ככבש)!","\u0003אלא\u0004 יש לומר כי \u0003אצטריכו תרי קראי\u0004 \u0005[נצרכים שני מקראות]\u0006 לכל אלו: \u0003חד\u0004 \u0005[\u0006מקרא \u0005אחד]\u0006 — \u0003לבהמת חולין, וחד\u0004 \u0005[ו\u0006מקרא \u0005אחד]\u0006 — \u0003לבהמת קדשים, הכא נמי\u0004 \u0005[כאן\u0006 ביוצא דופן גם כן] יש לומר כי \u0003איצטריך תרי קראי\u0004 \u0005[נצרכים שני מקראות],\u0006 ולמדנו איפוא כדברי ר' יוחנן בשיטת ר' שמעון, שמודה ר' שמעון ביוצא דופן בקדשים, שאינו קדוש.","ועוד בבירור השיטות במשנתנו, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אשה \u0003המקשה\u0004 ללדת, ובתוך צער הלידה ראתה דם במשך \u0003שלשה ימים, ו\u0004לאחר מכן \u0003יצא\u0004 ה\u0003ולד דרך דופן\u0004 — \u0003הרי זו\u0004 נחשבת \u0003יולדת בזוב,\u0004 שדינה כזבה רגילה. שאף שאשה המקשה ללדת וראתה דם אינה נחשבת זבה, אינו אלא ביולדת כדרכה, ולא ביולדת דרך דופן. \u0003ור' שמעון אומר: אין זו\u0004 נחשבת \u0003יולדת בזוב,\u0004 אלא אף זו נחשבת כלידה. \u0003ו\u0004עוד נחלקו, בדינו של ה\u0003דם היוצא משם,\u0004 שלדעת חכמים הריהו \u0003טמא, ו\u0004אילו \u0003ר' שמעון מטהר\u0004 דם זה.","ודנים בדבר, \u0003בשלמא רישא\u0004 \u0005[נוחה,\u0006 מובנת היא \u0005תחילת\u0006 הברייתא\u0005]\u0006 במחלוקת הראשונה שבין חכמים לר' שמעון, שכן הן \u0003ר' שמעון\u0004 הולך בה \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 במשנה, שלידת יוצא דופן נחשבת כלידת ולד רגיל, \u0003ו\u0004הן \u0003רבנן\u0004 \u0005[חכמים]\u0006 הולכים בה \u0003לטעמייהו\u0004 \u0005[לטעמם,\u0006 לשיטתם\u0005]\u0006 במשנה, שלידת יוצא דופן אינה נחשבת כלידת ולד רגיל. \u0003אלא\u0004 בענין המחלוקת בין חכמים לר' שמעון ב\u0003סיפא\u0004 \u0005[סוף\u0006 הברייתא\u0005]\u0006 יש לברר: \u0003במאי פליגי\u0004 \u0005[במה\u0006 הם \u0005חולקים]?\u0006 \u0003אמר רבינא:\u0004 במקרה \u0003כגון שיצא\u0004 ה\u0003ולד\u0004 עצמו \u0003דרך\u0004 ה\u0003דופן,\u0004"],["\u0003ו\u0004אולם ה\u0003דם,\u0004 שהוא דם הקישוי בשלושת הימים שלפני הלידה, יצא \u0003דרך\u0004 ה\u0003רחם.\u0004 \u0003ואזדא\u0004 \u0005[והולך]\u0006 \u0003ר' שמעון\u0004 אף בהלכה זו \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 שהנולד יוצא דופן הריהו כשאר הנולדים, ולכן גם דם קישוי היוצא לפני לידת יוצא דופן הריהו כדם קישוי היוצא לפני לידת ולד רגיל, וטהור הוא, \u0003ו\u0004כמו כן אף \u0003רבנן\u0004 \u0005[חכמים]\u0006 הולכים בהלכה זו \u0003לטעמייהו\u0004 \u0005[לטעמם,\u0006 לשיטתם\u0005],\u0006 שיוצא דופן אינו נחשב לענין זה כילוד, ודם קישוי שקודם ללידה זו טמא הוא.","\u0003מתקיף לה\u0004 \u0005[מקשה עליה,\u0006 על הסבר זה\u0005]\u0006 \u0003רב יוסף:\u0004 אין לומר כן בהסבר הברייתא, משני טעמים: \u0003חדא\u0004 \u0005[האחד]\u0006 — \u0003דהיינו רישא\u0004 \u0005[שהרי זה,\u0006 המקרה המתואר ב\u0005ראשית\u0006 הברייתא\u0005],\u0006 שעניינה דם קישוי היוצא לפני לידת יוצא דופן. \u0003ועוד,\u0004 הלשון הנזכרת בסוף הברייתא \"דם היוצא \u0003משם\"\u0004 — מה \u0003מקום\u0004 שיצא ממנו ה\u0003ולד משמע,\u0004 ולא שיצא הולד דרך הדופן, והדם דרך הרחם!","\u0003אלא אמר רב יוסף\u0004 בהסבר סוף הברייתא: מדובר ב\u0003כגון שיצא\u0004 הן ה\u0003ולד ו\u0004הן ה\u0003דם דרך\u0004 ה\u0003דופן.\u0004","ואף שאין הדם היוצא דרך הדופן מטמא כשלעצמו בטומאת הנדה ובטומאת הזיבה, יש לדון בדינו, \u0003ו\u0004בשאלה \u0003במקור\u0004 האם \u0003מקומו טמא קמיפלגי\u0004 \u0005[הם חולקים],\u0006 ובאופן זה, \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 חכמים, \u0005סבורים]\u0006 כי \u0003מקור מקומו טמא,\u0004 ולכן אף שיצא הדם דרך הדופן הריהו טמא, כיון שנגע במקור. ואילו \u0003מר סבר וחכם זה,\u0004 ר' שמעון, \u0005סבור]\u0006 כי \u0003מקור מקומו טהור,\u0004 ולכן לדעתו אף שנגע הדם במקור כיון שיצא שלא דרך הרחם הריהו טהור.","ועוד בהבנת השיטות בברייתא זו, \u0003אמר ריש לקיש: לדברי\u0004 \u0003המטמא בדם\u0004 היוצא מהדופן (חכמים), הריהו \u0003מטמא באשה\u0004 טומאת נדה, שטמאה טומאת שבעה, ולא טומאת מגע בלבד, שהיא לערב. ואילו \u0003לדברי המטהר בדם\u0004 היוצא מהדופן (ר' שמעון) — הריהו \u0003מטהר באשה\u0004 מטומאת הנדה. \u0003ו\u0004אילו \u0003ר' יוחנן אמר: אף לדברי המטמא בדם\u0004 היוצא מהדופן (חכמים) — \u0003מטהר באשה,\u0004 שאינה נטמאת בדם זה משום נדה.","\u0003ואזדא\u0004 \u0005[והולך]\u0006 בכך \u0003ר' יוחנן לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 שכן \u0003אמר ר'\u0004 \u0003יוחנן משום\u0004 \u0005[בשם]\u0006 \u0003ר' שמעון בן יוחי: מנין שאין\u0004 ה\u0003אשה\u0004 נחשבת \u0003טמאה\u0004 בטומאת נדה או בטומאת זיבה, \u0003עד שיצא מדוה\u0004 (הדבר המטמא) \u0003דרך ערותה\u0004 — \u0003ש\u0004כן \u0003נאמר\u0004 בפרשת איסורי העריות \u0003\"ואיש אשר ישכב את אשה דוה וגלה את ערותה את מקורה הערה\"\u0004 (ויקרא כ, יח) — \u0003מלמד שאין אשה\u0004 נעשית \u0003טמאה עד שיצא מדוה דרך ערותה.\u0004 ולכך הדם היוצא דרך הדופן, אינו מטמא בטומאת הנדה.","כיון שהוזכר המקור, מביאים עוד מה ש\u0003אמר ריש לקיש משום\u0004 \u0005[בשם]\u0006 \u0003ר' יהודה נשיאה: מקור\u0004 (רחם האשה) \u0003שנעקר\u0004 חלק ממנו, \u0003ונפל לארץ\u0004 כחתיכת בשר — האשה \u0003טמאה\u0004 בכך, \u0003ש\u0004כן \u0003נאמר\u0004 בתיאור תועבות ירושלים כדרך האשה המזנה \u0003\"יען השפך נחשתך ותגלה ערותך\"\u0004 (יחזקאל טז, לו), הרי שאף שיצא חלק מהמקור ארצה (\"השפך נחושתך\") עדיין נחשב הוא כ\"ערוה\".","ומבררים: \u0003למאי\u0004 \u0005[למה,\u0006 לאיזה ענין\u0005]\u0006 נחשבת אשה זו כטמאה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003ל\u0004ענין שתיטמא בו האשה \u0003טומאת שבעה\u0004 כנדה — אין לומר כן, שהרי בדין הנדה \u0003אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 \"ואשה כי תהיה זבה \u0003דם\u0004 יהיה בבשרה שבעת ימים תהיה בנדתה\" (ויקרא טו, יט), להורות: דווקא בדם היא נטמאת, \u0003ולא\u0004 ב\u0003חתיכה\u0004 הבאה מהמקור! \u0003אלא\u0004 אמר ר' יוחנן לענין שנטמאה האשה בנגיעתה בחתיכת מקור זו בזמן שיצאה ממנה, אלא \u0003לטומאת ערב\u0004 בלבד, ככל הנוגע בנדה.","ועוד בדינו של המקור, \u0003אמר ר'\u0004 \u0003יוחנן: מקור שהזיע\u0004 (ביצבץ) דם לבן וצלול \u0003כ\u0004מראה \u0003שתי טיפי מרגליות\u0004 — \u0003טמאה\u0004 בו האשה הרואה. ומבררים: \u0003למאי\u0004 \u0005[למה,\u0006 לאיזה ענין\u0005]\u0006 אמר ר' יוחנן את דבריו אלו, \u0003אילימא\u0004 \u0005[אם תאמר ]\u0006 \u0003ל\u0004ענין שתיטמא האשה במראה זה \u0003טומאת שבעה\u0004 ימים כנדה — אין לומר כן, שהרי שנינו במסכתנו (פרק שני) כי רק \u0003חמשה דמים טמאין\u0004 יש \u0003באשה ותו\u0004 \u0005[ויותר]\u0006 \u0003לא,\u0004 ודם זה אינו נמנה בין החמישה! \u0003אלא\u0004 אמר ר' יוחנן דבריו אלה \u0003ל\u0004ענין \u0003טומאת ערב,\u0004 מפני שנגעו טיפות אלה במקור, וכיון שנגעה בהן האשה נטמאה. ומסייגים: \u0003ודווקא\u0004 שהיו אלה \u0003תרתי\u0004 \u0005[שתיים]\u0006 טיפות, \u0003אבל\u0004 בטיפה \u0003חדא\u0004 \u0005[אחת]\u0006 — אין האשה נטמאת בה, שכן \u0003אימא מעלמא אתיא\u0004 \u0005[\u0006יש מקום \u0005לומר\u0006 כי \u0005מהעולם,\u0006 מחוץ למקור היא \u0005באה].\u0006","שנינו במשנתנו כי \u0003כל הנשים מטמאין\u0004 (נטמאות) בטומאת הנדה \u0003ב\u0004יציאת הדם מהמקור והגעתו ל\u0003בית החיצון.\u0004 ומבררים: \u0003הי ניהו\u0004 \u0005[איזהו הוא]\u0006 בדיוק המקום בגוף האשה המכונה \u0003\"בית החיצון\"? אמר ריש לקיש: כל\u0004 מקום פתח הרחם \u0003ש\u0004בשעה שה\u0003תינוקת יושבת,\u0004 מתרחב במקצת \u0003ונראת,\u0004 הוא הקרוי בית החיצון.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן\u0004 לריש לקיש, אין זה כדבריך, שהרי בטומאת הנדה נאמר \"דם יהיה בבשרה\" (ויקרא טו, יט), שטמאה היא בדם בעודו מצוי בתוך גופה (\"בבשרה\"), ואילו \u0003אותו מקום\u0004 שהגדרת נחשב כמקום גלוי, וכפי שמצאנו שכ \u0003גלוי הוא\u0004 נחשב \u0003אצל\u0004 (בענין) טומאת נגיעה ב\u0003שרץ,\u0004 שאף שאין מגע השרץ מטמא בבית הסתרים, מקום זה הריהו בכלל המקומות הגלויים! \u0003אלא אמר ר'\u0004 \u0003יוחנן:\u0004 \"בית החיצון\" שנטמאת בו האשה בנדה, הוא המקום במרחב שבין צידו החיצוני של גוף האשה \u0003עד בין השינים\u0004 (גבשושיות בשר מוגבהות בתוך הרחם).","בעקבות דברי ר' יוחנן אלה, \u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 ללומדי בית המדרש\u0005]\u0006 שאלה זו: האם מקום \u0003בין השינים\u0004 עצמם נחשב \u0003כלפנים\u0004 (כלפי המקור), \u0003או כלחוץ\u0004 (כלפי הצד החיצון של הגוף)? ומביאים ראיה, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003ר' זכאי\u0004 במפורש: כל המקום שמצידו החיצון של גוף האשה ו\u0003עד בין השינים\u0004 — דם הנמצא בו מטמא. ואילו המקום ש\u0003בין השינים עצמן\u0004 — נחשב \u0003כלפנים,\u0004 ואינו מטמא.","ובענין הגדרת \"בית החיצון\" שנטמאת בו האשה, מביאים עוד, כי \u0003במתניתא תנא\u0004 \u0005[בברייתא שנינו]:\u0006 \"בית החיצון\" הרי זה \u0003מקום דישה.\u0004 ומסבירים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מקום דישה\"? אמר רב יהודה:\u0004 ה\u0003מקום\u0004 ברחם האשה \u0003ש\u0004בשעת תשמיש \u0003השמש\u0004 (כינוי לאבר זכרות) \u0003דש\u0004 (נוגע) בו.","ועוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר בטומאת הנדה \"אשה כי תהיה זבה דם יהיה זובה \u0003בבשרה\u0004 שבעת ימים תהיה בנדתה\" (ויקרא טו, יט) — \u0003מלמד שמטמאה\u0004 (שנטמאת) בטומאת הנדה בדם שיצא מן המקור ונמצא \u0003בפנים\u0004 גופה \u0003כ\u0004בדם ש\u0003בחוץ.\u0004 \u0003ואין לי\u0004 שנוהג דין זה \u0003אלא\u0004 בטומאת ה\u0003נדה,\u0004 ה\u0003זבה מנין\u0004 — \u0003תלמוד לומר\u0004 (מלמדנו האמור) באותו פסוק \u0003\"זבה בבשרה\",\u0004 שאף האשה הזבה בכלל זה.","ושואלים עוד: \u0003פולטת שכבת זרע\u0004 שנטמאת בכך בטומאת ערב, \u0003מנין\u0004 לי שאף היא אם פלטה לבית החיצון, נטמאה — \u0003תלמוד לומר\u0004 בכתוב זה \u0003\"יהיה\",\u0004 לרבות כל המטמא אותה, שכשהוא בבית החיצון הריהי נטמאת בכך. \u0003ו\u0004אילו \u0003ר' שמעון אומר:\u0004 אין האשה שפלטה שכבת זרע לבית החיצון נטמאת בכך, אלא משעה שיצאה שכבת הזרע אל מחוץ לגופה. שכן \u0003דיה\u0004 לאשה בטומאה זו שתהיה \u0003כבועלה\u0004 (האיש), שהביא עליה טומאה זו, שלא תהיה חמורה ממנו. \u0003מה בועלה\u0004 — \u0003אינו מטמא\u0004 בהוצאת שכבת זרע, \u0003עד\u0004 \u0003שתצא\u0004 ה\u0003טומאה לחוץ\u0004 מגופו, \u0003אף היא,\u0004 האשה — \u0003אינה מטמאה\u0004 בפליטת שכבת זרע \u0003עד שתצא טומאתה לחוץ.\u0004","ומקשים: \u0003וסבר\u0004 \u0005[וכי סבור]\u0006 \u0003ר' שמעון\u0004 שאומרים כלל זה ש\u0003דיה\u0004 לטומאת אשה שתהיה \u0003כ\u0004טומאת \u0003בועלה? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 על האמור באיש שיצאה ממנו שכבת זרע \"ואשה אשר ישכב איש אותה שכבת זרע \u0003ורחצו במים וטמאו עד הערב\"\u0004 (ויקרא טו, יח), \u0003אמר ר'\u0004 \u0003שמעון: וכי מה בא\u0004 כתוב \u0003זה ללמדנו? אם לענין\u0004 ה\u0003נוגע בשכבת זרע\u0004 שנטמא טומאת ערב — \u0003הרי\u0004 דבר זה \u0003כבר נאמר למטה\u0004 (להלן, ויקרא כב, ד) בכתוב \u0003\"או איש\u0004 אשר תצא ממנו שכבת זרע\", ללמד שהנוגע בשכבת זרע נטמא.","\u0003אלא\u0004 מלמדנו הכתוב שאשה שנבעלה נטמאת בשכבת זרע של בועלה, אף שנגעה בה שכבת זרע זו בתוך גופה. ואף שלא היתה צריכה להיטמא ממנה \u0003מפני שטומאת בית הסתרים היא, ו\u0004כלל הוא ש\u0003טומאת בית הסתרים אינה מטמאה, אלא שגזרת הכתוב הוא\u0004 שהאשה הנבעלת נטמאת אף באופן זה. הרי שלשיטת ר' שמעון נטמאת האשה בשכבת זרע בבית הסתרים, וחמורה היא איפוא מבועלה, שהוא נטמא בשכבת זרע רק משיצאה מגופו!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 שיש להבחין בין המקרים, \u0003כאן\u0004 ששנינו שחמור דינה של הנבעלת מבועלה — הרי זה \u0003במשמשת,\u0004 שגזירת הכתוב היא שהאשה נטמאת אף בבית הסתרים. \u0003כאן\u0004 ששנינו שדיה שתטמא כבועלה — \u0003בפולטת\u0004 שכבת זרע, שאינה מטמאת בבית הסתרים, אלא משיצאה שכבת הזרע לחוץ, כבועלה.","ותוהים: זו ה\u0003פולטת\u0004 שכבת זרע — ודאי נטמאת, שכן \u0003תיפוק ליה\u0004 \u0005[תצא לו]\u0006 הלכה זו שהיא טמאה, \u0003דהא\u0004 \u0005[שהרי]\u0006 לפני שפלטה האשה היא \u0003שמשה\u0004 עם בעלה, ונטמאה בכך! ומשיבים: צריך להשמיענו שהיא טמאה \u0003ב\u0004מקרה \u0003שטבלה ל\u0004אחר \u0003שמושה\u0004 ונטהרה מטומאת תשמישה, ולאחר מכן פלטה שכבת זרע.","ושואלים: \u0003למימרא\u0004 \u0005[האם לומר\u0006 מכאן\u0005]\u0006 שה\u0003משמשת, בטומאת ערב סגי\u0004 \u0005[די]\u0006 \u0003לה? והא\u0004 \u0005[והרי]\u0006 \u0003אמר רבא: משמשת\u0004 — \u0003כל שלשה ימים\u0004 שלאחר התשמיש \u0003אסורה לאכול בתרומה,\u0004 משום \u0003שאי אפשר לה שלא תפלוט\u0004 משכבת הזרע, ותיטמא בה!","ומתרצים: דינו זה של ר' שמעון שהאשה הפולטת שכבת זרע נטמאת רק ביציאתה אל מחוץ לגופה, מתייחס למקרה מסויים, \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003ש\u0004לאחר ששימשה, \u0003הטבילוה\u0004 לטהרתה, בעת שהיא \u0003במטה.\u0004 שכיון שלא קמה ממיטתה, אין לחשוש בה שפלטה משכבת הזרע שבה, ונטהרה בטבילתה, ומותרת באכילת תרומה. ושואלים: הרי שאם קמה מן המיטה חוששים שפלטה, \u0003מכלל דכי קאמר\u0004 \u0005[מכאן שכאשר אמר]\u0006 \u0003רבא\u0004 שאי אפשר שלא תפלוט שכבת זרע בשלושת הימים שלאחר התשמיש, הרי זה מדובר במקרה \u0003דאזלה איהי בכרעה\u0004 \u0005[שהלכה היא\u0006 עצמה \u0005ברגליה]\u0006 \u0003וטבלה,\u0004 ולא שהטבילוה אחרים בהיותה במיטה, ואולם במקרה זה יש לחשוש: \u0003דילמא בהדי דקאזלה שדיתא\u0004 \u0005[שמא בתוך הליכתה\u0006 זו לטבול \u0005פלטה]\u0006 את שכבת הזרע שבה, ולאחר שטבלה לטהרתה ונטהרה, שוב לא תפלוט ולא תיטמא שוב, ומדוע אסרה רבא באכילת תרומה?"],["\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שזה שאסרה רבא לאכול בתרומה הוא רק משום החשש \u0003דילמא אשתייר\u0004 \u0005[שמא נשתייר]\u0006 בתוכה משכבת הזרע לאחר שטבלה — אין לומר כן, שהרי \u0003אי הכי\u0004 \u0005[אם כך]\u0006 היא כוונת דבריו, בלשון \u0003\"חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא נשתייר\" מבעי ליה\u0004 \u0005[נצרך לו]\u0006 לומר, ולא בלשון ודאית \"שאי אפשר לה שלא תפלוט\"!","\u0003אלא\u0004 יש לומר כי \u0003ל\u0004שיטת \u0003רבא נמי\u0004 \u0005[גם כן]\u0006 מדובר במקרה \u0003שהטבילוה\u0004 לאחר ששימשה, כשהיא נתונה \u0003במטה,\u0004 ומאחר שברור שלא פלטה, ודאי שתפלוט לאחר הטבילה. \u0003ולא קשיא\u0004 \u0005[קשה]\u0006 מדבריו אלו של רבא על שיטת ר' שמעון, שכן יש להבדיל בין המקרים השונים: \u0003כאן\u0004 בדברי רבא, מדובר \u0003ב\u0004אשה שלאחר טבילתה הריהי \u0003מתהפכת\u0004 במיטתה מצד זה של גופה לצידה האחר לאחר התשמיש, ומתוך שהיא מתהפכת ודאי שהיא פולטת את שכבת זרע שבתוכה. ואילו \u0003כאן\u0004 בדברי ר' שמעון מדובר \u0003ב\u0004זו \u0003ש\u0004שוכבת במיטתה ו\u0003אינה מתהפכת\u0004 לאחר תשמיש. שזו שטבלה ונטהרה מטומאת התשמיש, אינה נטמאת משכבת זרע, אלא משיצא אל מחוץ לגופה, וכדינו של בועלה.","\u0003ורבא\u0004 שאמר את דבריו, \u0003אקרא קאי\u0004 \u0005[על המקרא\u0006 הוא \u0005עומד,\u0006 מתייחס\u0005],\u0006 \u0003והכי קאמר\u0004 \u0005[וכך הוא אומר]\u0006 בהסבר הכתוב: \u0003כי כתב רחמנא\u0004 \u0005[כאשר אמרה התורה]\u0006 בדין שכבת הזרע בתשמיש \"ואשה אשר ישכב איש אותה שכבת זרע \u0003ורחצו במים וטמאו עד הערב\"\u0004 (ויקרא טו, יח) — הרי זה דווקא \u0003ב\u0004זו \u0003ש\u0004שוכבת במיטתה לאחר טבילתה ו\u0003אינה מתהפכת, אבל במתהפכת\u0004 — \u0003כל שלשה ימים אסורה לאכול בתרומה,\u0004 משום \u0003שאי אפשר לה שלא תפלוט.\u0004","ועוד בענין האשה הפולטת שכבת זרע, \u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רב שמואל בר ביסנא מאביי:\u0004 האשה ה\u0003פולטת שכבת זרע,\u0004 משום מה היא טמאה, האם משום שכ \u0003רואה\u0004 דם \u0003הויא\u0004 \u0005[הריהי]\u0006 נחשבת, \u0003או\u0004 משום שכ \u0003נוגעת\u0004 בטומאה \u0003הויא\u0004 \u0005[הריהי]\u0006 נחשבת?","ומעירים: ו\u0003נפקא מינה\u0004 \u0005[יוצא ממנה,\u0006 משאלה זו הבדל הלכה למעשה\u0005]\u0006 לכמה עניינים: האם יש \u0003לסתור\u0004 (לבטל) ולהתחיל מחדש את ספירת שבעת ימי הנקיות של הזבה. שכן אם כרואה דם נדה היא — הריהי סותרת, אבל אם כנוגעת בטומאה היא — אינה סותרת; \u0003ו\u0004כן יש הבדל להלכה לענין \u0003לטמא\u0004 אותה \u0003ב\u0004שפלטה שיעור \u0003משהו,\u0004 שכן אם היא כרואה — הריהי נטמאת אף במשהו, ואולם אם היא כנוגעת — אין היא מטמאת אלא בשיעור המוגדר (כעדשה או כחתימת פי האמה); \u0003ו\u0004כן יש הבדל להלכה לענין \u0003לטמא\u0004 אותה אף בהיות שכבת הזרע עדיין \u0003בפנים\u0004 גוף האשה \u0003כ\u0004פולטת שכבת זרע \u0003בחוץ\u0004 לגופה. שכן אם היא כרואה — הריהי מטמאה אף בפנים, כראיית דם נדה. ואולם אם היא כנוגעת — אין הפליטה מטמאת אלא בהיותה בחוץ, כשאר נגיעות הטומאה.","ודנים: \u0003מה נפשך\u0004 \u0005[רצונך]\u0006 לומר: \u0003אי שמיע ליה מתניתין\u0004 \u0005[אם\u0006 רב שמואל בר ביסנא \u0005שמע אותה,\u0006 את הברייתא\u0005]\u0006 מה מקום לבעייתו, שהרי עולה מן הברייתא כי \u0003ל\u0004שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 — \u0003רואה הויא\u0004 \u0005[הריהי],\u0006 שלדעתם טמאה היא בהיות שכבת הזרע בתוך גופה, בבית החיצון. \u0003ו\u0004אילו \u0003ל\u0004שיטת \u0003ר' שמעון\u0004 — שיטתו היא ש\u0003נוגעת הויא\u0004 \u0005[הריהי],\u0006 שלדעתו אין היא נטמאת אלא משיצאה שכבת הזרע לחוץ.","\u0003ואי לא שמיע ליה מתניתין\u0004 \u0005[אם\u0006 רב שמואל בר ביסנא \u0005לא שמע אותה,\u0006 את הברייתא\u0005],\u0006 עדיין מה מקום לשאלתו, שהרי \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 לומר ש\u0003נוגעת הויא\u0004 \u0005[הריהי],\u0006 שהרי אין שכבת הזרע שבא אל האשה מחוצה לה, כדם שפרש ממנה!","ומסבירים: \u0003לעולם\u0004 רב שמואל בר ביסנא \u0003שמיע ליה מתניתין\u0004 \u0005[שמע את הברייתא],\u0006 \u0003ו\u0004אכן \u0003אליבא דרבנן\u0004 \u0005[שלשיטת חכמים]\u0006 — \u0003לא קמיבעיא ליה\u0004 \u0005[נשאלה לו]\u0006 שאלתו זו, שלשיטתם הפולטת כרואה לכל דבר, ואולם \u0003כי קא מיבעיא ליה\u0004 \u0005[כאשר נשאלה לו]\u0006 שאלתו זו — הרי זה \u0003אליבא\u0004 \u0005[לשיטת]\u0006 \u0003ר' שמעון.\u0004","ומסייגים עוד, \u0003ו\u0004אף לשיטת ר' שמעון, לענין \u0003לטמא בפנים כבחוץ\u0004 — \u0003לא קמיבעיא ליה\u0004 \u0005[נשאלה לו]\u0006 שאלתו זו, שהרי ר' שמעון אמר במפורש כי אין הפליטה מטמאת בפנים כבחוץ. \u0003כי קמיבעיא ליה\u0004 לשיטת ר' שמעון — לענין \u0003לסתור\u0004 ספירת ימי נקיות של זיבה, \u0003ו\u0004לענין \u0003לטמא בכל שהוא, מאי\u0004 \u0005[מה]\u0006 הדין.","ואלו צדדי הבעיה: האם \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003ר' שמעון\u0004 את שיטתו זו ש\u0003דיה\u0004 של האשה להיות \u0003כבועלה\u0004 — \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא לענין \u0003לטמויי\u0004 \u0005[לטמא]\u0006 \u0003בפנים כבחוץ, אבל\u0004 לענין \u0003לסתור\u0004 ספירת ימי זיבה \u0003ו\u0004לענין \u0003לטמא\u0004 אף \u0003בכל שהוא\u0004 — כ\u0003רואה הויא\u0004 \u0005[הריהי]\u0006 אף לשיטת ר' שמעון. \u0003או דילמא\u0004 \u0005[שמא]\u0006 לשיטת ר' שמעון \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 דינה של הפולטת לענין שיעור המטמא ולענין סתירת ספירת ימי זיבה מטומאת פנים, שבכל אלה הפליטה מטמאת בנגיעה, ולא בראייה.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 הסבר אחר באשר לבעייתו של רב שמואל בר ביסנא: \u0003לעולם לא שמיע ליה מתניתא\u0004 \u0005[שמע את הברייתא]\u0006 שנחלקו בה חכמים ור' שמעון, \u0003ו\u0004אין זה פשוט לו שהפולטת טמאה משום נגיעה, משום ש\u0003הכי קמיבעיא ליה\u0004 \u0005[כך נשאלה לו]\u0006 שאלתו זו: \u0003מדאחמיר רחמנא אבעלי קריין\u0004 \u0005[מ\u0006זה \u0005שהחמירה התורה על בעלי קרי,\u0006 שיצאה מהם שכבת זרע\u0005]\u0006 לפני מתן תורה \u0003בסיני,\u0004 שכן נצטוו \"היו נכונים לשלושת ימים אל תגשו אל אשה\" (שמות יט, טו), ולא הוזהרו על שאר טומאות — טומאה חמורה היא, ויש איפוא מקום לומר שהפולטת שכבת זרע כ\u0003רואה הויא\u0004 \u0005[הריהי].\u0006","\u0003או דילמא\u0004 \u0005[שמא]:\u0006 \u0003לא גמרינן\u0004 \u0005[אין אנו למדים]\u0006 \u0003מ\u0004האמור במתן תורה ב\u0003סיני,\u0004 שכן \u0003חדוש הוא,\u0004 \u0003דהא\u0004 \u0005[שהרי]\u0006 אף על טומאת \u0003זבין ומצורעים דחמירי\u0004 \u0005[שחמורים]\u0006 דינם מדינם של בעלי קרי — \u0003ולא אחמיר בהו רחמנא\u0004 \u0005[החמירה בהם התורה]\u0006 להזהירם מן הדבר. ולפיכך עדיין אפשר לומר שאין דינה של הפולטת אלא משום נגיעה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי לרב שמואל בר ביסנא בתשובה לשאלתו זו: \u0003רואה הויא\u0004 \u0005[הריהי].\u0006 ומסופר כי \u0003אתא\u0004 \u0005[בא]\u0006 רב שמואל בר ביסנא ו\u0003שייליה\u0004 \u0005[שאלו]\u0006 \u0003לרבא\u0004 את בעייתו זו, \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003רואה הויא\u0004 \u0005[הריהי].\u0006 ועוד \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב יוסף\u0004 עם שאלתו, ואף הוא \u0003אמר ליה\u0004 \u0005[לו],\u0006 \u0003רואה הויא\u0004 \u0005[הריהי].\u0006 \u0003הדר אתא לקמיה\u0004 \u0005[חזר בא לפני]\u0006 \u0003אביי, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כולכו\u0004 \u0005[כולכם],\u0006 כל החכמים ששאלתים, אביי ורבא ורב יוסף, \u0003ברוקא חדא תפיתו\u0004 \u0005[ברוק אחד\u0006 אתם \u0005ירקתם]\u0006 ואין ממש בדברים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003שפיר אמרי\u0004 \u0005[יפה,\u0006 היטב, \u0005אמרו]\u0006 \u0003לך.\u0004 שכן, \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' שמעון\u0004 שהפולטת שכבת זרע \u0003דיה כבועלה\u0004 — \u0003אלא\u0004 לענין \u0003לטמא בפנים כבחוץ, אבל\u0004 לענין \u0003לסתור ולטמא בכל שהוא\u0004 — \u0003רואה הויא\u0004 \u0005[הריהי].\u0006","ועוד בדין טומאת פנים כבחוץ, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 טומאת \u0003הנדה, ו\u0004טומאת \u0003הזבה, ו\u0004טומאת \u0003השומרת יום כנגד יום\u0004 (הרואה יום או שני ימים בימי הזיבה, שצריכה לשמור יום בטהרה), \u0003ו\u0004טומאת \u0003היולדת\u0004 — \u0003כולן מטמאות בפנים כבחוץ.\u0004","ודנים בדברים: \u0003בשלמא כולהו\u0004 \u0005[זה נוח,\u0006 מובן מה ששנינו ב\u0005כולם]\u0006 שנטמאות אף שלא יצאה הטומאה אל מחוץ לגופן — \u0003לחיי\u0004 \u0005[לחיים,\u0006 בסדר\u0005],\u0006 \u0003אלא\u0004 מה ששנינו בכללן את ה\u0003יולדת\u0004 אין זה ברור, שכן \u0003אי\u0004 \u0005[אם]\u0006 המדובר בדם שרואה \u0003בימי נדה\u0004 — \u0003נדה\u0004 היא, והריהי כלולה בדין נדה האמור לפני כן, וכמו כן \u0003אי\u0004 \u0005[אם]\u0006 המדובר \u0003בימי זיבה\u0004 — \u0003זיבה\u0004 היא, והריהי כלולה בזבה האמורה מקודם!","ומסבירים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה \u0003ש\u0004עברו ימי טומאת לידה (שבוע ללידת זכר, ושבועיים ללידת נקבה), ו\u0003ירדה\u0004 היולדת \u0003לטבול\u0004 כדי לעבור על ידי טבילה זו \u0003מ\u0004ימי \u0003טומאה ל\u0004ימי \u0003טהרה.\u0004","\u0003וכי הא\u0004 \u0005[וכמו\u0006 הלכה \u0005זו]\u0006 ש\u0003אמר ר'\u0004 \u0003זירא,\u0004 שעוסקת אף היא במקרה דומה, שכך \u0003אמר ר'\u0004 \u0003חייא בר אשי, אמר רב:\u0004 ה\u0003יולדת שירדה לטבול,\u0004 כדי לעבור \u0003מ\u0004ימי \u0003טמאה ל\u0004ימי \u0003טהורה, ו\u0004לפני שטבלה \u0003נעקר ממנה\u0004 (ממקורה) \u0003דם,\u0004 ואולם לא יצא אלא לבית החיצון, ולא אל מחוץ לגופה. מה דינה? אם נעקר הדם \u0003בירידה\u0004 לטבילה — הרי היא עדיין \u0003טמאה,\u0004 שלא הועילה לה טבילתה. ואולם אם נעקר הדם \u0003בעלייה\u0004 מן הטבילה, והרי היא עתה כבר בימי טהרתה — \u0003טהורה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' ירמיה לר' זירא\u0004 בשאלה על הלכה זו: אם נעקר הדם \u0003בירידה\u0004 לטבילה \u0003אמאי\u0004 \u0005[מדוע]\u0006 היא \u0003טמאה?\u0004 והרי \u0003טומאה בלועה היא! אמר ליה\u0004 \u0005[לו]\u0006 ר' זירא לר' ירמיה: \u0003זיל שייליה\u0004 \u0005[לך שאל אותו]\u0006 את \u0003ר' אבין, דאסברית ניהליה\u0004 \u0005[שהסברתי לו]\u0006 טעמו של דבר זה, \u0003וכרכיש\u0004 \u0003לי ברישיה בי מדרשא\u0004 \u0005[ונענע לי בראשו ב\u0006היותו ב\u0005בית המדרש,\u0006 כמסכים לדבריי\u0005].\u0006","ומסופר, \u0003אזל\u0004 \u0005[הלך]\u0006 ר' ירמיה, \u0003שייליה\u0004 \u0005[שאלו]\u0006 את ר' אבין להסבר הדבר, \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אבין לר' ירמיה: \u0003עשאוה כנבלת עוף טהור, שמטמאה בגדים\u0004 של האוכל אותה, בהיות כזית ממנה \u0003בבית הבליעה\u0004 של האוכל, אף שטומאה בלועה היא. הקשה לו ר' ירמיה: \u0003מי דמי\u0004 \u0005[האם דומה]\u0006 טומאת יולדת לטומאתו של האוכל נבלת עוף טהור שמטמא בגדים?"],["שהרי \u0003התם\u0004 \u0005[שם,\u0006 בטומאה הבאה על ידי אכילת נבלת עוף טהור\u0005]\u0006 — \u0003אין לה\u0004 לסוג טומאה זו כלל \u0003טומאה בחוץ,\u0004 שכן כל טומאת אכילת נבלת עוף טהור מיוחדת היא שאינה אלא בהיות נבלה זו בפיו, ואילו \u0003הכא\u0004 \u0005[כאן,\u0006 בטומאת דם היולדת המטמא במגע ובמשא\u0005]\u0006 — \u0003כי נפיק לבראי ליטמי\u0004 \u0005[כאשר יצא\u0006 הדם \u0005אל מחוץ\u0006 לגופה \u0005שיטמא],\u0006 ככל הדברים המטמאים במגעם, שאינם מטמאים בהיותם בלועים! אלא יש לומר מכח קושיה זו כי \u0003הכא נמי\u0004 \u0005[כאן\u0006 בדברי ר' זירא אלו \u0005גם כן]\u0006 מדובר \u0003כשיצא\u0004 הדם \u0003לחוץ\u0004 מגופה, והריהי נטמאת במגעו, ולא בהיותו בגופה, שטומאה בלועה היא.","ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 המדובר בדם ש\u0003יצא לחוץ\u0004 — \u0003מאי למימרא\u0004 \u0005[מה\u0006 חידוש בא ר' זירא \u0005לומר]\u0006 בדבריו, שמטמא דם זה במגעו? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003מגו דמהני\u0004 \u0005[מתוך שמועילה]\u0006 ה\u0003טבילה\u0004 שטובלת היולדת מימי טומאתה לימי טהרתה, \u0003לדם דאיכא גואי\u0004 \u0005[שישנה בתוכה],\u0006 שהרי כל דם שיש בה, שיעקר לאחר טבילה זו, הריהו טהור — \u0003תהני נמי\u0004 \u0005[תועיל גם כן]\u0006 טבילה זו אף \u0003להאי\u0004 \u0005[לזה],\u0006 לדם שיש בה, וכבר נעקר, אך לא יצא החוצה, שלא יטמא לכשיצא. לכן \u0003קא משמע לן\u0004 \u0005[הוא,\u0006 ר' זירא, \u0005משמיע לנו]\u0006 שהועילה הטבילה רק לדם שלא נעקר לפני הטבילה.","ושואלים: מעתה, \u0003שמעתין\u0004 \u0005[שמועתנו,\u0006 דברי הלכה אלו של ר' זירא\u0005]\u0006 — \u0003איפריק\u0004 \u0005[יושבו,\u0006 תורצו\u0005],\u0006 \u0003אלא\u0004 באשר ל\u0003יולדת\u0004 ששנינו במשנתנו שהיא מטמאה ביציאת הדם לבית החיצון, נשארה השאלה: מה חידוש יש בדבר זה, שהרי \u0003אי\u0004 \u0005[אם]\u0006 היא \u0003בימי נדה\u0004 — \u0003נדה\u0004 היא, ולמדנו במשנתנו שהנדה מטמאה ביציאת הדם לבית החיצון, ו\u0003אי\u0004 \u0005[אם]\u0006 היא \u0003בימי זיבה\u0004 — \u0003זיבה\u0004 היא זו, ואף בזבה שנינו שנטמאת ביציאה לבית החיצון. ומה צורך להשמיע דין זה ביולדת!","ומתרצים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן\u0006 במשנתנו \u0005במה אנו עוסקים]\u0006 — באשה היולדת \u0003בלידה יבשתא\u0004 \u0005[יבישה],\u0006 שאין עמה דם. שנטמאת בטומאת הלידה כשלעצמה, וחידשה משנתנו, שנטמאת אף שלא יצא דמה אל מחוץ לגופה. ושואלים על הסבר זה: אם מדברת משנתנו ב\u0003לידה יבשתא\u0004 \u0005[יבישה],\u0006 אם כן \u0003מאי\u0004 \u0005[מה,\u0006 איזה\u0005]\u0006 דבר בלידה זו שניתן לומר בו, כדברי המשנה, ש\u0003מטמא בפנים כבחוץ איכא\u0004 \u0005[יש]\u0006 בלידה זו, והלא לא היה בה כלל דם בלידה זו!","ומתרצים: כוונת הלשון היא לא לדם אלא ל\u0003כגון שהוציא\u0004 ה\u0003ולד\u0004 את \u0003ראשו\u0004 אל מ\u0003חוץ לפרוזדור\u0004 שברחם אמו, לבית החיצון שבה. ונחשב בכך לנולד, ונטמאת אמו בטומאת הלידה, אף שלא יצא הראש אל מחוץ לגופה. \u0003וכ\u0004שיטתו של \u0003רב אושעיא,\u0004 שכך \u0003אמר רב אושעיא:\u0004 המיילדת שהכניסה ידה לתוך רחמה של אשה שהעובר שבמעיה מת, טמאה בטומאת המת מדברי חכמים משום \u0003גזרה\u0004 שגזרו חכמים לטמאה במקרה זה, \u0003שמא יוציא הולד ראשו חוץ לפרוזדור,\u0004 ומת לאחר מכן, והמיילדת הנוגעת בולד זה הריהי טמאה מן התורה במגעו, שאז נחשב הוא כילוד.","\u0003וכי ההוא\u0004 \u0005[וכמו\u0006 המסופר באדם \u0005אחד]\u0006 \u0003דאתא לקמיה\u0004 \u0005[שבא לפני]\u0006 \u0003רבא, אמר ליה\u0004 \u0005[לו]\u0006 בשאלה: \u0003מהו\u0004 הדין לענין \u0003לממהל בשבתא\u0004 \u0005[למול בשבת]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003שפיר דמי\u0004 \u0005[יפה,\u0006 ראוי \u0005הדבר].\u0006 \u0003בתר דנפק\u0004 \u0005[אחר שיצא]\u0006 אותו אדם מלפני רבא, \u0003אמר רבא\u0004 לעצמו, בתמיהה: וכי \u0003סלקא דעתך דההוא גברא\u0004 \u0005[עולה על הדעת שאותו אדם]\u0006 \u0003לא ידע דשרי לממהל בשבתא\u0004 \u0005[שמותר למול בשבת],\u0006 שבא לשאול על כך? אין זאת, אלא שיש דבר נוסף בשאלתו, שלא אמר. \u0003אזל בתריה\u0004 \u0005[הלך\u0006 רבא \u0005אחריו],\u0006 ומשהשיגו, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 \u0003לי איזי\u0004 \u0005[חביבי],\u0006 בדיוק, \u0003גופא דעובדא היכי הוה\u0004 \u0005[גוף המעשה איך היה].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אותו אדם לרבא: \u0003שמעית\u0004 \u0005[שמעתי]\u0006 את ה\u0003ולד דצויץ אפניא דמעלי שבתא\u0004 \u0005[שמצייץ,\u0006 משמיע קול, ביום ששי \u0005בערב שלפני כניסת שבת],\u0006 \u0003ו\u0004אולם \u0003לא אתיליד\u0004 \u0005[נולד]\u0006 \u0003עד שבתא\u0004 \u0005[שבת].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003האי\u0004 \u0005[זה]\u0006 התינוק \u0003הוציא ראשו חוץ לפרוזדור הוא,\u0004 שהרי אלמלא כן לא היה יכול להישמע קולו. וכיון שכך, הריהו נחשב כמי שנולד כבר ביום ששי, וחל זמן מילתו ביום השמיני ללידתו, ביום הששי הבא. \u0003ו\u0004אם באים למולו לאחר מכן, \u0003הוי\u0004 \u0005[הריהי]\u0006 \u0003מילה שלא בזמנה, ו\u0004כלל הוא: שאף שמילה בזמנה דוחה את השבת, ואולם \u0003כל מילה שלא בזמנה\u0004 — \u0003אין מחללין עליה את השבת.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 לחכמים\u0005]\u0006 שאלה זו: \u0003אותו מקום\u0004 (מקום הערווה) \u0003של\u0004 ה\u0003אשה,\u0004 כיצד הוא מוגדר בדיוק, האם \u0003בלוע הוי\u0004 \u0005[הינו],\u0006 וכלל הוא שאין הדבר הבלוע בתוך גופו של אדם מטמא אותו. \u0003או בית הסתרים הוי\u0004 \u0005[הינו],\u0006 שאינו מטמא בנגיעת הדבר הטמא בו, אבל מטמא הוא במשא?","ומבררים: \u0003למאי נפקא מינה\u0004 \u0005[למה,\u0006 לאיזה ענין יש \u0005תוצאה ממנה,\u0006 משאלה זו\u0005]\u0006 — במקרה \u0003כגון\u0004 \u0003שתחבה לה חבירתה כזית נבלה,\u0004 שהוא שיעור המטמא, \u0003באותו מקום.\u0004 ומעתה, \u0003אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שאותו המקום \u0003בלוע הוי\u0004 \u0005[הינו]\u0006 — אף זו הריהי \u0003טומאה בלועה,\u0004 וטומאה בלועה \u0003לא מטמאה.\u0004 \u0003ו\u0004אולם \u0003אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שאותו מקום \u0003בית הסתרים הוי\u0004 \u0005[הינו],\u0006 — \u0003נהי\u0004 \u0005[אמנם]\u0006 שאותו המקום של האשה, בהיותו נחשב כבית הסתרים גורם לכך ש\u0003במגע לא מטמיא\u0004 \u0005[אינה נטמאת],\u0006 אבל \u0003במשא מיהא מטמיא\u0004 \u0005[לפחות תיטמא],\u0006 שהרי מכל מקום היא נושאת את כזית הנבילה.","\u0003אביי אמר\u0004 בפתרון בעיה זו: \u0003בלוע הוי\u0004 \u0005[הינו],\u0006 ואילו \u0003רבא אמר: בית הסתרים הוי\u0004 \u0005[הינו].\u0006 ובנימוק שיטתו \u0003אמר רבא: מנא אמינא לה\u0004 \u0005[מנין אומר אני אותה,\u0006 את שיטתי זו\u0005]\u0006 — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 על האמור \"ואשה אשר ישכב איש אותה שכבת זרע ורחצו במים וטמאו עד הערב\" (ויקרא טו, יח), אמר ר' שמעון: וכי מה בא כתוב זה ללמדנו? אם לענין הנוגע בשכבת זרע שנטמא טומאת ערב — הרי דבר זה כבר נלמד מן האמור בהמשך הכתובים (ויקרא כב, ד) \"או אשר תצא ממנו שכבת זרע\". אלא בא הכתוב ללמדנו שהאשה שנבעלה נטמאת בשכבת זרע של בועלה, אף שלא נגעה בה שכבת זרע זו מחוץ לגופה. ומה חידוש הוא? \u0003אלא מפני שטומאת בית הסתרים היא, ו\u0004כלל הוא ש","\u0003טומאת בית הסתרים לא מטמאה.\u0004 \u0003אלא שגזרת הכתוב היא\u0004 שהאשה הנבעלת נטמאת אף באופן זה. הרי איפוא שאותו המקום נחשב כבית הסתרים.","\u0003ואביי\u0004 מה משיב הוא על הוכחתו זו של רבא? — \u0003חדא\u0004 \u0005[אחת]\u0006 \u0003ועוד קאמר\u0004 \u0005[הוא\u0006 ר' שמעון, התנא שבברייתא זו אומר], וכך יש להבין את דבריו: \u0003חדא\u0004 \u0005[אחת]\u0006 שכן \u0003טומאה בלועה היא.\u0004 \u0003ועוד, אפילו אם תמצי\u0004 \u0005[תמצא]\u0006 מקום \u0003לומר\u0004 ש\u0003טומאת בית הסתרים היא\u0004 — זו כרגיל \u0003אינה מטמאה, אלא ש\u0004בענין האשה הנבעלת \u0003גזרת הכתוב היא.\u0004","ועוד \u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 לחכמים\u0005]\u0006 שאלה דומה: מקום הבליעה בפיו של אדם, שהוא ה\u0003מקום\u0004 בו \u0003נבלת עוף טהור\u0004 מטמאת, מהי הגדרתו המדוייקת, האם \u0003בלוע הוי\u0004 \u0005[הינו]\u0006 נחשב, \u0003או\u0004 כ\u0003בית הסתרים הוי\u0004 \u0005[הינו]\u0006 נחשב?","ומבררים: \u0003למאי נפקא מינה\u0004 \u0005[למה,\u0006 לאיזה ענין יש \u0005תוצאה ממנה,\u0006 משאלה זו\u0005] —\u0006 \u0003כגון שתחב לו חבירו כזית נבלה\u0004 של עוף טהור, שהוא השיעור המטמא \u0003לתוך פיו\u0004 של זה. ויש לדון בדינו: שכן \u0003אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שבית הבליעה \u0003בלוע הוי\u0004 \u0005[הינו]\u0006 — הרי איפוא \u0003טומאה בלועה\u0004 היא בפיו, וטומאה בלועה \u0003לא מטמיא\u0004 \u0005[מטמאת]. (\u0006\u0003אלא אי\u0004 \u0005[אם]\u0006\u0003) אמרת\u0004 \u0005[אומר אתה]\u0006 שבית הבליעה \u0003בית הסתרים הוי\u0004 \u0005[הינו]\u0006 — \u0003נהי\u0004 \u0005[אמנם]\u0006 ש\u0003במגע\u0004 הוא \u0003לא מטמא, במשא מיהא\u0004 \u0005[לפחות]\u0006 \u0003מטמא.\u0004","ואף בשאלה זו נחלקו אביי ורבא, \u0003אביי אמר: בלוע הוי\u0004 \u0005[הינו],\u0006 \u0003ורבא אמר: בית הסתרים הוי\u0004 \u0005[הינו].\u0006 \u0003אמר אביי\u0004 בנימוק שיטתו: \u0003מנא אמינא לה\u0004 \u0005[מנין אומר אני אותה,\u0006 את שיטתי זו\u0005]\u0006 — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003יכול תהא\u0004 אף אכילת \u0003נבלת בהמה מטמאה בגדים\u0004 בהיותה ב\u0003בית הבליעה\u0004 של האוכל, ובדומה לאכילת נבלת עוף טהור? — \u0003תלמוד לומר \"נבלה וטרפה לא יאכל לטמאה בה\"\u0004 (שם כב, ח), ולמדנו מכתוב זה העוסק בטומאה שעל ידי אכילה, כי הדברים אמורים דווקא ב","\u0003מי שאין לה טומאה אלא\u0004 ב\u0003אכילתה\u0004 בלבד, כלומר, בנבלת עוף טהור, שאינה מטמאה אלא בהיותה נאכלת בבית הבליעה של האוכלה — \u0003יצתה\u0004 (יצאה) מכלל זה \u0003זו שטמאה\u0004 גם \u0003קודם שיאכלנה,\u0004 במגע ובמשא. שאין שאר הטומאות, מלבד נבלת עוף טהור, מטמאות בבית הבליעה. והרי זה איפוא כשיטת אביי, שמקום בית הבליעה בלוע הוא, ולכן אינו מטמא כלל.","ושואלים על הלימוד שבברייתא: \u0003ותיתי\u0004 \u0005[ותבוא,\u0006 ותילמד\u0005]\u0006 הלכה שנבלת בהמה מטמאת בגדים בבית הבליעה, \u0003בקל וחומר מנבלת עוף טהור,\u0004 ובאופן זה: \u0003ומה נבלת עוף טהור,\u0004 שקל הוא דינה, \u0003ש\u0004הרי \u0003אין לה טומאה בחוץ,\u0004 שאם נגע בה אדם או נשאה אינו טמא — \u0003יש לה טומאה בפנים\u0004 (בבית הבליעה). \u0003זו\u0004 (נבלת בהמה), שחמורה היא בדינה, \u0003ש\u0004הרי \u0003יש לה טומאה בחוץ\u0004 — אינו דין שיש לה טומאה בפנים! ומשיבים:","\u0003אמר קרא\u0004 \u0005[המקרא]\u0006 בטומאה זו \"נבלה וטרפה לא יאכל לטמאה \u0003בה\"\u0004 — והרי זה לשון מיעוט: דווקא \u0003בה\u0004 בנבלת עוף טהור, נוהגת טומאה בבית הבליעה, \u0003ולא באחרת.\u0004","אלא מעתה יש לשאול: \u0003אם כן מה תלמוד לומר\u0004 (מלמדנו) הכתוב בטומאת נבלת בהמה \u0003\"והאוכל\u0004 מנבלתה יכבס בגדיו וטמא עד הערב\" (שם יא, מ), שעולה מן הדברים שמטמאת נבלת הבהמה אף באכילתה?","— \u0003ליתן שיעור\u0004 לטומאת נבלת הבהמה, בכמה היא מטמאה, ואולם אין היא מטמאת אלא \u0003לנוגע ולנושא\u0004 אותה, ולא לאוכל אותה. ששיעור זה הריהו \u0003כ\u0004שיעור של ה\u0003אוכל.\u0004 \u0003מה\u0004 שיעורו של ה\u0003אוכל\u0004 שתיחשב אכילתו אכילה — \u0003בכזית, אף\u0004 שיעור הטומאה בנבלת בהמה ל\u0003נוגע\u0004 בה \u0003ו\u0004ל\u0003נושא\u0004 אותה — \u0003בכזית.\u0004","ועוד בענין טומאת בבית הסתרים, \u0003אמר רבא:\u0004 נמצא \u0003שרץ\u0004 מת \u0003ב\u0004תוך \u0003קומטו\u0004 (המקומות הקמוטים בגוף האדם, כגון בין אצילי ידיו) — \u0003טהור.\u0004 נמצאת \u0003נבלה בקומטו\u0004 של אדם — הריהו \u0003טמא\u0004 בכך.","ומסביר רבא את דבריו: \u0003שרץ בקומטו, טהור\u0004 האדם — שכן ה\u0003שרץ בנגיעה הוא\u0004 ש\u0003מטמא, ובית הסתרים לאו\u0004 \u0005[לא]\u0006 \u0003בר מגע הוא.\u0004 נמצאת \u0003נבלה בקומטו, טמא\u0004 — כי \u0003נהי\u0004 \u0005[הגם]\u0006 ש\u0003במגע\u0004 הוא \u0003לא מטמא,\u0004 שהרי בית הסתרים הוא, ואולם \u0003ב\u0004טומאת \u0003משא מיהא\u0004 \u0005[לפחות]\u0006 הריהו \u0003מטמא.\u0004 שהרי אף שאינו נחשב כנוגע בה נושא הוא אותה.","ועוד אמר רבא: היה \u0003שרץ בקומטו, והכניסו\u0004 את קומטו והשרץ שבו, \u0003ל\u0004תוך \u0003אויר\u0004 (חלל) כלי גדול, כעין \u0003התנור\u0004 — \u0003טמא\u0004 התנור בכך, כדין השרץ שנכנס לחלל התנור. ושואלים על הלכה זו: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר, ומה משמיענו רבא? ומשיבים: חידוש יש בדבר, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 כיון שבדין טומאת השרצים \"וכל כלי חרש אשר יפול מהם אל \u0003תוכו\u0004 כל אשר בתוכו יטמא ואותו תשבורו\" (שם יא, לג) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 והרי זה בא לדייק: דווקא אם נפל השרץ לתוכו ממש,"],["\u0003ולא\u0004 כאשר השרץ נמצא ב\u0003תוך תוכו\u0004 בקומטו, לכן \u0003קא משמע לן\u0004 \u0005[הוא משמיע לנו]\u0006 שאין תוך הקמט נחשב כתוך תוכו, אלא רק כאשר היה כלי בתוך התנור, ופתחו של כלי זה הוא מחוץ לתנור, ונפל לכלי שבתוכו.","ועוד בענין טומאה בקומטו של אדם, \u0003אמר ריש לקיש:\u0004 היה \u0003קנה\u0004 או מוט נתון \u0003ב\u0004תוך \u0003קומטו של\u0004 אדם הטמא בטומאת \u0003זב, והסיט בו את ה\u0004אדם ה\u0003טהור\u0004 — אף שהזב מטמא בהיסטו, אדם זה הריהו \u0003טהור.\u0004 \u0003ואם היה ה\u0004\u0003קנה\u0004 נתון \u0003ב\u0004תוך \u0003קומטו של\u0004 אדם \u0003טהור, והסיט בו את הזב\u0004 — \u0003טמא\u0004 הטהור בכך. שכן נטמא ככל הנושא את הזב, ובכלל טומאת משא אף אם נשא הטהור את הזב בבית סתריו.","ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הזב שהסיט בקנה שבקומטו את הטהור, אינו נטמא בכך — שכן \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 בדינו של הזב \u0003\"וכל אשר יגע בו הזב וידיו לא שטף במים\u0004 וכבס בגדיו ורחץ במים וטמא עד הערב\" (ויקרא טו, יא) — \u0003זהו\u0004 כוונת הכתוב \"אשר יגע בו\" \u0003הסיטו של זב.\u0004 \u0003שלא מצינו\u0004 (מצאנו) \u0003לו\u0004 (כמותו) \u0003טומאה בכל התורה כולה,\u0004 שמטמאת בהיסט, מלבד בטומאת הזב.","\u0003ואפקיה רחמנא\u0004 \u0005[והוציאתו,\u0006 וכתבתו \u0005התורה]\u0006 לטומאה שעל ידי היסט \u0003בלשון נגיעה, למימרא\u0004 \u0005[לומר,\u0006 ללמד\u0005]\u0006 שטומאה על ידי \u0003היסט ו\u0004טומאה שעל ידי \u0003נגיעה\u0004 הרי הן \u0003כידיו.\u0004 \u0003מה התם\u0004 \u0005[שם],\u0006 בטומאת מגע — הריהי \u0003מאבראי\u0004 \u0005[מבחוץ],\u0006 \u0003אף הכא\u0004 \u0005[כאן]\u0006 בטומאה שעל ידי היסט — \u0003מאבראי\u0004 \u0005[מבחוץ].\u0006","שנינו במשנתנו כי הנדה מטמאת עוד בהיות הדם בבית החיצון, ואף שלא יצא לחוץ, \u0003אבל הזב ובעל קרי אינן מטמאין\u0004 אלא משתצא טומאתם אל מחוץ לגופם. ומסבירים: דינו זה של ה\u0003זב\u0004 — משום \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בזב \"איש איש \u0003כי יהיה זב מבשרו\"\u0004 (שם ב) — \u0003עד שיצא זובו מבשרו.\u0004 ודינו זה של \u0003בעל קרי\u0004 — משום \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בטומאת בעל הקרי \u0003\"ואיש כי תצא ממנו שכבת זרע\"\u0004 (שם טז) — דווקא כאשר תצא אל מחוץ לבשרו.","עוד שנינו במשנתנו שאם \u0003היה אוכל בתרומה והרגיש\u0004 בתוך כך שנעקרה ממנו שכבת זרע (\"הזדעזעו אבריו\"), הריהו אוחז באמתו, באבר זכרותו, כדי לעצור את שכבת הזרע מלצאת, ובולע את התרומה שבפיו. שהרי אם תצא שכבת הזרע, ייטמא בכך, ויצטרך לפולטה ולהפסידה בכך. ושואלים: \u0003אוחז\u0004 באמתו? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: כל האוחז באמה ומשתין,\u0004 הריהו עושה כמעשיהם של בני דור המבול, שהשחיתו דרכם בהוצאת שכבת זרע, ו\u0003כאילו מביא\u0004 בכך \u0003מבול לעולם!\u0004","\u0003אמר אביי:\u0004 כוונת משנתנו לומר שיאחז באמתו \u0003ב\u0004אמצעות \u0003מטלית עבה,\u0004 ואין באופן זה משום חימום המביא לידי הוצאת זרע. \u0003רבא אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שמדובר במשנתנו באוחז באמתו \u0003במטלית רכה,\u0004 ואולם במקרה זה, שכבר הרגיש שנעקרה ממנו שכבת זרע, מותר הדבר, ש\u0003כיון\u0004 שכבר \u0003עקר\u0004 הזרע ממקומו — \u0003עקר,\u0004 ובאחיזתו באמתו, אין הוא גורם עוד לעקירת זרע. \u0003ו\u0004הסבר שיטותיהם: \u0003אביי\u0004 — \u0003חייש\u0004 \u0005[חושש]\u0006 שהמחזיק באמתו במטלית רכה, \u0003דילמא אתי לאוסופי\u0004 \u0005[שמא יביא\u0006 הדבר \u0005להוספה]\u0006 בהוצאת הזרע שכבר נעקר ממנו. \u0003ו\u0004אילו \u0003רבא\u0004 — \u0003לאוסופי לא חייש\u0004 \u0005[להוספה\u0006 על הזרע שכבר נעקר \u0005אינו חושש].\u0006","ושואלים לשיטת רבא: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003למה זה\u0004 האוחז באיברו \u0003דומה\u0004 — \u0003ל\u0004זה ה\u0003נותן אצבע בעין, שכל זמן ש\u0004ה\u0003אצבע\u0004 נתונה \u0003ב\u0004תוך ה\u0003עין\u0004 — העין \u0003מדמעת וחוזרת ומדמעת,\u0004 ואף זה המחזיק באיברו, גורם שיצא שוב ושוב ממנו זרע.","\u0003ורבא\u0004 סבור כי \u0003כל\u0004 מקרה של \u0003אחמומי והדר אחמומי בשעתא\u0004 \u0005[חימום\u0006 הגוף, וכמו במשנתנו שחש שנזדעזע גופו, \u0005ושוב חימום ב\u0006אותה \u0005שעה]\u0006 הריהו \u0003לא שכיח\u0004 \u0005[מצוי],\u0006 ואין לחשוש בו להוצאה נוספת של זרע. ואולם במקרה של המחזיק באיברו, ובלא חימום, אפשר שיצא ממנו שוב ושוב זרע, וכדוגמת הנותן אצבע בעין.","\u0003אמר שמואל: כל שכבת זרע שאין כל גופו מרגיש בה\u0004 בשעה שיצאה ממנו — \u0003אינה מטמאה.\u0004 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — שכן בדין טומאת בעל קרי \"ואיש כי תצא ממנו \u0003שכבת זרע\"\u0004 (ויקרא טו, טז) \u0003אמר רחמנא\u0004 \u0005[אמרה תורה]\u0006 — דווקא \u0003ב\u0004שכבת זרע ה\u0003ראויה להזריע\u0004 (להפריה) הריהו נטמא, ורק זו שמרגיש ביציאתה ראויה להזריע.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: \u0003היה מהרהר\u0004 בשנתו \u0003בלילה\u0004 בדברים שיש בהם להביא להוצאת זרע, \u0003ועמד\u0004 (וקם, והתעורר) \u0003ומצא\u0004 את \u0003בשרו\u0004 (אבר זכרותו) שהוא \u0003חם,\u0004 ואולם לא חש שיצאה ממנו שכבת זרע — הרי זה \u0003טמא,\u0004 הרי שטומאת קרי אף בשכבת זרע שאין כל גופו מרגיש בה! ומשיבים: כבר \u0003תרגמא\u0004 \u0005[פירשה,\u0006 העמידה\u0005]\u0006 \u0003רב הונא\u0004 את דברי הברייתא, שמדובר בה \u0003ב\u0004זה שראה שהוא \u0003משמש מטתו בחלומו,\u0004 וכיון ש\u0003אי אפשר לשמש בלא הרגשה,\u0004 בודאי אף הוא הרגיש, אלא שלאחר שניעור משנתו אינו מרגיש.","\u0003לישנא אחרינא\u0004 \u0005[לשון אחרת],\u0006 שכך \u0003אמר שמואל: כל שכבת זרע שאינו יורה כחץ\u0004 — \u0003אינה מטמאה\u0004 את האדם בטומאת קרי. ומבררים: \u0003מאי איכא בין האי לישנא להאי לישנא\u0004 \u0005[מה,\u0006 איזה הבדל יש בין הלשון הזו ללשון הזו]? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל זה: שכבת זרע ש\u0003נעקרה בהרגשה, ו\u0004אולם \u0003יצאה שלא בהרגשה\u0004 שאין זו כיריה בחץ. שללשון הראשונה הריהו נטמא בכך, וללשון השניה אין הוא נטמא בכך.","ומעירים: \u0003מילתא דפשיטא ליה\u0004 \u0005[דבר שפשוט לו]\u0006 \u0003לשמואל, מיבעיא ליה\u0004 \u0005[נשאל לו]\u0006 \u0003לרבא.\u0004 שכן \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא:\u0004 שכבת זרע ש\u0003נעקרה בהרגשה, ו\u0004אולם \u0003יצתה\u0004 ממנו \u0003שלא בהרגשה, מהו\u0004 שתטמא משום בעל קרי.","ומביאים פתרון לשאלה מזו, \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע] ממה ששנינו: \u0003בעל קרי שטבל\u0004 לטהרתו, \u0003ולא הטיל מים\u0004 לפני טבילתו — \u0003לכשיטיל מים,\u0004 הריהו \u0003טמא,\u0004 שכן בתוך שיצאו ממנו מי רגליו, יוצא אגב כך גם מן הזרע שנעקר ממנו. ונטמא ביציאה זו, ואף שהיא שלא בהרגשה. ובודאי הטעם הוא משום שעקירת הזרע היתה בהרגשה. ודוחים: אין להביא ראיה מכאן, שכן \u0003שאני התם\u0004 \u0005[שונה\u0006 המקרה \u0005שם]\u0006 משום ש\u0003רובה\u0004 של שכבת הזרע \u0003בהרגשה נפק\u0004 \u0005[יצאה],\u0006 ולכך הוא נטמא אף בזו שיוצאת ממנו שלא בהרגשה.","\u0003לישנא אחרינא אמרי לה\u0004 \u0005[לשון אחרת אומרים אותה\u0006 הלכה\u0005]\u0006 שכך \u0003אמר שמואל: כל שכבת זרע שאינו יורה כחץ\u0004 — \u0003אינה מזרעת,\u0004 שלא יווצר ממנה עובר. ומדייקים בדבריו: שכבת זרע שאינה יורה כחץ \u0003אזרועי\u0004 \u0005[להזריע]\u0006 — \u0003הוא דלא מזרעא\u0004 \u0005[שאינה מזרעת],\u0006 \u0003הא טמויי\u0004 \u0005[הרי שלטמא]\u0006 בטומאת קרי — הריהי \u0003מטמיא\u0004 \u0005[מטמאה],\u0006 \u0003ש\u0004כן \u0003נאמר\u0004 בבעל קרי: \u0003\"כי יהיה בך איש אשר לא יהיה טהור מקרה\"\u0004 (דברים כג, יא) — \u0003אפילו קרי בעולם\u0004 (סתם) שאין בו כדי זריעה והולדה, הריהו מטמא.","ובענין דומה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא: גוי שהרהר\u0004 הרהור שיש בו להביא להוצאת זרע, ומתוך כך נעקרה ממנו שכבת זרע, ואולם לא יצאה אל מחוצה לו. \u0003ו\u0004לאחר מכן \u0003ירד וטבל\u0004 לשם גירות, והריהו מעתה יהודי. ואחרי כן יצאה ממנו שכבת הזרע, \u0003מהו\u0004 דינו?","וצדדי השאלה, \u0003אם תמצי\u0004 \u0005[תרצה]\u0006 \u0003לומר\u0004 כי כלל הוא ש\u0003בתר\u0004 \u0005[אחר]\u0006 ה\u0003עקירה אזלינן\u0004 \u0005[אנו הולכים],\u0006 ואף שאילו היה דבר שכזה קורה בישראלי, היה הוא נטמא בכך, בכגון זה שהיה בשעת העקירה גוי אינו נטמא בכך, ואולם יש לומר כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שהולכים אחר העקירה אמורים דווקא כאשר המסקנה \u0003לחומרא\u0004 (וכדרך שנפסק כן אצל הישראלי, במקרה שכזה), \u0003אבל הכא\u0004 \u0005[כאן,\u0006 אצל הגוי\u0005],\u0006 שאם נאמר שהולכים אחר העקירה, הרי זה \u0003לקולא\u0004 \u0005[להקל]\u0006 — שמא \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 שהולכים אחר העקירה. \u0003או דילמא\u0004 \u0005[שמא],\u0006 \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 דין זה בין הישראלי לבין הגוי, בין לחומרה ובין לקולא, תמיד הולכים אחר העקירה. ומסכמים: \u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה, ללא פתרון.","ועוד \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא\u0004 בענין דומה: האשה ה\u0003זבה שנעקרו מימי רגליה\u0004 (שהם טמאים כשאר מעיינות הזבה) ממקורם, וטרם יצאו מחוץ לגופה, \u0003וירדה וטבלה\u0004 לטהרתה משום הזיבה, ורק אחר כך הטילה את מימי רגליה, \u0003מהו\u0004 דינה?","וצדדי השאלה, \u0003אם תמצא\u0004 \u0005[תרצה]\u0006 \u0003לומר\u0004 כי \u0003בתר\u0004 \u0005[אחר]\u0006 \u0003עקירה אזלינן\u0004 \u0005[אנו הולכים],\u0006 ויש לנו איפוא לטמאה משום מי רגליה שנעקרו ממנה בהיותה זבה. ואולם יש לומר כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שהולכים אחר העקירה, אמורים דווקא ב\u0003שכבת זרע,\u0004 ומשום ש\u0003לא מצי נקיט לה\u0004 \u0005[שאינו יכול\u0006 האיש לאחוז בה, לעצור בעדה מלצאת\u0005],\u0006 \u0003אבל מימי רגליה, דמצי נקיט לה\u0004 \u0005[שיכולה\u0006 היא \u0005לעצור בה\u0006 מלצאת\u0005]\u0006 — \u0003לא\u0004 אומרים אנו בהם שאחר העקירה אנו הולכים, \u0003או דילמא לא שנא\u0004 \u0005[שמא אינו שונה]\u0006 דין מי רגלים מדין שכבת זרע, שבזה ובזה הולכים אחר העקירה. ומסכמים: \u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה, ללא פתרון.","ועוד \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא\u0004 שאלה דומה: \u0003גויה זבה\u0004 שאינה נחשבת כטמאה מן התורה (ורק מדברי חכמים הריהי כזבה לכל דבר) \u0003שנעקרו מימי רגליה\u0004 בהיותה גויה,"],["\u0003ו\u0004לאחר מכן \u0003ירדה וטבלה\u0004 לשם גירות, ומעתה הריהי כבת ישראל, \u0003מהו\u0004 דינה במקרה זה?","וצדדי השאלה: \u0003אם תמצי\u0004 \u0005[תמצא]\u0006 \u0003לומר\u0004 כי \u0003בתר\u0004 \u0005[אחר]\u0006 \u0003עקירה אזלינן אף על גב דמצי נקיט להו\u0004 \u0005[אנו הולכים, אף על פי שיכולה לאחוז בהם\u0006 שלא יצאו לחוץ\u0005],\u0006 ומשום כך, אילו היה זה בישראלית הריהי טמאה, אבל גויה אינה נטמאת בכך מן התורה. ואולם אפשר לומר מצד שני \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא ב\u0003ישראלית,\u0004 שהיא \u0003טמאה\u0004 טומאה \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 \u0003אבל גויה זבה,\u0004 שאין היא \u0003טמאה\u0004 אלא מ\u0003דרבנן\u0004 \u0005[\u0006מגזירת \u0005חכמים]\u0006 — \u0003לא\u0004 נאמר שהולכים אחר העקירה, \u0003או דילמא לא שנא\u0004 \u0005[שמא אינו שונה]\u0006 דינה של הגיורת מדינה של הישראלית לענין זה. ומסכמים: לא נפתרה בעיה זו, ו\u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה, ללא פתרון.","שנינו במשנתנו שהזיבה והקרי \u0003מטמאין\u0004 את האדם שיצאו ממנו \u0003בכל שהן.\u0004 \u0003אמר שמואל:\u0004 על מנת שייטמא האדם ב\u0003זב צריך\u0004 שתצא ממנו זיבה \u0003כ\u0004שיעור שיש בה כדי \u0003חתימת\u0004 (סתימת) \u0003פי האמה\u0004 (פתח אבר הזכרות), \u0003ש\u0004כן \u0003נאמר\u0004 בדינו של הזב \"וזאת תהיה טומאתו בזובו... \u0003או החתים בשרו מזובו\u0004 טומאתו היא\" (ויקרא טו, ג).","ומקשים: \u0003והאנן תנן\u0004 \u0005[והרי אנו שנינו]\u0006 במשנתנו כי הזיבה והקרי \u0003מטמאין בכל שהן?\u0004 ומשיבים: \u0003הוא\u0004 שמואל ש\u0003אומר\u0004 את שיטתו זו, סבור כר' נתן. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' נתן אומר משום\u0004 \u0005[בשם]\u0006 \u0003ר' ישמעאל:\u0004 על מנת שייטמא האדם ב\u0003זב צריך\u0004 שתצא ממנו זיבה \u0003כ\u0004די \u0003חתימת\u0004 (סתימת) \u0003פי האמה, ולא הודו לו\u0004 חכמים לר' ישמעאל, ולדעתם די לטומאה בשיעור כלשהו. ומשנתנו כשיטת חכמים, ואילו שמואל סבור כשיטת ר' ישמעאל.","ודנים בשיטה זו, \u0003מאי טעמא\u0004 \u0005[מה הטעם,\u0006 המקור בתורה\u0005]\u0006 לשיטה זו של \u0003ר' ישמעאל\u0004 — שכן \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 בדינו של הזב \"וזאת תהיה טומאתו בזובו רר בשרו את זובו \u0003או החתים בשרו מזובו\u0004 טומאתו היא\". הרי שהזיבה צריך שתהיה בה כדי חתימת האיבר.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 החלוקים על ר' ישמעאל, מה הם למדים מהכתוב הזה? — לדעתם הכתוב \u0003ההוא מבעי ליה\u0004 \u0005[נצרך לו]\u0006 ללמד הלכה אחרת בדיני הזב, שרק זוב \u0003לח\u0004 שיש בו כדי להחתים את בשר האדם, בהיותו נוזלי, הוא ש\u0003מטמא\u0004 בזיבה, \u0003ואינו מטמא\u0004 בהיותו \u0003יבש.\u0004","ושואלים לצד האחר, \u0003ור' ישמעאל\u0004 שלמד מכתוב זה את שיטתו בשיעור הזיבה, מנין הוא למד את ההלכה שרק הזיבה הלחה היא שמטמאה? ומשיבים: הדין \u0003ההוא מ\u0004הכתוב באותו פסוק \"וזאת תהיה טומאתו בזובו \u0003רר\u0004 בשרו את זובו\" \u0003נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005].\u0006","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 שלמדו את דין הזיבה הלחה שמטמאה מ\"או החתים\" מה למדים הם מהכתוב \"רר בשרו את זובו\"? — לדעתם הכתוב \u0003ההוא למנינא\u0004 \u0005[ל\u0006למדנו את \u0005מספר]\u0006 ראיות הזיבה, שבהן נטמא הזב \u0003הוא דאתא\u0004 \u0005[שבא].\u0006 נאמר בכתוב \"וזאת תהיה טומאתו בזובו רר בשרו את זובו או החתים בשרו מזובו טומאתו היא\", וללמדנו: \u0003\"זובו\"\u0004 — הרי זו ראיה \u0003חדא\u0004 \u0005[אחת],\u0006 \u0003\"רר בשרו\"\u0004 — הרי זו \u0003תרי\u0004 \u0005[שתי]\u0006 ראיות, \u0003\"את זובו\"\u0004 — הרי זו \u0003תלת\u0004 \u0005[שלוש]\u0006 ראיות. ומכאן \u0003לימד\u0004 הכתוב \u0003על זב בעל שלש ראיות ש\u0004הוא \u0003חייב בקרבן.\u0004","ומסוף הפסוק בו נאמר \u0003\"או החתים בשרו מזובו טמא\u0004 הוא\" למדים כי \u0003מקצת זובו,\u0004 אף זה שלא ראה שלוש ראיות זיבה, הריהו \u0003טמא.\u0004 ומכאן \u0003לימד\u0004 הכתוב \u0003על זב בעל שתי ראיות ש\u0004אף שאינו מביא קרבן, הריהו \u0003מטמא משכב ומושב.\u0004 ושואלים: \u0003ו\u0004לשיטת \u0003ר' ישמעאל,\u0004 שלמד מהכתוב \"רר בשרו את זובו\" שאין הזיבה מטמאה אלא בלחה, \u0003מנינא מנא ליה\u0004 \u0005[מניין\u0006 הראיות שהזב נטמא בהן \u0005מנין לו]?\u0006 ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא,\u0006 נלמד \u0005לו]\u0006 דין זה \u0003מ\u0004דרשתו של ר' סימאי.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' סימאי אומר:\u0004 נאמר בזב \"איש איש כי יהיה זב מבשרו זובו טמא הוא. וזאת תהיה טומאתו בזובו רר בשרו את זובו.. טומאתו היא\". שם, ב—ג). הרי ש\u0003מנה הכתוב\u0004 בפסוק הראשון \u0003שתים\u0004 ראיות של זיבה (\"זב מבשרו\", \"זובו\") — \u0003וקראו \"טמא\"\u0004 (\"טמא הוא\"). ולאחר מכן, בפסוק הבא, חזר הכתוב ומנה \u0003שלש\u0004 ראיות (\"זובו\", \"רר בשרו\", \"את זובו\") — \u0003וקראו \"טמא\"\u0004 (\"טומאתו היא\"). \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 ניישב שני כתובים אלה? אלא ב\u0003שתים\u0004 ראיות — הריהו זב \u0003ל\u0004ענין \u0003טומאה\u0004 בלבד, \u0003ו\u0004אילו ב\u0003שלש\u0004 ראיות — הריהו זב אף \u0003ל\u0004ענין \u0003קרבן.\u0004","ושואלים: \u0003ולמאן דנפקא ליה תרוייהו\u0004 \u0005[ולמי,\u0006 לחכמים החולקים על ר' ישמעאל, כפי שהוסברו דבריהם למעלה, שיוצאים, שנלמדים \u0005להם שניהם,\u0006 גם דין הטומאה וגם דין הקרבן\u0005]\u0006 \u0003מ\u0004האמור בפסוק השני, \"ו \u0003זאת תהיה טומאתו בזובו...\u0004 טומאתו היא\", אם כן האמור בפסוק הקודם \u0003\"איש איש כי יהיה זב מבשרו\" מאי עביד ליה\u0004 \u0005[מה עושה בו,\u0006 מה הוא לומד ממנו\u0005]?\u0006 ומשיבים: \u0003מבעי ליה\u0004 \u0005[נצרך לו]\u0006 כתוב זה ללמדנו כי אין הזב נטמא אלא \u0003עד שיצא\u0004 הזיבה \u0003מבשרו.\u0004","ואילו סופו של הפסוק הקודם שנאמר בו \u0003\"זובו טמא\" למה לי? לימד על הזוב\u0004 (טיפת הזיבה כשלעצמה) שלא רק שהוא מטמא את האדם שזב ממנו, אלא \u0003ש\u0004אף \u0003הוא,\u0004 הזוב עצמו, \u0003טמא\u0004 ומטמא אחרים במגעו.","שנינו שהזיבה ושכבת הזרע נטמאים בה הזב ובעל הקרי בכל שהוא. \u0003אמר רב חנילאי משום\u0004 \u0005[בשם]\u0006 \u0003ר' אלעזר בר' שמעון:\u0004 שיעור \u0003שכבת זרע\u0004 המטמא, \u0003ל\u0004איש ה\u0003רואה\u0004 שכבת זרע — טומאתו \u0003במשהו,\u0004 ואילו \u0003לנוגע\u0004 בשכבת זרע — רק כשיש \u0003ב\u0004שכבת הזרע שיעור \u0003כעדשה.\u0004 ושואלים: \u0003והאנן\u0004 \u0005[והרי אנו]\u0006 כי הזיבה ושכבת הזרע \u0003מטמאין בכל שהן תנן\u0004 \u0005[שנינו]\u0006 במשנתנו. \u0003מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה \u0003ל\u0004אדם ה\u0003נוגע\u0004 בשכבת זרע, שנטמא בכלשהו! ודוחים: \u0003לא,\u0004 הכוונה היא \u0003ל\u0004אדם ה\u0003רואה\u0004 שכבת זרע, אבל הנוגע אינו נטמא בפחות מכעדשה.","ומביאים ראיה, \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע] מברייתא: \u0003חומר\u0004 (חומרה) יש \u0003ב\u0004טומאת \u0003שכבת זרע\u0004 יותר \u0003מב\u0004 טומאת ה\u0003שרץ.\u0004 \u0003ו\u0004כן יש \u0003חומר\u0004 דין \u0003ב\u0004טומאת ה\u0003שרץ\u0004 יותר \u0003מב\u0004 טומאת \u0003שכבת זרע.\u0004 ומפרטים: \u0003חומר ב\u0004טומאת ה\u0003שרץ\u0004 מטומאת שכבת זרע — \u0003ש\u0004כן \u0003שרץ אין חלוקה\u0004 (הבחנה) ב\u0003טומאתו\u0004 של השרץ, \u0003מה שאין כן בשכבת זרע,\u0004 שיש המטמא ויש שאינו מטמא. ומן הצד האחר, יש \u0003חומר ב\u0004טומאת \u0003שכבת זרע\u0004 — \u0003ש\u0004כן \u0003השכבת זרע מטמא בכל\u0004 שיעור \u0003שהוא, מה שאין כן בשרץ,\u0004 שאינו מטמא בפחות משיעור כעדשה.","\u0003מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה בדברי הברייתא הללו ששכבת הזרע מטמאה בכל שהוא \u0003לנוגע\u0004 בה? ושלא כדברי רב חנילאי! ודוחים: \u0003לא,\u0004 הכוונה היא דווקא \u0003לרואה\u0004 שכבת זרע, אבל הנוגע בשכבת זרע אינו נטמא בפחות מכעדשה.","ושואלים על כך: \u0003והא דומיא\u0004 \u0005[והרי בדומה]\u0006 ל\u0003שרץ קתני\u0004 \u0005[שנה]\u0006 את דינה של שכבת הזרע, ומן ההשוואה לשרץ נאמר: \u0003מה\u0004 טומאת \u0003שרץ\u0004 — הריהי טומאה הבאה \u0003בנגיעה, אף\u0004 הטומאה האמורה בברייתא ב\u0003שכבת זרע\u0004 — היא טומאה הבאה \u0003בנגיעה! אמר רב אדא בר אהבה\u0004 בתשובה: אין ההשוואה בברייתא בין דרך טומאת שכבת זרע ודרך טומאת השרץ, אלא \u0003שום\u0004 \u0005[שם,\u0006 מהות\u0005]\u0006 טומאת \u0003שרץ קתני\u0004 \u0005[שנינו],\u0006 \u0003ושום\u0004 \u0005[ושם]\u0006 \u0003שכבת זרע קתני\u0004 \u0005[שנינו],\u0006 שטומאתו של השרץ בנגיעה בשיעור כעדשה, וטומאתה של שכבת זרע בראיה היא בשיעור כלשהו.","ושואלים עוד: \u0003ו\u0004האם ה\u0003שרץ לא מטמא\u0004 אף \u0003ב\u0004שיעור \u0003משהו? והא אנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה במסכת אהלות\u0005]:\u0006 \u0003האברים\u0004 של הדברים המטמאים (כגון המת, הנבילה, השרץ) \u0003אין להם שיעור\u0004 לטומאתם, אם הם שלמים, ואף איבר שיש בו \u0003פחות מ\u0004כשיעור \u0003כזית,\u0004 והוא מ\u0003בשר המת, ו\u0004כן איבר שיש בו \u0003פחות מכזית\u0004 והוא מ\u0003בשר נבלה, ו\u0004כן איבר שיש בו שיעור \u0003פחות מכעדשה\u0004 והוא \u0003מן השרץ,\u0004 הרי כל אלו מטמאים. וכיצד זה שנינו בברייתא שיש שיעור לטומאת השרץ, בכעדשה?","ומשיבים: \u0003שאני\u0004 \u0005[שונה,\u0006 מיוחד\u0005]\u0006 הוא דינו של \u0003אבר\u0004 מן השרץ, שמטמא אף בפחות משיעור כעדשה — משום \u0003דכוליה\u0004 \u0005[שכולו,\u0006 שהוא בשלימותו\u0005]\u0006 \u0003במקום\u0004 שיעור כ\u0003עדשה קאי\u0004 \u0005[עומד,\u0006 נחשב\u0005].\u0006 וראיה לדבר, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003אילו חסר פורתא\u0004 \u0005[מעט]\u0006 מ\u0003אבר\u0004 השרץ (ואין בו שיעור כעדשה) — \u0003מי קמטמיא\u0004 \u0005[האם הוא מטמא]?!\u0006","שנינו בברייתא כי \u0003שכבת זרע חלוקה טומאתו,\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 עניינה של חלוקה זו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהכוונה שחלוקה טומאת שכבת זרע \u0003בין ישראל\u0004 שנוהגת בהם \u0003ל\u0004בין ה\u0003גוים\u0004 שאינה נוהגת בהם — \u0003הכי נמי איכא\u0004 \u0005[כך גם כן יש]\u0006 חלוקה בטומאת השרץ, בין \u0003עכבר\u0004 של \u0003ים\u0004 שאינו מטמא, \u0003ו\u0004בין \u0003עכבר\u0004 של \u0003יבשה\u0004 שמטמא!","\u0003אלא\u0004 הכוונה היא שחלוקה טומאת שכבת זרע \u0003בין\u0004 זו של ה\u0003קטן\u0004 (שאין נחשבת שכבת זרע, ואינו מטמא בה) \u0003ל\u0004בין זו של ה\u0003גדול\u0004 (שמטמא בה). בעוד שבטומאת השרץ אין חלוקה שכזו, בין השרץ הגדול והקטן, ששניהם מטמאים.","\u0003אמר רב פפא:\u0004 שיעורה של שכבת זרע המטמאת את הנוגע בה הוא \u0003כ\u0004תלוי במחלוקת \u0003תנאי\u0004 \u0005[תנאים].\u0006 שכן שנינו בברייתא: \u0003מנין לרבות\u0004 אף את ה\u0003נוגע בשכבת זרע,\u0004 שיהא דינו כנוגע בשרץ, שאינו נטמא אלא בשיעור כעדשה? — \u0003תלמוד לומר\u0004 בפרשת טומאת השרץ \u0003\"או איש\u0004 אשר יגע בכל שרץ אשר יטמא לו\" (ויקרא כב, ה). ולשון ריבוי זה באה ללמד שאף בטומאת שכבת זרע כך הדין.","\u0003ופליגי תנאי בעלמא\u0004 \u0005[ונחלקו תנאים בכלל],\u0006 בכללי דרך הלימוד של דבר אחד מחבירו, \u0003דאיכא דאמרי\u0004 \u0005[שיש שאומרים]:\u0006 שבכל מקרה בו נלמד דינו של דבר אחד מדינו של דבר אחר, יש ל\u0003דון\u0004 (ללמוד) \u0003מינה\u0004 \u0005[ממנה,\u0006 מהדבר המלמד\u0005],\u0006 \u0003ו\u0004ללמוד עוד \u0003מינה\u0004 \u0005[ממנה]\u0006 אף לשאר הדברים שיש בדבר המלמד שינהגו בדבר הנלמד. \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]:\u0006 \u0003דון מינה\u0004 \u0005[ממנה]\u0006 \u0003ו\u0004אולם \u0003אוקי באתרא\u0004 \u0005[העמד\u0006 אותה, את הדבר הנלמד \u0005במקומה],\u0006 שאין להעתיק כל האמור בדבר המלמד ולתיתו בדבר הנלמד. ומחלוקת תנאים זו שייכת אף בענייננו.","שכן \u0003למאן דאמר\u0004 \u0005[למי שאומר]\u0006 \u0003דון מינה ומינה\u0004 \u0005[ממנה וממנה],\u0006 נאמר: \u0003מה שרץ\u0004 — טומאתו \u0003בנגיעה, אף שכבת זרע\u0004 — טומאה יש בה גם \u0003בנגיעה.\u0004 \u0003ו\u0004עוד נוסיף ונלמד \u0003מינה\u0004 \u0005[ממנה],\u0006 מטומאת שרץ לטומאת שכבת זרע, באופן זה: \u0003מה\u0004 טומאת ה\u0003שרץ\u0004 — שיעורה \u0003בכעדשה, אף\u0004 טומאת \u0003שכבת זרע\u0004 — שיעורה \u0003בכעדשה.\u0004","\u0003ולמאן דאמר\u0004 \u0005[ולמי שאומר]\u0006 \u0003דון מינה ואוקי באתרא\u0004 \u0005[למד ממנה ו\u0006אולם \u0005העמד\u0006 אותה \u0005במקומה],\u0006 יש לומר: \u0003מה שרץ\u0004 — \u0003בנגיעה, אף שכבת זרע\u0004 — \u0003בנגיעה, ואוקי באתרא\u0004 \u0005[והעמד\u0006 את טומאת שכבת זרע \u0005במקומה]\u0006 — \u0003מה שכבת זרע, לרואה\u0004 עצמו — שיעור טומאתה הוא \u0003במשהו, אף לנוגע\u0004 בשכבת זרע — שיעור טומאתה הוא \u0003במשהו.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נתן לרב פפא\u0004 בשאלה על דבריו אלו: \u0003ממאי\u0004 \u0005[ממה,\u0006 מניין לך\u0005]\u0006 \u0003שמ\u0004 הכתוב \u0003\"או איש\"\u0004 האמור בטומאת \u0003שרץ קמרבי ליה\u0004 \u0005[הוא מרבה אותו]\u0006 את דין הנוגע בשכבת זרע, \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003מ\u0004האמור בפסוק הקודם \u0003\"או איש אשר תצא ממנו שכבת זרע\",\u0004 שעניינו טומאת שכבת זרע, \u0003קמרבי ליה\u0004 \u0005[הוא מרבה אותו],\u0006 את הנוגע בשכבת זרע. \u0003ו\u0004הרי \u0003דכולי עלמא\u0004 \u0005[שכולם,\u0006 כל התנאים\u0005]\u0006 מסכימים שכאשר דבר נלמד מעניינו, אנו אומרים \u0003דון מינה ומינה\u0004 \u0005[ממנה וממנה],\u0006 ונסיק, שכשם שלמדנו דין נגיעה בשכבת זרע מדין ראייתה שמטמאה, כן נלמד לשיעור טומאת נגיעתה שמטמאת בכלשהו, כראייתה!","ונמסר כי \u0003שיילינהו לתנאי\u0004 \u0005[שאלו את התנאים,\u0006 שוני המשניות והברייתות\u0005]\u0006 כיצד הם גורסים בברייתא זו, האם נלמד דין הנגיעה בשכבת זרע מ\"או איש\" האמור בטומאת שרץ או מ\"או איש\" האמור בטומאת שכבת זרע, \u0003איכא דתני\u0004 \u0005[יש\u0006 מהם \u0005ששנה]\u0006 ברייתא זו \u0003כרב פפא,\u0004 שנלמד דין הנגיעה בשכבת זרע מ\"או איש\" האמור בטומאת השרץ, \u0003ואיכא דתני\u0004 \u0005[ויש ששנה]\u0006 בברייתא זו \u0003כרב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נתן,\u0004 שדין נגיעה בשכבת זרע נלמד מ\"או איש\" האמור בשכבת זרע.","ה\u0003תנוקת\u0004 אף שהיא \u0003בת יום אחד\u0004 שראתה דם \u0003מטמאה\u0004 (נטמאת) \u0003ב\u0004טומאת ה\u0003נדה.\u0004 והתינוקת שהיא \u0003בת עשרה ימים,\u0004 שראתה דם במשך שלושה ימים בזה אחר זה, לאחר שבעת ימי נדות — הריהי \u0003מטמאה\u0004 (נטמאת) \u0003בזיבה,\u0004 להיות נחשבת \"זבה גדולה\".","ה\u0003תנוק בן יום אחד\u0004 — \u0003מטמא\u0004 (נטמא) \u0003בזיבה.\u0004 \u0003ו\u0004עוד: התינוק בן יום אחד \u0003מטמא בנגעים\u0004 להיחשב כמצורע, \u0003ומטמא בטמא\u0004 (בטומאה הבאה על ידי) \u0003מת.\u0004 \u0003וזוקק\u0004 (מזקיק את אשת אחיו שמת בלא בנים) \u0003ליבום\u0004 על ידו, \u0003ו\u0004אם מת אדם ולא השאיר אחריו אלא תינוק בן יום אחד, הריהו \u0003פוטר\u0004 את אשת המת \u0003מן\u0004 חובת \u0003היבום,\u0004 ורשאית היא להינשא לכל אדם. \u0003ו\u0004אם היה תינוק זה בן לאם ישראלית ואביו כהן, הריהו \u0003מאכיל\u0004 (מתיר לאמו לאכול) \u0003בתרומה, ו\u0004מצד אחר, הריהו \u0003פוסל (את) [מן]\u0004 אכילת \u0003התרומה\u0004 את בת הכהן שנישאה לישראל ונפטר, כיון שהתינוק אינו ראוי לאכול בתרומה."],["\u0003ונוחל\u0004 התינוק בן יומו את ירושת אמו שמתה ביום לידתו, \u0003ו\u0004אם מת — הריהו \u0003מנחיל\u0004 את ירושתו (לאחיו מן האב). ועוד בדינו של התינוק בן יומו, שהרי הוא נחשב בכלל האמור ברציחה \"ואיש כי יכה כל נפש אדם מות יומת\" (ויקרא כד, יז), \u0003ו\u0004לכן האדם \u0003ההורגו חייב\u0004 על כך. \u0003ו\u0004אם נפטר \u0003הרי הוא\u0004 נחשב לענין דיני אבילות \u0003לאביו ולאמו ולכל קרוביו כחתן שלם,\u0004 שמתאבלים עליו.","שנינו במשנה שנוהגים דיני הנדה אף בקטנה שהיא בת יום אחד בלבד, ושואלים: \u0003מנהני מילי\u0004 \u0005[מנין אלו הדברים]?\u0006 ומשיבים: \u0003דתנו רבנן\u0004 \u0005[ש\u0006כן \u0005שנו חכמים]\u0006 על האמור בתורה: \"ואשה כי תהיה זבה דם יהיה זובה בבשרה שבעת ימים תהיה בנדתה\" (ויקרא טו, יט). מן הכתוב \u0003\"אשה\"\u0004 — \u0003אין לי\u0004 בכלל טומאת הנדה \u0003אלא\u0004 מי שהיא \u0003אשה\u0004 בלבד, תינוקת \u0003בת יום אחד ל\u0004ענין טומאת ה\u0003נדה מנין?\u0004 — \u0003תלמוד לומר: \"ואשה\",\u0004 לרבות אף את זו.","עוד שנינו במשנתנו כי אף התינוקת שהיא \u0003בת עשרה ימים\u0004 יכולה \u0003ל\u0004הטמא ב\u0003זיבה.\u0004 ודנים בדבר: \u0003מנא הני מילי\u0004 \u0005[מנין אלו הדברים]?\u0006 ומשיבים: \u0003דתנו רבנן\u0004 \u0005[ש\u0006כן \u0005שנו חכמים]\u0006 על האמור בתורה בדין הזבה: \"ואשה כי יזוב זוב דמה ימים רבים בלא עת נדתה או כי תזוב על נדתה כל ימי זוב טומאתה כימי נדתה תהיה טמאה היא\" (שם, כה). מן הכתוב \u0003\"אשה\"\u0004 — \u0003אין לי\u0004 בכלל טומאת הזבה \u0003אלא\u0004 מי שהיא \u0003אשה\u0004 בלבד, תינוקת \u0003בת עשרה ימים ל\u0004ענין שנוהגת אף בה טומאת ה\u0003זיבה מנין?\u0004 — \u0003תלמוד לומר: \"ואשה\",\u0004 לרבות אף את זו.","עוד שנינו במשנתנו כי ה\u0003תינוק בן יום אחד\u0004 הריהו בכלל טומאת זיבה. ושואלים בדבר: \u0003מנא הני מילי\u0004 \u0005[מנין אלו הדברים]?\u0006 ומשיבים: \u0003דתנו רבנן\u0004 \u0005[ש\u0006כן \u0005שנו חכמים]\u0006 על האמור בתורה בדין הזב \u0003\"איש איש\u0004 כי יהיה זב מבשרו זובו טמא הוא\" (שם ב). ויש לברר: \u0003מה תלמוד לומר\u0004 (מלמדנו הכתוב) בכפל הלשון \u0003\"איש איש\"?\u0004 — \u0003לרבות\u0004 את התינוק שהוא \u0003בן יום אחד ש\u0004אף הוא \u0003מטמא בזיבה,\u0004 אלו דברי ר' \u0003יהודה.\u0004 \u0003ר'\u0004","\u0003ישמעאל בנו של ר'\u0004 \u0003יוחנן בן ברוקא אומר:\u0004 דין זה \u0003אינו צריך\u0004 ללימוד זה, ש\u0003הרי הוא\u0004 הכתוב \u0003אומר\u0004 בסוף פרשת הטמאים, שבאותו פרק \u0003\"והזב את זובו לזכר ולנקבה\"\u0004 (שם, לג). והלשון הכוללת \u0003\"לזכר\"\u0004 באה ללמד: \u0003כל\u0004 מי \u0003שהוא\u0004 \"זכר\" הריהו בכלל הטומאות שנזכרו בפרשה, \u0003בין\u0004 שהוא \u0003גדול בין\u0004 שהוא \u0003קטן,\u0004 בן יום אחד. ובדומה לכך הלשון הכוללת \u0003\"לנקבה\"\u0004 — \u0003כל שהיא\u0004 נקבה, \u0003בין\u0004 שהיא \u0003גדולה בין\u0004 שהיא \u0003קטנה.\u0004 \u0003אם כן מה תלמוד לומר \"איש איש\"?\u0004 — אין זה מלמד דבר, ואשר לכפל הלשון, \u0003דברה תורה כלשון בני אדם.\u0004","\u0003ו\u0004עוד שנינו במשנתנו כי אף התינוק בין יום אחד \u0003מטמא בנגעים.\u0004 ומסבירים: דבר זה נלמד ממה \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בתורה בתחילת פרשת הנגעים: \u0003\"אדם כי יהיה בעור בשרו\u0004 שאת או ספחת או בהרת\" (שם יג, ב), ומן הלשון הכוללת \u0003\"אדם\"\u0004 יש ללמוד, כי בכלל פרשה זו \u0003כל שהו\u0004 אדם, ואף התינוק בכלל זה.","\u0003ו\u0004עוד שנינו במשנתנו כי אף התינוק בן יום אחד \u0003מטמא בטמא מת.\u0004 ומסבירים: דבר זה נלמד ממה \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בתורה בטהרה במי אפר פרה אדומה, של הנטמאים בטומאת מת: \"ולקח אזוב וטבל במים איש טהור והזה על האהל ועל כל הכלים \u0003ועל הנפשות אשר היו שם\"\u0004 (במדבר יט, יח), ומלשון כוללת זו (\"נפשות\") יש ללמוד כי בכלל טומאת מת אף \u0003נפש כל דהו\u0004 \u0005[שהוא],\u0006 ובכלל זה התינוק בן יומו.","\u0003ו\u0004עוד שנינו במשנתנו כי אף התינוק בן יום אחד \u0003זוקק\u0004 את אשת אחיו שמת בלא בנים \u0003ליבום.\u0004 ומסבירים: נלמד דבר זה, ממה \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בתורה בדין הייבום: \u0003\"כי ישבו אחים יחדיו\u0004 ומת אחד מהם ובן אין לו לא תהיה אשת המת החוצה לאיש זר יבמה יבוא עליה ולקחה לו לאשה ויבמה\" (דברים כה, ה). ומן האמור \"ישבו אחים יחדיו\" הרינו למדים שדין זה של יבום בכל ה\u0003אחים שהיה להם ישיבה אחת בעולם,\u0004 ואף התינוק שהיה בן יומו, כשמת אחיו היתה לו ישיבה אחת בעולם עם אחיו, ומחייב את אשת אחיו בייבום.","\u0003ו\u0004עוד שנינו במשנתנו כי מי שנפטר והשאיר אחריו תינוק שאף שאינו אלא בן יום אחד, הריהו \u0003פוטר\u0004 את אשת המת \u0003מן\u0004 חובת \u0003היבום.\u0004 ומסבירים: נלמד דבר זה, שכן במצות הייבום \"ומת אחד מהם \u0003ובן אין לו\"\u0004 (שם שם) \u0003אמר רחמנא\u0004 \u0005[הכתוב],\u0006 \u0003ו\u0004אילו \u0003הא\u0004 \u0005[זה]\u0006 הנפטר הלא \u0003אית ליה\u0004 \u0005[יש לו]\u0006 בן אף שהוא בן יום אחד.","\u0003ו\u0004עוד שנינו במשנתנו כי התינוק בן יומו שהוא בן לכהן שנפטר \u0003מאכיל בתרומה\u0004 את אמו הישראלית. ומסבירים: דבר זה נלמד ממה \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בזכאים לאכול בתרומה מכוחו של הכהן: \u0003\"ויליד ביתו הם יאכלו בלחמו\"\u0004 (ויקרא כב, יא), שאף שנאמר בלשון \"\u0003יאכלו בלחמו\"\u0004 \u0003קרי ביה\u0004 \u0005[קרא בו,\u0006 בכתוב זה\u0005]:\u0006 הם יאכילו בלחמו, שמכוח בנה הכהן אוכלת אף אמו הישראלית, לאחר פטירת האב הכהן.","\u0003ו\u0004עוד שנינו במשנתנו כי התינוק בן יומו הנולד לאמו הכהנת שנישאה לישראל, ומת, אף שהיא חוזרת לבית אביה הכהן, תינוק זה \u0003פוסל\u0004 אותה \u0003מן\u0004 הזכות לשוב ולאכול מ\u0003התרומה.\u0004 וטעם הדבר, שכן האשה בת הכהן שהתאלמנה או התגרשה מבעלה הישראלי, חוזרת לאכול בתרומה \u0003\"וזרע אין לה\u0004 ושבה אל בית אביה כנעוריה מלחם אביה תאכל\" (שם יג) \u0003אמר רחמנא\u0004 \u0005[הכתוב],\u0006 \u0003ו\u0004אילו \u0003הא אית\u0004 \u0005[זו יש]\u0006 \u0003לה\u0004 זרע מבעלה הישראלי.","ושואלים: \u0003מאי איריא\u0004 \u0005[מדוע דווקא]\u0006 משמיענו הכתוב שאם יש לה \u0003זרע\u0004 (ולד חי) מבעלה הישראלי הריהי פסולה מלאכול בתרומה, והרי \u0003אפילו\u0004 אם יש לה \u0003עובר\u0004 מבעלה הישראלי \u0003נמי\u0004 \u0005[גם כן]\u0006 כך הדין, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בענין בת כהן שהתאלמנה או נתגרשה לאכול בתרומה \"ושבה אל בית אביה \u0003כנעוריה\"\u0004 — שדווקא זו שהריהי כבימי נעוריה אוכלת שוב בתרומה, \u0003פרט ל\u0004שבה אל בית אביה כשהיא \u0003מעוברת\u0004 מן הישראלי, שאינה אוכלת בתרומה!","\u0003ו\u0004משיבים: \u0003צריכי\u0004 \u0005[נצרכים]\u0006 שני הלימודים הללו, שהתינוק הנולד לכהנת מן הישראלי פוסל אותה מלשוב ולאכול בתרומת בית אביה, ושעובר הכהנת מן הישראלי פוסל אותה מלשוב ולאכול בתרומת בית אביה. \u0003דאי כתב רחמנא\u0004 \u0005[שאם היתה כותבת התורה]\u0006 רק את הפסוק \u0003\"וזרע אין לה\"\u0004 ללמדנו שאינה אוכלת בגלל שיש לה ילד מן הישראלי — הייתי אומר כי דין זה הריהו \u0003משום דמעיקרא חד גופא\u0004 \u0005[מתחילה\u0006 קודם שנישאה היתה האשה הזו \u0005גוף אחד],\u0006 \u0003והשתא תרי גופי\u0004 \u0005[ועכשיו\u0006 הריהי \u0005שני גופים,\u0006 היא ותינוקה\u0005],\u0006 ולכן אין זו ממש שיבה לבית אביה. \u0003אבל הכא\u0004 \u0005[כאן,\u0006 במעוברת מן הישראלי\u0005],\u0006 השבה לבית אביה, \u0003דמעיקרא חד גופא, והשתא חד גופא\u0004 \u0005[שמתחילה\u0006 היתה \u0005גוף אחד, ועכשיו\u0006 היא גם כן \u0005גוף אחד]\u0006 — \u0003אימא תיכול\u0004 \u0005[אמור\u0006 ש\u0005תאכל]\u0006 בתרומת בית אביה. לכן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"כנעוריה\"\u0004 ללמדנו שאף המעוברת השבה לבית אביה אינה אוכלת בתרומה.","\u0003ו\u0004מן הצד האחר, \u0003אי כתב רחמנא\u0004 \u0005[אם היתה התורה כותבת]\u0006 רק \u0003\"כנעוריה\"\u0004 — הייתי אומר שנוהג דין זה \u0003משום דמעיקרא גופה סריקא, והשתא גופה מליא\u0004 \u0005[שמתחילה\u0006 היתה אשה זו \u0005גוף ריק, ועכשיו\u0006 היא \u0005גוף מלא]\u0006 ואין זו שיבה ממש לבית אביה, \u0003אבל הכא\u0004 \u0005[כאן,\u0006 במי שיש לה תינוק\u0005],\u0006 \u0003דמעיקרא גופה סריקא והשתא גופה סריקא\u0004 \u0005[שמתחילה גוף ריק, ועכשיו גוף ריק]\u0006 \u0003אימא תיכול\u0004 \u0005[אמור\u0006 ש\u0005תאכל]\u0006 בתרומת בית אביה, לכן \u0003צריכא\u0004 \u0005[נצרכו]\u0006 שני המקראות הללו.","ושואלים: \u0003קראי\u0004 — \u0003אתרוץ\u0004 \u0005[המקראות תורצו,\u0006 הוסברו\u0005]\u0006 מדוע נצרכו שניהם, ומה כל כתוב מלמדנו. \u0003אלא\u0004 על מתניתין \u0005[משנתנו]\u0006 עדיין יש לשאול: \u0003מאי אריא\u0004 \u0005[מדוע דווקא]\u0006 ציינה המשנה שתינוק \u0003בן יום אחד\u0004 פוסל את אמו שנישאה לישראל מלאכול שוב בתרומת אביה הכהן, והרי \u0003אפילו\u0004 בעובר \u0003נמי\u0004 \u0005[גם כן]\u0006 הדין כן! \u0003אמר רב ששת: הכא במאי עסקינן\u0004 \u0005[כאן,\u0006 במשנתנו, \u0005במה אנו עוסקים]\u0006 \u0003ב\u0004מקרה של \u0003כהן שיש לו שתי נשים: אחת גרושה\u0004 שנשאה שלא כדין, שהרי הגרושה אסורה על הכהן. \u0003ואחת שאינה גרושה.\u0004 \u0003ויש לו בנים מ\u0004האשה \u0003שאינה גרושה, ויש לו\u0004 תינוק \u0003בן יום אחד מן הגרושה,\u0004 והרי תינוק זה הוא חלל, האסור באכילת תרומה.","והשמיעה לנו המשנה ש\u0003פוסל\u0004 תינוק זה \u0003בעבדי אביו מלאכול\u0004 שוב \u0003בתרומה.\u0004 שמכיון שתינוק זה יש לו חלק בירושת אביו, ובכלל זה אף בעבדים אלו, הם אינם יכולים עוד לאכול בשל היותם גם עבדיו של הפסול לאכילת תרומה. \u0003ו\u0004באה משנתנו \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004שיטת \u0003ר' יוסי\u0004 ש\u0003אמר\u0004 ש\u0003עובר\u0004 שהוא חלל \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003פוסל\u0004 את עבדי אביו מלאכול בתרומה, לכן \u0003קא משמע לן\u0004 \u0005[הוא\u0006 התנא שבמשנתנו \u0005משמיע לנו]\u0006 שדווקא \u0003בן יום אחד\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 פוסל את עבדי אביו מלאכול בתרומה, ואולם ה\u0003עובר\u0004 — \u0003לא\u0004 פוסל.","\u0003ו\u0004עוד שנינו במשנתנו כי התינוק בן יומו \u0003נוחל ומנחיל.\u0004 ודנים במה ששנינו כי התינוק בן יומו \u0003נוחל,\u0004 \u0003ממאן\u0004 \u0005[ממי]\u0006 הוא נוחל? — \u0003מאביו, ו\u0004מה ששנינו כי התינוק בן יומו \u0003מנחיל, למאן\u0004 \u0005[למי]\u0006 הוא מנחיל? — \u0003לאחיו מאביו,\u0004 שהרי אחיו מן האם אינם יורשים אותו. ויש לשאול: מה באה משנתנו ללמדנו שאחיו יורש אותו, והלא \u0003אי בעי\u0004 \u0005[אם ירצה]\u0006 אח זה \u0003מאבוה לירתי\u0004 \u0005[מאביו יירש],\u0006 \u0003ואי בעי\u0004 \u0005[ואם ירצה]\u0006 — \u0003מיניה לירתי\u0004 \u0005[ממנו,\u0006 מתינוק זה \u0005יירש],\u0006 שהרי אף בלא שיוריש לו התינוק, יורש הוא מאביו ישירות!","\u0003אמר רב ששת:\u0004 כוונת המשנה ללמדנו שהתינוק בן יומו \u0003נוחל בנכסי האם\u0004 שאיננה אמם של אחיו מאביו, שרק הוא יכול לירש אותה, ולא הם. ואם ימות לאחר שירש ירושה זו, יש בו \u0003להנחיל\u0004 ירושתו זו \u0003לאחיו מן האב.\u0004 ומסבירים את דין משנתנו עוד, \u0003ודוקא בן יום אחד\u0004 נוחל בנכסי אמו שמתה, ומנחיל לאחיו מן האב, \u0003אבל עובר\u0004 (שמתה אמו, והוא עצמו לא נולד) — \u0003לא\u0004 נאמר בו שיורש את נכסי אמו ומורישם לאחיו מן האב. ו\u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — שכן ברור ש\u0003הוא\u0004 העובר \u0003מיית ברישא\u0004 \u0005[מת בתחילה]\u0006 לפני שמתה אמו, \u0003ו\u0004כלל הוא ש\u0003אין הבן יורש את אמו\u0004"],["בהיותו \u0003בקבר\u0004 (כשהוא מת) כדי \u0003להנחיל\u0004 את ירושת אמו זו \u0003לאחיו מן האב.\u0004","ושואלים: \u0003איני\u0004 \u0005[והאמנם כך],\u0006 וכי ודאי שמת העובר לפני שמתה אמו, \u0003והא הוה עובדא\u0004 \u0005[והרי היה מעשה]\u0006 במעוברת שמתה, והוציאו ממעיה את העובר שהיה בה, \u0003ופרכס עד תלת פרכוסי\u0004 \u0005[שלושה פרכוסים],\u0006 הרי שיש אפשרות שהעובר ימשיך לחיות גם לאחר מות אמו! \u0003אמר מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אשי:\u0004 לא היו אלה תנועות של יצור חי, אלא הרי זה \u0003מידי דהוה\u0004 \u0005[דבר שהינו]\u0006 כעין \u0003זנב הלטאה\u0004 ש\u0003מפרכסת\u0004 אף לאחר שנקטעה מגוף הלטאה, שאין בה חיים.","\u0003מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא אמר\u0004 הסבר אחר באשר למה שמחדשת לנו משנתנו האומרת כי התינוק בן יומו נוחל ומנחיל: \u0003לומר\u0004 (ללמד) \u0003ש\u0004התינוק בן יום אחד \u0003ממעט בחלק\u0004 ה\u0003בכורה\u0004 של אחיו הבכור. שכיון שנולד בחיי אביו, אף הוא בכלל יורשיו, ונמצא שחלק הבכור שהוא כרגיל כנגד שני חלקים של שאר היורשים הנמצאים בשעת פטירת האב נעשה קטן יותר, שהרי משנולד זה מתחלקת הירושה ליותר יורשים. \u0003ו\u0004עוד \u0003אמר מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: בן שנולד אחר מיתת האב\u0004 — \u0003אינו ממעט בחלק בכורה, מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — שכן נאמר בפרשת זכות ירושת הבכור \u0003\"וילדו לו\u0004 בנים...\" (דברים כא, טו), ללמדנו כי \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 לקיום זכות ירושת הבכור שיהיו כל היורשים בנים לאביהם, ואין בכלל זה מי שנולד לאחר מות אביו.","ומעירים: \u0003בסורא מתנו הכי\u0004 \u0005[שנו כך]\u0006 את דברי מר בנו של רב יוסף, כפי שאמרנו. ואילו \u0003בפומבדיתא מתנו הכי\u0004 \u0005[שנו כך]\u0006 את דבריו: \u0003אמר מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: בכור שנולד לאחר מיתת אביו\u0004 — \u0003אינו נוטל פי שנים\u0004 כשאר בכור, \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — שכן נאמר בדין הבכור \"כי את הבכור... \u0003יכיר\u0004 לתת לו פי שנים\" (שם יז), ללמדנו כי \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 לקיום זכות ירושת הבכור שיכיר האב את בנו הבכור, \u0003והא ליכא\u0004 \u0005[ו\u0006תנאי \u0005זה אין כאן],\u0006 שהרי נולד לו לאחר מותו.","ומסכמים: \u0003והלכתא\u0004 \u0005[וההלכה],\u0006 \u0003ככל הני לישני\u0004 \u0005[אלה הלשונות]\u0006 של \u0003מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף\u0004 שאמר \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא.\u0004","\u0003ו\u0004עוד שנינו במשנתנו כי \u0003ההורגו\u0004 את התינוק בן יום אחד, \u0003חייב.\u0004 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בדינו של הרוצח: \u0003\"ואיש כי יכה כל נפש\u0004 אדם מות יומת\" (ויקרא כד, יז), ולשון כוללת זו (\"כל נפש\") באה להורות כי חייב הרוצח \u0003מכל מקום,\u0004 על כל נפש שרצח.","\u0003ו\u0004עוד שנינו במשנתנו בדין התינוק בן יום אחד כי \u0003הרי הוא לאביו ולאמו ולכל קרוביו כחתן שלם.\u0004 ומבררים: \u0003למאי הלכתא\u0004 \u0005[למה,\u0006 לענין איזו \u0005הלכה]\u0006 נאמרה קביעה זו? \u0003אמר רב פפא: לענין אבלות.\u0004","ומסבירים: \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 היא שיטת משנתנו שנחשב התינוק בן יום אחד כאדם חי לכל דבריו? ש\u0003לא כ\u0004שיטת \u0003רבן שמעון בן גמליאל.\u0004 שכך \u0003אמר\u0004 רבן שמעון בן גמליאל: \u0003כל\u0004 ולד \u0003ששהה\u0004 לאחר שנולד \u0003שלשים יום, באדם\u0004 — \u0003אינו נפל.\u0004 ומדבריו נסיק: \u0003הא\u0004 \u0005[הרי]\u0006 כל עוד \u0003לא שהה\u0004 שלושים יום — \u0003ספק\u0004 נפל \u0003הוי\u0004 \u0005[הריהו]!\u0006 ומשיבים: אף משנתנו סבורה כרבן שמעון בן גמליאל, שכל שלא מלאו לו שלושים יום מלידתו, הרי הוא בכלל ספק נפל, ואולם \u0003הכא במאי עסקינן\u0004 \u0005[כאן\u0006 במשנתנו במה אנו עוסקים] — \u0003דקים ליה\u0004 \u0005[שעומד,\u0006 שמוחזק \u0005לו]\u0006 \u0003שכלו לו\u0004 לתינוק זה \u0003חדשיו\u0004 לתחילת ההריון, ומשעה שנולד, אין הוא בגדר נפל אלא בגדר בן קיימא.","ילדה \u0003בת שלש שנים ויום אחד\u0004 שמסרה אביה לקידושין בדרך ביאה — הריהי \u0003מתקדשת בביאה,\u0004 ככל אשה, שביאתה של בת שלוש שנים נחשבת לביאה. \u0003ו\u0004כן אם מת בעלה של הילדה בת שלוש שנים בלא זרע, והיא עומדת לפני אחיו למצוות ייבום — \u0003אם בא עליה\u0004 ה\u0003יבם, קנאה\u0004 בביאתו זו שתיחשב מעתה כאשתו לכל דיניה. \u0003ו\u0004עוד בדיניה של בת השלוש: אם היא נשואה, ובא עליה אדם אחר — \u0003חייבין עליה\u0004 מיתת בית דין \u0003משום\u0004 איסור \u0003אשת איש.\u0004","\u0003ו\u0004אם היא נדה ובא עליה בעלה — הריהי \u0003מטמאה את בועלה לטמא\u0004 מעתה את כל המצעות עליהם שכב. ודינו של ה\u0003משכב\u0004 ה\u0003תחתון\u0004 ששוכב עליו הבועל הריהו \u0003כ\u0004דינו של הבגד ה\u0003עליון\u0004 שעל גבי הזב, שזה וזה נחשבים כראשון לטומאה, ולא כאב הטומאה, והריהם מטמאים רק אוכלים ומשקים, אך לא אדם וכלים.","ועוד בדיניה של בת השלוש, שאם היא ישראלית ו\u0003נשאת\u0004 על ידי אביה \u0003לכהן\u0004 — הרי זו \u0003תאכל בתרומה\u0004 ככל אשת כהן. ואם אינה נשואה ו\u0003בא עליה אחד מן הפסולין\u0004 לכהונה, וכגון ממזר או חלל — \u0003פסלה\u0004 בכך \u0003מן הכהונה,\u0004 שאינה רשאית להינשא לכהן. וכן אם היא בתו של כהן, מעתה שוב אין היא אוכלת בתרומה. ועוד בדיניה של זו, שאם \u0003בא עליה אחד מכל העריות האמורות בתורה,\u0004 וכגון אביה או אבי בעלה — הם \u0003מומתין\u0004 (חייבים מיתת בית דין) \u0003עליה, ו\u0004אולם \u0003היא\u0004 עצמה, הריהי \u0003פטורה\u0004 מעונש על כך, שהרי אין היא בת עונשין.","כל הדינים האמורים למעלה, הריהם דווקא במי שהיא בת שלוש ויותר, ואולם היא בת \u0003פחות מכן\u0004 — אין הביאה עליה נחשבת כביאה, ואין זה אלא \u0003כ\u0004אדם ה\u0003נותן אצבע בעין,\u0004 שהעין נלחצת ודומעת, אך שבה לאחר מכן למצבה הקודם. וכמו כן הקטנה בת פחות משלוש שנים בתוליה חוזרים.","שנינו במשנתנו כי בת שלוש שנים ויום אחד מתקדשת בקידושי ביאה, ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בת שלש שנים מתקדשת בביאה, דברי ר'\u0004 \u0003מאיר.\u0004 \u0003ו\u0004אילו \u0003חכמים אומרים:\u0004 אין מתקדשת בביאה אלא מי שהיא \u0003בת שלש שנים ויום אחד.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה,\u0006 איזה הבדל להלכה\u0005]\u0006 יש \u0003בינייהו\u0004 \u0005[ביניהם],\u0006 שהרי בין לר' מאיר ובין לחכמים אינה מתקדשת אלא משימלאו לה שלוש שנים? ומשיבים: \u0003אמרי דבי\u0004 \u0005[אמרו\u0006 חכמי \u0005בית\u0006 המדרש\u0005]\u0006 של \u0003ר' ינאי:\u0004 בדינה של התינוקת ב\u0003ערב ראש השנה\u0004 (היום הראשון לשנה) הרביעית לחייה \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל, שלשיטת ר' מאיר הריהי מתקדשת בביאה ביום הזה, כיון שביום זה מלאו לה שלוש שנים. ואילו לשיטת חכמים אינה מתקדשת, כיון שעדיין לא באה ליום הראשון של שנתה הרביעית.","\u0003ור' יוחנן אמר:\u0004 בקביעת הדין בענין האם \u0003שלשים יום בשנה\u0004 הם \u0003חשובין שנה, איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל. שלשיטת ר' מאיר שלושים יום נחשבים כשנה, ולכן כאשר התינוקת בת שנתיים ושלושים יום, הריהי נחשבת כבר כבת שלוש, ומתקדשת בביאה. ואילו לשיטת חכמים, שלושים יום בשנה אינם נחשבים לשנה, ואין היא מתקדשת בביאה אלא כשהיא בת שלוש ויום אחד.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על הסברו זה של ר' ינאי ממה ששנינו: תינוקת \u0003בת שלש שנים, ואפילו בת שתי שנים ויום אחד\u0004 — \u0003מתקדשת בביאה,\u0004 אלו דברי ר' \u0003מאיר.\u0004 \u0003וחכמים אומרים:\u0004 אין מתקדשת בביאה אלא מי שהיא \u0003בת שלשה שנים ויום אחד.\u0004"],["ומעתה יש לשאול: \u0003בשלמא\u0004 \u0005[נוח,\u0006 אין מכאן קושיה\u0005]]\u0006 \u0003ל\u0004הסברו של \u0003ר' יוחנן,\u0004 שכן \u0003כי היכי דאיכא\u0004 \u0005[כמו שיש]\u0006 \u0003תנא דקאמר\u0004 \u0005[האומר,\u0006 הסבור\u0005]\u0006 כי \u0003יום אחד בשנה חשוב שנה,\u0004 ולכן סבור ר' מאיר בברייתא זו כי בת שנתיים ויום אחד נחשבת כבת שלוש שנים, ומתקדשת בביאה, \u0003הכי נמי איכא\u0004 \u0005[כך גם כן יש]\u0006 \u0003תנא\u0004 ש\u0003אמר\u0004 כי \u0003שלשים יום בשנה חשובין שנה,\u0004 ולשיטת ר' מאיר התינוקת מתקדשת בביאה מבת שנתיים ושלושים יום, וכדרך שהסביר ר' יוחנן.","\u0003אלא ל\u0004הסברו של \u0003ר' ינאי\u0004 שאמר בשיטת ר' מאיר שצריך שלוש שנים מלאות, \u0003קשיא\u0004 \u0005[קשה]\u0006 ברייתא זו, ששנינו בה במפורש לשיטת ר' מאיר שאפילו בת שנתיים ויום אחד מתקדשת בביאה! ומסכמים: אכן \u0003קשיא\u0004 \u0005[קשה]\u0006 ברייתא זו על הסברו של ר' ינאי.","שנינו בסוף משנתנו כי ביאתה של זו ש\u0003פחות מכאן,\u0004 מבת שלוש שנים, אינה נחשבת ביאה, והרי זה \u0003כנותן אצבע בעין\u0004 שהיא דומעת בכך, ולא נגרם נזק של ממש לעין, ובדומה לכך, אף אחר ביאה זו, יש לה בתולים. ובדבר זה \u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 לחכמי בית המדרש\u0005]\u0006 שאלה זו: \u0003הני\u0004 \u0005[אלו]\u0006 ה\u0003בתולין\u0004 של בת פחות משלוש שנים שבאו עליה לפני היותה בת שלוש, מה אירע בהם בביאה זו? האם \u0003מיזל אזלי ואתו\u0004 \u0005[הלכו\u0006 הבתולים, \u0005ובאים]\u0006 שוב לאחר מכן, \u0003או דלמא אתצודי\u0004 \u0005[שמא צידתם,\u0006 נטילתם\u0005]\u0006 של הבתולים \u0003הוא דלא מתצדי\u0004 \u0005[שאינם ניצודים,\u0006 ניטלים\u0005]\u0006 \u0003עד לאחר\u0004 שנעשית בת \u0003שלש\u0004 שנים, ולא לפני כן?","ומסבירים: \u0003למאי נפקא מינה\u0004 \u0005[למה,\u0006 לאיזה הלכה יש \u0005תוצאה ממנה,\u0006 מבעיה זו\u0005]?\u0006 — לענין \u0003כגון שבעל\u0004 כהן את התינוקת בהיותה \u0003בתוך\u0004 שלוש שנים, \u0003ומצא\u0004 אצלה דם בעקבות ביאתו זו, \u0003ו\u0004חזר ו\u0003בעל\u0004 אותה לאחר מכן שוב ושוב, וגם \u0003לאחר\u0004 שנעשתה בת \u0003שלש, ו\u0004באותה בעילה \u0003לא מצא דם.\u0004 ומעתה יש לדון: \u0003אי אמרת\u0004 \u0005[אם אתה אומר,\u0006 סבור\u0005]\u0006 כי בביאת בת פחות משלוש, הבתולים \u0003מיזל אזלי ואתו\u0004 \u0005[הלכו ושבו\u0006 אחר כך\u0005] —\u0006 בזו אפשר לומר כי הלכו בתוליה בביאתו הראשונה אותה, ואולם לא שבו משום ש\u0003שהות\u0004 (פרק זמן מספיק, ללא שיבעל אותה) \u0003הוא\u0004 ש\u0003לא הויא להו\u0004 \u0005[היה להם]\u0006 בכדי שישובו הבתולים.","\u0003אלא אי אמרת\u0004 \u0005[אם אתה אומר,\u0006 סבור\u0005]\u0006 כי בביאת בת פחות משלש הבתולים \u0003אתצודי\u0004 \u0005[צידתם,\u0006 נטילתם\u0005]\u0006 של הבתולים \u0003הוא דלא מתצדי\u0004 \u0005[שאינם ניצודים,\u0006 ניטלים\u0005]\u0006 \u0003עד לאחר\u0004 שנעשית בת \u0003שלש\u0004 שנים, ולא לפני כן, ו\u0003הא\u0004 \u0005[זה]\u0006 שלא ראתה דם לאחר שלוש שנים — משום שאדם \u0003אחר בא עליה\u0004 לאחר היותה בת שלוש שנים, והרי היא איפוא בגדר \"זונה\" האסורה לכהן. ומעתה יש לברר: \u0003מאי\u0004 \u0005[מה]\u0006 דינה של זו, ותלוי הדבר בפתרון הבעייה שנשאלה.","\u0003מתקיף לה\u0004 \u0005[מקשה עליה,\u0006 על הסבר זה של ההבדלים בין צדדי הבעייה\u0005]\u0006 \u0003רב חייא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא: ו\u0004אף אם נאמר שבביאת בת פחות משלוש שנים הבתולים הולכים ושבים, עדיין יש לחשוש בתינוקת זו שזינתה תחת בעלה הכהן, שכן \u0003מאן לימא לן\u0004 \u0005[מי יאמר לנו\u0006 בוודאות\u0005]\u0006 שה\u0003מכה\u0004 (הפגיעה בבתולים) \u0003שבתוך שלש\u0004 שנים \u0003אינה חוזרת\u0004 ונרפאת \u0003לאלתר\u0004 (מיד), \u0003שמא\u0004 הריהי \u0003חוזרת\u0004 ונרפאת \u0003לאלתר, והא\u0004 \u0005[וזו]\u0006 שלא נמצא לה דם בביאה שלאחר היותה בת שלוש שנים — משום ש\u0003אחר בא עליה,\u0004 והיא בכלל \"זונה\" האסורה לכהן!","\u0003אלא נפקא מינה\u0004 \u0005[\u0006יש \u0005תוצאה ממנה,\u0006 מבעיה זו\u0005]?\u0006 לענין \u0003כגון שבעל\u0004 אותה בהיותה \u0003בתוך שלש ומצא דם, ובעל לאחר שלש ומצא דם.\u0004 ויש לדון: \u0003אי אמרת\u0004 \u0005[אם אתה אומר,\u0006 סבור\u0005]\u0006 כי בביאת בת פחות משלוש, הבתולים \u0003מיזל אזלי ואתו\u0004 \u0005[הולכים ושבים]\u0006 — \u0003האי\u0004 \u0005[זה]\u0006 ה\u0003דם\u0004 שהיא רואה לאחר הביאה בהיותה בת שלוש שנים, דם \u0003בתולין הוא,\u0004 כשם שדם שראתה בביאתה בהיותה בת פחות משלוש שנים היה דם בתולים. \u0003אלא אי אמרת\u0004 \u0005[אם אתה אומר,\u0006 סבור\u0005]\u0006 כי בביאת בת פחות משלוש הבתולים \u0003אתצודי\u0004 \u0005[צידתם,\u0006 נטילתם\u0005]\u0006 של הבתולים \u0003הוא דלא מתצדי\u0004 \u0005[שאינם ניצודים,\u0006 ניטלים\u0005]\u0006 \u0003אלא עד לאחר שלש\u0004 שנים, ולא לפני כן — אם כן \u0003האי\u0004 \u0005[זה]\u0006 הדם שראתה לאחר ביאתה בהיותה בת פחות משלוש שנים, \u0003דם נדה הוא.\u0004 ואם כן \u0003מאי\u0004 \u0005[מה]\u0006 דינה של זו, ותלוי הדבר בפתרון הבעייה שנשאלה.","ובפתרון בעיה זו \u0003אמר רב חסדא: תא שמע\u0004 \u0005[בוא\u0006 ושמע] ראיה ממה ששנינו במשנתנו בדינה של ביאת בת \u0003פחות מכאן\u0004 משלוש שנים — הרי זה \u0003כנותן אצבע בעין.\u0004 ויש לדקדק: \u0003למה לי למתני\u0004 \u0005[לשנות]\u0006 לשון \u0003\"כנותן אצבע בעין\", לתני\u0004 \u0005[שישנה]\u0006 התנא רק את ההלכה: הבא על הקטנה \u0003פחות מכאן\u0004 — נחשב הדבר כ\u0003ולא כלום.\u0004 \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 — \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה,\u0006 ההשוואה לנתינת אצבע בעין \u0005היא משמיעה לנו]\u0006 עוד בהלכה זו: \u0003מה\u0004 נתינת אצבע ב\u0003עין\u0004 — גורמת לעין שהיא \u0003מדמעת\u0004 על ידי כך, \u0003ו\u0004אולם היא \u0003חוזרת ומדמעת\u0004 לכשתינתן בה שוב אצבע, \u0003אף בתולין\u0004 בביאת בת פחות משלוש שנים — \u0003מיזל אזלי ואתי\u0004 \u0005[הולכים ושבים].\u0006","ועוד בענין ביאת התינוקת, \u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 \u0003מעשה ב\u0004אשה גויה ושמה \u0003יוסטני\u0004 ממשפחת הקיסרות, שהיתה \u0003בתו של אסוירוס בן אנטנינוס\u0004 שהיה קיסר רומי. \u0003שבאת\u0004 (שבאה) \u0003לפני רבי.\u0004 \u0003אמרה לו: רבי, אשה בכמה ניסת,\u0004 באיזה גיל הריהי ראויה לביאה, ונישאת לאיש? \u0003אמר לה: בת שלש שנים ויום אחד.\u0004","\u0003הוסיפה ושאלה:\u0004 \u0003ובכמה\u0004 באיזה גיל הריהי \u0003מתעברת\u0004 מביאתה? \u0003אמר לה:\u0004 מהיותה \u0003בת שתים עשרה שנה ויום אחד.\u0004 \u0003אמרה לו: אני נשאתי ב\u0004היותי בת \u0003שש\u0004 שנים \u0003וילדתי\u0004 ילד לאחר שנה, \u0003ב\u0004היותי בת \u0003שבע\u0004 שנים, \u0003אוי\u0004 (חבל) \u0003ל\u0004אותן \u0003שלש שנים\u0004 שבין גיל שלוש הראויים לביאה לבין גיל שש שבו נישאתי, \u0003שאבדתי\u0004 בלא ביאה בהיותי \u0003בבית אבא!\u0004","ושואלים על דבריה שהתעברה בגיל שבע: \u0003ומי מעברה\u0004 \u0005[והאם\u0006 קטנה בגיל זה \u0005מתעברת]?\u0006 \u0003והתני\u0004 \u0005[והרי שנה]\u0006 \u0003רב ביבי קמיה\u0004 \u0005[לפני]\u0006 \u0003רב נחמן: שלש נשים משמשות במוך\u0004 כדי להימנע מהתעברות המזיקה להן, ואלו הן: ה\u0003קטנה,\u0004 ה\u0003מעוברת ו\u0004\u0003המניקה.\u0004","והסכנה שיש בעיבור לכל אחת מאלה: ה\u0003קטנה\u0004 — \u0003שמא תתעבר, ותמות\u0004 על ידי הריון זה. ה\u0003מעוברת\u0004 — \u0003שמא תעשה\u0004 על ידי עיבור נוסף את \u0003עוברה\u0004 שבמעיה ל\u0003סנדל\u0004 (מעוך). וה\u0003מניקה\u0004 — \u0003שמא\u0004 ההריון החדש יגרום לה ש\u0003תגמול\u0004 (תחדל להניק) \u0003את בנה,\u0004 \u0003ו\u0004עלול הדבר לגרום לו שימות.","\u0003ואיזוהי\u0004 המוגדרת \u0003קטנה\u0004 שמשמשת במוך — \u0003מבת אחת עשרה שנה ויום אחד ועד שתים עשרה שנה ויום אחד.\u0004 וזו שגילה \u0003פחות מכאן, א\u0004 \u0003ו יתר על כן\u0004 — הריהי \u0003משמשת והולכת\u0004 כדרכה, בלא להזדקק למוך, אלו \u0003דברי ר'\u0004 \u0003מאיר.\u0004 שבפחות מכך — אינה מתעברת עדיין, וזו שגילה מבוגר יותר — אין ההריון מסוכן לה.","\u0003וחכמים אומרים: אחת זו\u0004 שמתעברת בביאתה \u0003ואחת זו\u0004 שאינה מתעברת בביאתה — \u0003משמשת כדרכה\u0004 (ללא מוך), \u0003והולכת, ומן השמים ירחמו, שנאמר \"שומר פתאים ה' \"\u0004(תהלים קטז, ו). הרי שאין הקטנה מתעברת בגיל שכזה, וכיצד זו התעברה בגיל שבע?","ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 בתשובה: זו התעברה בגיל כה צעיר כיון שגויה היתה, ובהם נאמר \u0003\"אשר בשר חמורים בשרם\"\u0004 (יחזקאל כג, כ). \u0003ואיבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 בתשובה: אף זו לא התעברה בגיל שבע, כדבריה, ושיקרה לרבי, שכן מצוי בהם השקר, כמו שנאמר \u0003\"אשר פיהם דבר שוא וימינם ימין שקר\u0004 (תהלים קמד, ח).","ועוד בענין ביאת התינוקת, \u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 \u0003מעשה באשה אחת שבאת\u0004 (שבאה) \u0003לפני ר'\u0004 \u0003עקיבא.\u0004 \u0003אמרה לו: רבי, נבעלתי\u0004 לפסול כשהייתי \u0003בתוך שלש שנים, מה אני\u0004 (דיני) מעתה לענין להינשא \u0003לכהונה? אמר לה: כשרה את לכהונה.\u0004","\u0003אמרה לו: רבי, אמשול לך משל, למה הדבר דומה\u0004 — \u0003לתינוק שטמנו לו\u0004 בעל כורחו את \u0003אצבעו בדבש,\u0004 כדי שיאכלנו. \u0003פעם ראשונה ושניה\u0004 שעושים לו כן — הריהו \u0003גוער בה\u0004 באמו העושה לו כך, ואולם בפעם ה\u0003שלישית,\u0004 משהתרגל לטעם הדבש — \u0003מצצה\u0004 את אצבעו הטבולה בדבש, מרצונו. ורמזה לר' עקיבא, שכמה בעילות היו אלה, וביאה ראשונה ושניה היו אכן בעל כורחה, אך בפעם השלישית היה זה לרצונה. \u0003אמר לה\u0004 ר' עקיבא: \u0003אם כן\u0004 — \u0003פסולה את לכהונה.\u0004","\u0003ראה\u0004 ר' עקיבא את \u0003התלמידים\u0004 שהם \u0003מסתכלים זה בזה\u0004 כתמהים על דינו זה. \u0003אמר להם: למה הדבר קשה בעיניכם? [אמרו ליה\u0004 \u0005[לו]\u0006\u0003]: כשם שכל התורה הלכה למשה מסיני, כך\u0004 דינה של מי שנבעלה בהיותה \u0003פחותה מבת שלש שנים\u0004 שהיא \u0003כשרה לכהונה\u0004 אף זו \u0003הלכה למשה מסיני,\u0004 בין שנבעלה לפסול בעל כורחה ובין שנבעלה לרצונה. ומעירים: \u0003ואף ר'\u0004 \u0003עקיבא\u0004 שאמר כן לאשה, \u0003לא אמרה\u0004 משום שכך היא ההלכה, \u0003אלא\u0004 אך ורק כדי \u0003לחדד בה את התלמידים,\u0004 שיתמהו על דבריו אלה.","ילד \u0003בן תשע שנים ויום אחד ש\u0004מת אחיו בלא בנים, ונפלה לפניו אשת אחיו לייבום, ו\u0003בא על יבמתו\u0004 — ביאתו נחשבת כביאה, ו\u0003קנאה\u0004 ליבמתו בכך, \u0003ו\u0004אולם \u0003אין\u0004 הוא \u0003נותן\u0004 ליבמתו \u0003גט\u0004 להתירה להינשא לאדם אחר \u0003עד שיגדיל.\u0004","\u0003ו\u0004כן בן תשע שנים שבא על האשה הנדה — הרי הוא \u0003מטמא\u0004 (נטמא) \u0003ב\u0004טומאת \u0003נדה,\u0004 ככל הבועל נדה, לענין \u0003לטמא\u0004 מעתה את המצעות עליהם הוא שכב, ואף אם מרובים הם המצעות הללו זה על גבי זה. ודינו של ה\u0003משכב\u0004 ה\u0003תחתון\u0004 ששוכב עליו הבועל הריהו \u0003כ\u0004דינו של הבגד ה\u0003עליון\u0004 שעל גבי הזב, שזה וזה נחשבים כראשון לטומאה, ומטמאים אוכלים ומשקים, אך לא אדם וכלים.","\u0003ו\u0004עוד בדין בן תשע שנים ויום אחד, שאם הוא מפסולי כהונה (כגון גוי או חלל), ובא על בת כהן — הרי הוא \u0003פוסל\u0004 אותה בכך מלאכול עוד בתרומה. \u0003ו\u0004אם הוא כהן שנשא ישראלית — \u0003אינו מאכיל\u0004 (מתיר לה בכך לאכול) \u0003בתרומה.\u0004 \u0003ו\u0004אם בא בן התשע שנים ויום אחד על הבהמה — הריהו \u0003פוסל\u0004 בכך את הבהמה מלהיקרב \u0003על גבי המזבח\u0004 ככל הבהמה הנרבעת על ידי אדם. \u0003ו\u0004הבהמה עצמה \u0003נסקלת על ידו\u0004 (בגללו). \u0003ואם בא\u0004 בן התשע שנים ויום אחד \u0003על אחת מכל העריות האמורות בתורה\u0004 כגון אחותו או אמו הגדולות, שבנות עונשים הן — הן עצמן \u0003מומתין\u0004 (חייבים מיתת בית דין) \u0003על ידו,\u0004 שכן נחשבת ביאתו ביאה, \u0003ו\u0004אילו \u0003הוא פטור,\u0004 שכן אינו בן עונשים.","שנינו במשנתנו שבן תשע שנים ויום אחד שבא על יבמתו קנאה בכך, \u0003ו\u0004אולם הריהו נותן לה גט להתירה לאחרים, רק \u0003לכשיגדיל.\u0004 ושואלים על כך: וכי \u0003בגט סגי\u0004 \u0005[די]\u0006 \u0003לה\u0004 להינשא לכל אדם, \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003עשו\u0004 (קבעו חכמים) כי \u0003ביאת בן תשע\u0004 שנים ויום אחד ביבמתו, תיחשב \u0003כמאמר\u0004 (מעשה קידושין, מתקנת חכמים) \u0003ב\u0004יבם ה\u0003גדול,\u0004 שתיקנו לו חכמים שאם קידש את יבימתו ולא בא עליה, שאף שקונה אותה, אין זה קנין גמור מן התורה שתיחשב כאשתו לכל דבר.","ומעתה, \u0003מה\u0004 (כשם) ש\u0003מאמר בגדול\u0004 על מנת להתירה להינשא לכל אדם \u0003צריך\u0004 היבם לתת לה \u0003גט ל\u0004התירה מ\u0003מאמרו וחליצה ל\u0004התירה מ\u0003זיקתו, אף ביאת בן תשע\u0004 שנים — \u0003צריך גט למאמרו וחליצה לזיקתו\u0004 (להפקיע את זיקת היבמה)!","\u0003אמר רב\u0004 בתשובה לכך: \u0003הכי קאמר\u0004 \u0005[כך הוא אומר],\u0006 זו כוונת התנא במשנתנו,"],["\u0003לכשיגדיל יבעול\u0004 ויקנה אותה בכך \u0003ו\u0004אז \u0003יתן גט.\u0004","הילדה מזמן שהיא \u0003בת אחת עשרה שנה ויום אחד\u0004 שנדרה — \u0003נדריה נבדקין\u0004 אם מודעת היא למשמעות נדרה, לשם מי נדרה. ואם נמצא בבדיקה זו שהיא יודעת — נדרה נדר. ומשהיא \u0003בת שתים עשרה שנה ויום אחד\u0004 והביאה שתי שערות (סימן המורה על גדלותה) — אין צורך לבודקה אם יודעת היא לשם מי נדרה, שהרי היא גדולה, ו\u0003נדריה קיימין\u0004 (תקפים). \u0003ו\u0004הלכה זו ש\u0003בודקין\u0004 בת אחת עשרה שנה אמורה ב\u0003כל\u0004 שנת ה\u0003שתים עשרה,\u0004 עד להיותה בת שתים עשרה שנים ויום אחד.","ובדומה לכך, הילד מזמן שהוא \u0003בן שתים עשרה שנה ויום אחד\u0004 — \u0003נדריו נבדקין\u0004 אם הוא מודע למשמעות נדרו. ואם נמצא שהוא אכן יודע — נדרו נדר. ומשהוא \u0003בן שלש עשרה שנה ויום אחד\u0004 שהביא שתי שערות — אין צורך לבודקו שהרי הוא גדול, ו\u0003נדריו קיימין.\u0004 \u0003ו\u0004הלכה זו ש\u0003בודקין\u0004 בן שתים עשרה שנה אמורה ב\u0003כל\u0004 שנת ה\u0003שלש עשרה,\u0004 עד להיותו בן שלוש עשרה שנים ויום אחד.","ומוסיפים: \u0003קודם לזמן הזה\u0004 (שנת השתים עשרה בילדה והשלוש עשרה בילד), \u0003אף על פי שאמרו\u0004 הילדה או הילד \u0003\"יודעין אנו לשם מי נדרנו\",\u0004 או \"יודעים אנו \u0003לשם מי הקדשנו\"\u0004 — \u0003אין נדריהם נדר, ואין הקדשן הקדש,\u0004 כיון שקטנים הם, ואין תוקף לנדרם והקדשם, ואף שהבדיקה מוכיחה שיודעים הם לשם מי נדרו והקדישו ואין בכך כלום. וכמו כן \u0003לאחר הזמן הזה\u0004 (משנהיתה הילדה בת שתים עשרה שנה ויום אחד, והילד בן שלוש עשרה שנה ויום אחד), \u0003אף על פי שאמרו\u0004 הילדה או הילד: \u0003\"אין אנו יודעין לשם מי נדרנו\",\u0004 או שאמרו: \"אין אנו יודעים \u0003לשם מי הקדשנו\"\u0004 — \u0003נדרן נדר והקדשן הקדש,\u0004 כיון שגדולים הם.","שנינו במשנה שבשנת השתים עשרה של הבת נבדקים נדריה; שבמלאת לה שתים עשרה שנים ויום אחד נדריה תקפים; ושנבדקים נדריה כל שנת השלוש עשרה. ושואלים: \u0003וכיון דתנא\u0004 \u0005[ששנה]\u0006 כבר ש\u0003בת אחת עשרה שנה ויום אחד\u0004 \u0003נדריה נבדקין,\u0004 מעתה ההלכה ש\u0003בת שתים עשרה שנה ויום אחד נדריה קיימין למה לי\u0004 לשנותה, שהרי גדולה היא? ומשיבים: ראוי לשנותה, כי אם לא היתה שנויה במפורש \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]\u0006 כי \u0003בודקין לעולם\u0004 ואף את הגדולה — לכן \u0003קא משמע לן\u0004 \u0005[הוא\u0006 התנא \u0005משמיע לנו\u0006 במפורש\u0005]\u0006 שנדרי הגדולה תקפים אף בלא בדיקה.","ושואלים עוד: \u0003וכיון דתני\u0004 \u0005[ששנה]\u0006 ההלכה ש\u0003בת שתים עשרה שנה ויום אחד\u0004 \u0003נדריה קיימין,\u0004 מעתה ההלכה ש\u0003בודקין כל שתים עשרה למה לי\u0004 לשנותה? ומשיבים: ראוי לשנותה, משום שאם לא היתה שנויה במפורש \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]:\u0006 \u0003הואיל ואמר מר\u0004 \u0005[החכם]\u0006 כי \u0003שלשים יום בשנה חשובים שנה,\u0004 לכן \u0003היכא דבדקנא\u0004 \u0005[היכן,\u0006 בכל מקרה \u0005שבדקנו]\u0006 אותה ב\u0003שלשים\u0004 הימים שלאחר היותה בת אחת עשרה שנה, \u0003ו\u0004נמצא בבדיקה שהיא \u0003לא ידעה להפלות\u0004 (לעמוד על משמעות דבריה) — \u0003אימא\u0004 \u0005[אומר]:\u0006 \u0003תו\u0004 \u0005[שוב]\u0006 \u0003לא ליבדוק\u0004 \u0005[תיבדק]\u0006 במהלך השנה, עד להיותה בת שתים עשרה, שאז נדריה תקפים. לכן \u0003קא משמע לן\u0004 \u0005[הוא\u0006 התנא \u0005משמיע לנו]\u0006 שנבדקת במשך כל שנת השתים עשרה.","ושואלים עוד: \u0003ולתני הני תרתי בבי\u0004 \u0005[ושישנה\u0006 התנא במשנתנו את \u0005שני החלקים,\u0006 ההלכות \u0005הללו]:\u0006 \u0003בת שתים עשרה שנה ויום אחד\u0004 — \u0003נדריה קיימין, ובודקין כל שתים עשרה.\u0004 ומעתה את ההלכה ש\u0003בת אחת עשרה ויום אחד נדריה נבדקין למה לי\u0004 לשנותה?","ומשיבים: \u0003איצטריך\u0004 \u0005[נצרך]\u0006 לשנותה. במפורש, משום שאם לא היתה שנויה במפורש \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]:\u0006 \u0003סתמא\u0004 \u0005[בסתם,\u0006 במקרה רגיל\u0005]\u0006 אכן רק \u0003ב\u0004שנת ה\u0003שתים עשרה בעיא\u0004 \u0005[צריכה]\u0006 הילדה \u0003בדיקה,\u0004 ואילו \u0003ב\u0004שנת ה\u0003אחת עשרה\u0004 היא \u0003לא בעיא\u0004 \u0005[צריכה]\u0006 \u0003בדיקה.\u0004 \u0003ו\u0004אולם \u0003היכא דחזינן לה דחריפא טפי\u0004 \u0005[היכן,\u0006 במקרה \u0005שאנו רואים בה ש\u0006היא \u0005חריפה,\u0006 פקחית \u0005ביותר]\u0006 — \u0003מיבדקה\u0004 \u0005[תיבדק]\u0006 כבר \u0003ב\u0004שנת ה\u0003אחת עשרה,\u0004 לכן \u0003קא משמע לן הוא\u0004 התנא משמיע לנו במפורש\u0005]\u0006 שאינה נבדקת, כיון שקטנה היא.","ושואלים עוד: מה ששנינו במשנתנו כי \u0003קודם הזמן הזה\u0004 (שנת השתים עשרה בבת, ושנת השלוש עשרה בבן) אין תוקף לנדרם אף אם אמרו שיודעים למי נדרו \u0003ו\u0004כן \u0003אחר הזמן הזה\u0004 נדרם נדר אף אם אמרו שאינם יודעים למי נדרו, \u0003למה לי\u0004 לשנות הלכה זו, שהרי כבר למדנו מהו הגיל בבת ובבן שנדרם נדר? ומשיבים: נצרכו הדברים להישנות במפורש, משום שאם לא היו נשנים \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא \u0003היכא\u0004 \u0005[היכן,\u0006 במקרה\u0005]\u0006 \u0003דלא קאמרי אינהו\u0004 \u0005[שאין הם אומרים]\u0006 \"יודעים אנו לשם מי נדרנו\" (בגיל הקודם לזמן תקיפות נדרם) או \"אין אנו יודעים לשם מי נדרנו\" (בגיל המאוחר לזמן תקיפות נדרם), \u0003אבל היכא דקאמרי אינהו\u0004 \u0005[היכן,\u0006 במקרה \u0005שהם אומרים]\u0006 — \u0003נסמוך עלייהו\u0004 \u0005[עליהם],\u0006 לכן \u0003קא משמע לן\u0004 \u0005[הוא\u0006 התנא במשנתנו \u0005משמיע לנו\u0006 במפורש\u0005],\u0006 שכל מקרה לפני הזמן הזה — אין נדרם נדר, ולאחר הזמן הזה — נדרם נדר.","ממשנתנו עולה כי התפתחותה של הילדה מהירה מהתפתחותו של הילד, ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 דברים \u0003אלו\u0004 האמורים במשנתנו בזמני הנדרים של הילדה והילד הם כ\u0003דברי רבי,\u0004 ואילו \u0003ר' שמעון בן אלעזר אומר\u0004 להיפך, וכי ה\u0003דברים האמורים\u0004 במשנתנו \u0003בתינוקת\u0004 — \u0003בתינוק\u0004 הם \u0003אמורים,\u0004 ואילו ה\u0003דברים האמורים בתנוק\u0004 — \u0003בתנוקת\u0004 הם \u0003אמורים.\u0004 שלדעתו, התפתחותו של הילד מהירה מהתפתחותה של הילדה.","\u0003אמר רב חסדא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 לשיטתו של \u0003רבי\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בבריאת האשה \u0003\"ויבן ה' [ אלהים] את הצלע\u0004 אשר לקח מן האדם לאשה\" (בראשית ב, כב). ולשון זה, \"ויבן\", \u0003מלמד שנתן הקדוש ברוך הוא בינה\u0004 (\"ויבן\") \u0003יתירה באשה יותר מבאיש\u0004 (\"מן האדם לאשה\").","ושואלים: \u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' שמעון בן אלעזר\u0005]\u0006 מה דורש הוא מכתוב זה? — הכתוב \u0003ההוא מבעי ליה\u0004 \u0005[נצרך לו]\u0006 \u0003לכ\u0004 דרך שדרש \u0003ריש לקיש\u0004 כתוב זה. שכך \u0003אמר ריש לקיש משום\u0004 \u0005[בשם]\u0006 \u0003ר' שמעון בן מנסיא: \"ויבן ה' [ אלהים] את הצלע אשר לקח מן האדם לאשה ויבאה אל האדם\"\u0004 — \u0003מלמד שקלעה\u0004 (קלע את השער) \u0003הקדוש ברוך הוא לחוה והביאה אצל אדם הראשון, שכן בכרכי הים קורין לקלעיתא\u0004 — \u0003בנייתא\u0004 \u0005[לקליעה\u0006 — \u0005בנייה\u0006\u0005].\u0006","ומבררים לצד השני, \u0003ור' שמעון בן אלעזר מאי טעמא\u0004 \u0005[מה הטעם]\u0006 לשיטתו, שהתפתחותו של הילד מהירה משל הילדה? \u0003אמר רב שמואל בר רב יצחק: מתוך שהתינוק מצוי בבית רבו, נכנסת בו ערמומית תחלה\u0004 קודם הילדה, שאינה מצויה בבית רב.","שנינו במשנתנו כי ישנם שלושה זמנים בהתפתחות הילדה והילד: זמן תקיפות נדרם, שהוא בשנת השתים עשרה לבת ושנת השלוש עשרה לבן, שייקרא להלן \"תוך הזמן\"; הזמן שלפני כן, שאין בו כלל תוקף לנדר, שייקרא להלן \"לפני הזמן\"; הזמן בו הנדר תקף בכל מקרה, שייקרא להלן \"לאחר זמן\". ואולם לא למדנו מהו זמן גדלותם של הנער והנערה, לענין הבאת שתי שערות. \u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 לחכמים\u0005]:\u0006 אם הביאו הילדה או הילד שערות ב\u0003\"תוך\u0004 \u0003הזמן\",\u0004 האם נחשב הדבר \u0003כ\u0004הבאת הסימנים \u0003לפני\u0004 ה\u0003זמן\u0004 ואין אלה נחשבים סימני בגרות, \u0003או\u0004 נחשב \u0003כ\u0004הבאה \u0003לאחר זמן,\u0004 והרי אלו סימני בגרות?","ומבררים: \u0003למאי הלכתא\u0004 \u0005[למה,\u0006 לאיזה \u0005הלכה]\u0006 חשוב פתרונה של בעיה זו? \u0003אי\u0004 \u0005[אם]\u0006 \u0003ל\u0004ענין \u0003נדרים\u0004 — \u0003לאו\u0004 \u0005[לא]\u0006 \u0003כלפני זמן דמיא\u0004 \u0005[נחשב]\u0006 הבאת הסימנים, \u0003ולאו\u0004 \u0005[ולא]\u0006 \u0003כלאחר זמן דמיא\u0004 \u0005[נחשב].\u0006 הבאת הסימנים, שהרי הדבר נקבע לפי תקיפות הנדר, בבדיקה אם הם מודעים למי שנדרו.","\u0003אלא, ל\u0004ענין \u0003עונשין\u0004 שייענשו כגדול על שעברו מצוות התורה, \u0003מאי\u0004 \u0005[מה]\u0006 הדין? ונחלקו בדבר חכמים, \u0003רב ור' חנינא דאמרי תרווייהו\u0004 \u0005[שאמרו שניהם]:\u0006 הבאת שערות ב\u0003תוך\u0004 ה\u0003זמן\u0004 — נחשבת \u0003כ\u0004הבאה \u0003לפני\u0004 ה\u0003זמן,\u0004 ואין הילדה או הילד נחשבים בכך לגדולים להיענש על מעשיהם. ואילו \u0003ר' יוחנן ור' יהושע בן לוי דאמרי תרווייהו\u0004 \u0005[שאמרו שניהם]:\u0006 הבאת סימני שערות ב\u0003תוך\u0004 ה\u0003זמן\u0004 נחשבת \u0003כ\u0004הבאה \u0003לאחר\u0004 ה\u0003זמן,\u0004 ונענשים הם.","\u0003אמר רב נחמן בר יצחק, וסימניך\u0004 לזכור את השמועה בשם אומרה המדויק: הכתוב \u0003\"וזאת לפנים בישראל\"\u0004 (רות ד, ז), להזכירנו כי החכם ששמו הוא כצורת נקבה (\"וזאת\"), ר' חנינא, סבר שהבאה בתוך הזמן נחשבת כהבאת לפני הזמן (\"לפנים\").","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב המנונא\u0004 על שיטת ר' יוחנן ור' יהושע בן לוי ממה ששנינו במשנתנו: \u0003אחר\u0004 הזמן \u0003הזה, אף על פי שאמרו \"אין אנו יודעים לשם מי נדרנו\",\u0004 או שאמרו \"אין אנו יודעים \u0003לשם מי הקדשנו\"\u0004 — \u0003נדריהם נדר והקדשן הקדש.\u0004 ומכאן נדייק: \u0003הא\u0004 \u0005[הרי]\u0006 אם היה זה ב\u0003תוך זמן\u0004 — \u0003כלפני זמן\u0004 נחשב לכל ענין, אף אם הביאו שערות.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא\u0004 לרב המנונא, בדחיית ראייתו זו: לדבריך, ושמא \u0003אימא רישא\u0004 \u0005[אמור\u0006 את \u0005תחילת\u0006 המשנה\u0005]:\u0006 \u0003קודם הזמן הזה, אף על פי שאמרו \"יודעים אנו לשם מי נדרנו\",\u0004 או שאמרו \"יודעים אנו \u0003לשם מי הקדשנו\"\u0004 — \u0003אין נדריהם נדר, ואין הקדשן הקדש.\u0004 ומכאן נדייק: \u0003הא\u0004 \u0005[הרי]\u0006 אם היה זה ב\u0003תוך זמן\u0004 — \u0003כלאחר זמן\u0004 נחשב הדבר לכל דבר! אלא אין להביא ראיה ממשנה זו.","ומציינים: \u0003ולא\u0004 כך \u0003היא,\u0004 אין זו דחייה של ממש, משום ש\u0003רבא קטעי\u0004 \u0005[טעה],\u0006 שכן \u0003הוא\u0004 רבא, \u0003סבר\u0004 כי \u0003רב המנונא ממשנה יתירה קדייק\u0004 \u0005[הוא מדייק],\u0006 \u0003ו\u0004על כך השיגו כי \u0003אדדייק מסיפא\u0004 \u0005[\u0006במקום \u0005שידייק מסוף\u0006 המשנה\u0005]\u0006 — \u0003לידוק מרישא\u0004 \u0005[שידייק מתחילת\u0006 המשנה\u0005].\u0006","\u0003ו\u0004אולם \u0003לא\u0004 כך \u0003היא.\u0004 שכן \u0003רב המנונא מגופא דמתניתין קא דייק\u0004 \u0005[מגוף המשנה הוא דייק]:,\u0006 ובאופן זה: \u0003הא\u0004 \u0005[זה]\u0006 ששנינו בה \u0003\"לאחר זמן\" היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 בזמן \u0003דלא אייתי\u0004 \u0005[ש\u0006עדיין לא הביא] \u0003שתי שערות\u0004 — הרי \u0003קטן הוא, אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 מדובר באופן \u0003דאייתי\u0004 \u0005[שהביא]\u0006 \u0003שתי שערות,\u0004"],["\u0003וטעמא\u0004 \u0005[והטעם]\u0006 שנחשבת הבאת שתי השערות להגדירו כגדול, הוא משום \u0003לאחר זמן הוא דגמרא לה למילתיה\u0004 \u0005[נגמר לו הדבר,\u0006 סימן הגדלות, השערות\u0005],\u0006 ומכאן הסיק רב המנונא: \u0003הא\u0004 \u0005[הרי]\u0006 שאם הביאו הילדה או הילד שתי שערות ב\u0003תוך\u0004 ה\u0003זמן\u0004 — הרי זה נחשב \u0003כלפני זמן\u0004 ואין הם נחשבים גדולים.","\u0003ועוד מתיב\u0004 \u0005[מקשה]\u0006 \u0003ר' זירא\u0004 על שיטת הסבורים שהבאת סימני גדלות בתוך הזמן נחשבת כהבאתם לאחר הזמן, ממה ששנינו בברייתא על האמור בפרשת נדרים \"דבר אל בני ישראל ואמרת אליהם \u0003איש\u0004 או אשה \u0003כי יפלא לנדר נדר\"\u0004 (במדבר ו, ב), \u0003מה תלמוד לומר\u0004 (מלמדנו) הכתוב \u0003\"איש\",\u0004 והרי כבר נאמר בכתוב \"בני ישראל\" — \u0003לרבות\u0004 כל מי שהוא \u0003בן שלש עשרה שנה ויום אחד, שאף על פי שאינו יודע להפליא\u0004 (להגדיר משמעות דבריו), \u0003נדריו קיימין.\u0004","ויש לברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]\u0006 באיזה ילד בן שלוש עשרה נאמרה הדרשה? \u0003אי\u0004 \u0005[אם]\u0006 שעדיין \u0003לא אייתי\u0004 \u0005[הביא]\u0006 \u0003שתי שערות\u0004 — \u0003קטן הוא\u0004 נחשב. \u0003אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 מדובר במקרה \u0003דאייתי\u0004 \u0005[שהביא]\u0006 כבר \u0003שתי שערות, וטעמא\u0004 \u0005[וטעם]\u0006 הדבר, שדווקא מי שהוא \u0003בן שלש עשרה ויום אחד הוא דהוה ליה\u0004 \u0005[שהינו]\u0006 בכלל \u0003\"איש\", הא\u0004 \u0005[הרי]\u0006 שהבאת שתי שערות ב\u0003תוך\u0004 ה\u0003זמן\u0004 נחשבת \u0003כ\u0004הבאה \u0003לפני\u0004 ה\u0003זמן!\u0004 ומסכמים: אכן \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 היא על שיטת ר' יוחנן ור' יהושע בן לוי.","\u0003אמר רב נחמן:\u0004 אין להקשות מברייתא זו על שיטת ר' יוחנן ור' יהושע בן לוי, שכן \u0003כתנאי\u0004 \u0005[כ\u0006מחלוקת \u0005תנאים]\u0006 שנוי דין זה ששנינו בברייתא, \u0003בן תשע שנים שהביא שתי שערות\u0004 — הרי זו נחשבת כ\u0003שומא\u0004 סתם לכל הדעות, ואין משמעות הלכתית להבאת שערות אלה. \u0003מבן תשע ועד שתים עשרה שנה ויום אחד\u0004 שהביא שתי שערות — הרי זו \u0003שומא.\u0004 \u0003ר'\u0004 \u0003יוסי בר' יהודה אומר:\u0004 הרי זה \u0003סימן\u0004 גדלות. \u0003בן שלש עשרה שנה ויום אחד\u0004 שהביא שתי שערות — \u0003דברי הכל\u0004 הרי זה \u0003סימן\u0004 גדלות.","ויש לשאול: \u0003הא גופא קשיא\u0004 \u0005[זו עצמה קשה],\u0006 שכן בתחילה \u0003אמרת\u0004 כי \u0003מבן תשע ועד שתים עשרה שנה ויום אחד\u0004 שהביא שתי שערות — הרי זו נחשבת כ\u0003שומא,\u0004 ולא סימן גדלות. ומכאן ניתן לדייק: \u0003הא\u0004 \u0005[הרי]\u0006 אם הביא בתוך \u0003שלש עשרה שנה גופא\u0004 \u0005[עצמה]\u0006 — הרי זה \u0003סימן\u0004 גדלות. \u0003והדר תני\u0004 \u0005[וחזר ושנה]\u0006 בברייתא כי \u0003בן שלש עשרה שנה ויום אחד\u0004 שהביא שתי שערות — הרי זה \u0003סימן\u0004 גדלות. ומכאן ניתן לדייק: \u0003הא\u0004 \u0005[הרי]\u0006 אם הביא שתי שערות בתוך \u0003שלש עשרה שנה גופא\u0004 \u0005[עצמה]\u0006 — הרי זו \u0003שומא,\u0004 והרי זו סתירה בין שני חלקי הברייתא!","\u0003מאי לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 יש לומר כי מחלוקת \u0003תנאי\u0004 \u0005[תנאים]\u0006 \u0003היא, דמר סבר\u0004 \u0005[שחכם זה\u0006 שבתחילת הברייתא \u0005סבור]\u0006 כי הבאה ב\u0003תוך\u0004 ה\u0003זמן\u0004 נחשבת \u0003כ\u0004הבאה \u0003לאחר\u0004 ה\u0003זמן, ומר סבר\u0004 \u0005[וחכם זה\u0006 שבסוף הברייתא \u0005סבור]\u0006 כי הבאה ב\u0003תוך\u0004 ה\u0003זמן\u0004 נחשבת \u0003כ\u0004הבאה \u0003לפני\u0004 ה\u0003זמן.\u0004 ושיטת ר' יוחנן ור' יהושע בן לוי היא כצד אחד במחלוקת זו של התנאים.","ודוחים: \u0003לא,\u0004 אין להסיק מכאן שמחלוקת תנאים היא, שכן אפשר לומר בהסבר הברייתא כי \u0003דכולי עלמא\u0004 \u0005[שהכל]\u0006 סבורים כי הבאה ב\u0003תוך\u0004 ה\u0003זמן\u0004 נחשבת \u0003כ\u0004הבאה \u0003לפני\u0004 ה\u0003זמן, ואידי ואידי\u0004 \u0005[וזה וזה,\u0006 בתחילת הברייתא ובסופה\u0005]\u0006 מדובר \u0003בתינוקת\u0004 (ילדה), \u0003ו\u0004אולם \u0003רישא\u0004 \u0005[תחילת]\u0006 הברייתא היא כשיטת \u0003רבי\u0004 הסבור שגיל שלוש עשרה שנה אצל התינוקת נחשב כלאחר זמן, ולכן הבאת השערות בזמן זה הינה סימן גדלות. \u0003וסיפא\u0004 \u0005[וסוף\u0006 הברייתא\u0005]\u0006 היא כשיטת \u0003ר' שמעון בן אלעזר\u0004 הסבור שגיל שלוש עשרה בתינוקת נחשב כלפני הזמן.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר: \u0003הא והא\u0004 \u0005[וזה וזה,\u0006 בתחילת הברייתא ובסופה\u0005]\u0006 מדובר \u0003בתינוק\u0004 (ילד), \u0003ורישא\u0004 \u0005[ותחילת\u0006 הברייתא\u0005]\u0006 היא כשיטת \u0003ר' שמעון בן אלעזר, וסיפא\u0004 \u0005[וסוף\u0006 הברייתא\u0005]\u0006 היא כשיטת \u0003רבי.\u0004","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר: \u0003הא והא\u0004 \u0005[וזה וזה,\u0006 תחילת הברייתא וסופה\u0005]\u0006 כשיטת \u0003רבי,\u0004 שבגיל שלוש עשרה אצל התינוק נחשב כלאחר זמן, ואולם \u0003הא\u0004 \u0005[זה\u0006 בסוף הברייתא\u0005]\u0006 מדובר \u0003בתינוק,\u0004 ולכן אם הביא לפני שלוש עשרה, הרי זה נחשב כהבאה לפני הזמן. ואילו \u0003הא\u0004 \u0005[זה\u0006 תחילת הברייתא\u0005]\u0006 מדובר \u0003בתינוקת\u0004 שמגיל שתים עשרה נחשב אצלה לאחר זמן, ולכן אם הביאה בגיל זה, הרי זה נחשב לאחר זמן. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 הסבר אחר בברייתא, \u0003הא והא\u0004 \u0005[וזה וזה,\u0006 תחילת הברייתא וסופה\u0005]\u0006 כשיטת \u0003ר' שמעון בן אלעזר,\u0004 ואולם \u0003הא\u0004 \u0005[זה\u0006 תחילת הברייתא\u0005]\u0006 מדובר \u0003בתינוק, הא\u0004 \u0005[זה\u0006 סוף הברייתא\u0005]\u0006 מדובר \u0003בתינוקת.\u0004","שנינו עוד בברייתא כי \u0003ר' יוסי בר' יהודה אומר\u0004 בדינו של המביא שתי שערות מבן תשע שנים ועד שתים עשרה שנים ויום אחד שהוא \u0003סימן\u0004 בגרות. ובהסבר שיטה זו, \u0003אמר ר'\u0004 \u0003כרוספדאי בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' שבתאי: והוא\u0004 (ובלבד) \u0003שעודן בו\u0004 כשבא לכלל גיל גדלות. אבל אם נשרו השערות עד אז — התברר שהיו אלה רק שומא.","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך,\u0006 כהסברו של ר' כרוספדאי\u0005]:\u0006 \u0003בן תשע שנים ויום אחד שהביא שתי שערות\u0004 — הרי זו \u0003שומא,\u0004 ואין זה סימן בגרות. \u0003מבן תשע ועד שתים עשרה שנה ויום אחד\u0004 שהביא שתי שערות, \u0003ועודן בו\u0004 כשהגיע לכלל גיל בגרות — הרי זו \u0003שומא.\u0004 \u0003ר'\u0004 \u0003יוסי בר' יהודה אומר:\u0004 הרי זה \u0003סימן\u0004 בגרות.","ולסיכומה להלכה של הדברים שלמעלה, \u0003אמר רבא: הילכתא\u0004 \u0005[הלכה]\u0006 היא כי הבאת שתי שערות ב\u0003תוך\u0004 ה\u0003זמן\u0004 נחשבת \u0003כ\u0004הבאה ש\u0003לפני\u0004 ה\u0003זמן,\u0004 ואין נעשים בכך גדול. \u0003רב שמואל בר זוטרא\u0004 \u0003מתני לה לשמעתא\u0004 \u0005[היה שונה את ההלכה\u0006 הזו\u0005]\u0006 של \u0003רבא בהאי לישנא\u0004 \u0005[בלשון זו],\u0006 \u0003אמר רבא: קטנה\u0004 יתומה מאביה, שהשיאוה אמה ואחיה (שתיקנו חכמים שיכולים הם להשיאה), ב\u0003כל\u0004 שנת ה\u0003שתים עשרה שנה\u0004 לחייה — מתקנת חכמים שיכולה היא להיות \u0003ממאנת\u0004 (מסרבת לנישואיה אלה, ובכך להפקיע אותם) \u0003והולכת\u0004 (נמשכת) זכותה זו לאורך כל השנה. ואפילו אם הביאה בתוך שנה זו שתי שערות, והריהי גדולה. ואולם \u0003מכאן\u0004 מגיל שתים עשרה שנים ויום אחד \u0003ואילך\u0004 (והלאה) שהיא כבר גדולה — שוב \u0003אינה ממאנת,\u0004 שזו אינה בכלל תקנת חכמים זו, \u0003ו\u0004כמו כן \u0003אינה חולצת\u0004 לאחי בעלה שמת בלא בנים.","ודנים בדבר, \u0003הא גופא קשיא\u0004 \u0005[זו עצמה קשה],\u0006 שכן בתחילה \u0003אמרת\u0004 שמגיל שתים עשרה שנים ויום אחד שוב \u0003אינה ממאנת, אלמא\u0004 \u0005[מכאן נסיק]\u0006 ש\u0003גדולה היא,\u0004 ואולם \u0003אי\u0004 \u0005[אם]\u0006 \u0003גדולה היא\u0004 ש\u0003תחלוץ,\u0004 ומדוע אמר שאינה חולצת?","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 כי \u0003מספקא ליה\u0004 \u0005[מסופק לו,\u0006 לרבא\u0005],\u0006 אם הביאה שתי שערות (והריהי גדולה), או שלא הביאה שתי שערות (והריהי עדיין קטנה), ומשום כך החמיר: שאינה ממאנת (כגדולה), ואינה חולצת (כקטנה). \u0003ו\u0004אולם יש לשאול: \u0003מי מספקא ליה\u0004 \u0005[האם מסופק לו\u0006 לרבא בדבר זה\u0005]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא: קטנה שהגיעה לכלל שנותיה\u0004 של בגרות, שהיא בת שתים עשרה שנים ויום אחד — \u0003אינה צריכה בדיקה\u0004 אם הביאה שתי שערות, כדי להחשיבה גדולה, ש\u0003חזקה\u0004 ש\u0003הביאה סימנין!\u0004","ומשיבים: \u0003הני מילי\u0004 \u0005[דברים אלה],\u0006 שרבא מעמיד את בת שתים עשרה שנים ויום אחד בחזקת שהביאה סימנים, אמורים דווקא \u0003בסתמא\u0004 \u0005[בסתם],\u0006 \u0003אבל הכא\u0004 \u0005[כאן]\u0006 מדובר כשכבר \u0003בדקו\u0004 אותה \u0003ולא אשכחו\u0004 \u0005[מצאו]\u0006 בה סימנים, ובכגון זה \u0003לא\u0004 אמר רבא שיש להעמידה על חזקתה זו, וספק הוא, ונוהגים בה להחמיר.","ושואלים על כך: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 מדובר, שבדקוה ולא נמצאו בה סימנים יהא דינה ככל קטנה, ו\u0003תמאן!\u0004 ומשיבים: אף שאין מעמידים אותה בחזקת שהביאה סימנים, ואולם \u0003חוששין שמא\u0004 היו בה סימנים ו\u0003נשרו.\u0004","ושואלים על כך: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח למי שאומר]\u0006 כי \u0003חוששין\u0004 לנשירה, \u0003אלא למאן דאמר\u0004 \u0005[למי שאומר]\u0006 כי \u0003אין חוששין\u0004 לנשירה, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר],\u0006 \u0003דאיתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו חכמים בדבר זה, \u0003רב פפא אמר: אין חוששין שמא נשרו, רב פפי אמר: חוששין.\u0004 ומשיבים: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שנחלקו אם חוששים לנשירת סימנים, אמורים דווקא \u0003לענין חליצה, אבל לענין מיאון\u0004 — לדעת הכל \u0003חוששין\u0004 לנשירה, ולכן מגיל שתים עשרה שנים ויום אחד שוב אינה ממאנת.","ושואלים: \u0003מכלל\u0004 דבריך עולה כי לשיטת \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 ש\u0003חוששין\u0004 לנשירת סימנים, הריהי \u0003חולצת\u0004 כגדולה, \u0003והא\u0004 \u0005[והרי]\u0006 \u0003חוששין בעלמא קאמר\u0004 \u0005[סתם הוא אומר]!\u0006","\u0003אלא, לעולם\u0004 יש לומר בהסבר דברי רבא שהוא מדבר כאשר \u0003לא בדקה.\u0004 ואינה ממאנת, משום החזקה שכבר הביאה שתי שערות והריהי גדולה. \u0003ו\u0004אולם \u0003לענין חליצה חיישינן\u0004 \u0005[חוששים אנו]\u0006 שמא עדיין לא הביאה שערות, והריהי בכלל קטנה. \u0003וכי קאמר\u0004 \u0005[וכאשר אמר]\u0006 \u0003רבא חזקה\u0004 שהביאה סימנים — הרי זה דווקא \u0003ל\u0004ענין \u0003מיאון, אבל ל\u0004ענין \u0003חליצה\u0004 — \u0003בעיא\u0004 \u0005[צריכה]\u0006 \u0003בדיקה.\u0004","ובסיכום להלכה אם חוששים לנשירת הסימנים, \u0003אמר רב דימי מנהרדעא: הלכתא\u0004 \u0005[הלכה]\u0006 היא כי מי שהגיעה לגיל שתים עשרה שנים ויום אחד, ונבדקה ולא נמצאו בה סימנים, \u0003חוששין שמא\u0004 היו בה סימנים, ו\u0003נשרו.\u0004 ומשום כך, אם קידשוה אמה ואחיה בקטנותה אינה יכולה אז למאן.","\u0003ו\u0004אולם \u0003הני מילי היכא\u0004 \u0005[דברים אלה\u0006 אמורים דווקא \u0005היכן,\u0006 כאשר\u0005]\u0006 \u0003קדשה\u0004 בעלה \u0003בתוך\u0004 ה\u0003זמן\u0004 (לפני שהיתה בת שתים עשרה שנים ויום אחד), \u0003ובעל\u0004 אותה \u0003לאחר זמן\u0004 (כשהיא בת שתים עשרה שנים ויום אחד), \u0003דאיכא ספיקא דאורייתא\u0004 \u0005[שיש כאן\u0006 במקרה זה \u0005ספק מן התורה],\u0006 שמא הביאה שתי שערות, והריהי גדולה, וחלו נישואיה (בביאה) מן התורה. \u0003אבל\u0004 אם בעל אותה רק \u0003מעיקרא\u0004 \u0005[בתחילה,\u0006 בהיותה לפני שתים עשרה שנים ויום אחד\u0005]\u0006 — \u0003לא\u0004 חוששים שהביאה סימנים ונשרו, שהרי אלו רק נישואין מדברי חכמים.","ועוד בדינו של הקטן הנודר, \u0003אמר רב הונא:\u0004 קטן היודע לשם מי הוא מקדיש, והריהו בתוך הזמן (הקטנה — בשנת השתים עשרה, והקטן — בשנת השלוש עשרה), ו\u0003הקדיש\u0004 דבר מאכל, \u0003ו\u0004לאחר מכן \u0003אכל\u0004 אותו — הריהו \u0003לוקה\u0004 (נענש במלקות, ככל האוכל הקדש).","\u0003ש\u0004כן \u0003נאמר\u0004 בפרשת הנדרים \u0003\"איש,\u0004 או אשה \u0003כי יפלא לנדר\"\u0004 (במדבר ו, ב), ללמד כי בכלל הנדרים אף זה שסמוך להיותו גדול ויודע לשם מי נדר (\"מופלא הסמוך לאיש\"), \u0003ו\u0004כן נאמר \"\u0003לא יחל דברו\"\u0004 (שם ל, ג), ללמדנו: \u0003כל\u0004 מי \u0003שישנו ב\u0004כלל \u0003הפלאה\u0004 — \u0003ישנו ב\u0004כלל איסור \u0003\"בל יחל\"\u0004 (\"איש כי ידור נדר לה' או השבע שבועה לאסור אסר על נפשו לא יחל דברו ככל היוצא מפיו יעשה\". שם). \u0003וכל\u0004 מי \u0003שאינו ב\u0004כלל \u0003הפלאה\u0004 — אין נדרו נחשב, ומשום כך, \u0003אינו ב\u0004כלל \u0003\"בל יחל\".\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב הונא בר יהודה (לרבא)\u0004 מן הברייתא \u0003לסיועי\u0004 \u0005[לסייע]\u0006 \u0003לרב הונא\u0004"],["שכך שנינו בה: \u0003לפי שמצינו\u0004 (מצאנו) בפרשת נדרים \"איש כי יפליא לנדור\" (במדבר ו, ב) \u0003שהשוה הכתוב\u0004 דינו של \u0003הקטן\u0004 (המופלא הסמוך לאיש) \u0003כגדול, ל\u0004ענין \u0003זדון שבועה\u0004 (שעבר על שבועתו במזיד), \u0003ול\u0004ענין \u0003איסר\u0004 (דבר שאסר על עצמו, שייחשב איסור עליו), \u0003ול\u0004ענין איסור \u0003\"בל\u0004 (לא) \u0003יחל\u0004 דברו\" (שם ל, ב), \u0003יכול\u0004 מעתה \u0003יהא\u0004 קטן זה אף \u0003חייב על\u0004 המעילה ב\u0003הקדשו\u0004 (כגון זה שאכל את הקדשו) \u0003קרבן,\u0004 כגדול?","\u0003תלמוד לומר\u0004 בדין הנדרים \u0003\"זה הדבר\u0004 אשר צוה ה'. איש כי ידור נדר לה' או השבע שבועה\" (שם ל, ב—ג), ללמדנו שרק לענין זה דין המופלא הסמוך לאיש כדינו של האיש, ולא להתחייב קרבן על מעילתו.","ויש לדייק בדברים: \u0003קתני מיהת\u0004 \u0005[על כל פנים שנה]\u0006 בברייתא זו שהמופלא הסמוך לאיש הריהו כגדול \u0003ל\u0004ענין \u0003איסור ול\u0004ענין \u0003\"בל\u0004 (לא) \u0003יחל\u0004 דברו\", והריהו \u0003חייב\u0004 עליהם, והרי זה כשיטת רב הונא שלוקה על אכילת הקדשו. ודוחים: \u0003אימא\u0004 \u0005[אמור]\u0006 כך בדברי הברייתא הזו, ששווה הקטן לגדול \u0003לאיסור \"בל\u0004 (לא) \u0003יחל\u0004 דברו\" ולא לקרבן.","ותוהים על דחייה זו: וכי יש לשנות בברייתא \u0003איסור \"בל\u0004 (לא) \u0003יחל\",\u0004 והרי \u0003מה נפשך\u0004 \u0005[רצונך],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 דינו של ה\u0003מופלא\u0004 ה\u0003סמוך לאיש\u0004 הוא \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 — \u0003מילקא נמי לילקי\u0004 \u0005[ללקות גם ילקה].\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 דינו של ה\u0003מופלא\u0004 ה\u0003סמוך לאיש\u0004 הוא \u0003לאו דאורייתא\u0004 \u0005[לא מן התורה]\u0006 אלא מדברי חכמים — \u0003איסור נמי ליכא\u0004 \u0005[איסור גם כן אין]!\u0006 ומשיבים: כוונת הדברים שאין האיסור חל על הקטן עצמו, אלא \u0003לאותן המוזהרים עליו\u0004 (המופקדים עליו להפרישו מאכילת דברים אסורים).","ואומרים: \u0003שמע מינה\u0004 \u0005[ממנה,\u0006 מהלכה זו ששנינו] ראיה למחלוקת חכמים זו, ששנינו אם \u0003קטן אוכל\u0004 בשר \u0003נבלות\u0004 (דבר האסור באכילה) — \u0003בית דין מצווין עליו להפרישו.\u0004 \u0003ומכאן למדים שמצווים להפרישו מדבר האסור באכילה, כגון הקדשו.\u0004 \u0003ודוחים: אין להביא מכאן ראיה לשיטה זו, כי\u0004 \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים],\u0006 \u0003כגון שהקדיש הוא\u0004 המופלא הסמוך לאיש, \u0003ואכלו אחרים\u0004 את הקדשו, שהם לוקים על הקדשו זה, ואולם אם הוא אכל אינו לוקה.","ושואלים על כך: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח למי שאומר]\u0006 \u0003הקדיש הוא, ואכלו אחרים\u0004 — \u0003לוקין, אלא למאן דאמר\u0004 \u0005[למי שאומר]\u0006 \u0003אין לוקין, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 \u0003דאיתמר\u0004 \u0005[שכן נאמר],\u0006 שנחלקו חכמים בדינו של מי ש\u0003הקדיש הוא ואכלו אחרים.\u0004 \u0003רב כהנא אמר: אין לוקין, ר'\u0004 \u0003יוחנן וריש לקיש דאמרי תרוויהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003לוקין!\u0004","ומשיבים: לשיטת הסובר שאין האחרים לוקים על הקדשו של המופלא הסמוך לאיש, כוונתו שאין לוקים מן התורה, ואולם הריהם לוקים \u0003מדרבנן\u0004 \u0005[מ\u0006דברי \u0005חכמים],\u0006 \u0003וקרא\u0004 \u0005[והמקרא]\u0006 שהובא בברייתא (\"שהשווה הכתוב הקטן כגדול\") הריהו \u0003אסמכתא בעלמא\u0004 \u0005[סמך בלבד].\u0006","למעלה הובא שנחלקו חכמים בדין אחרים שאכלו מה שהקדיש המופלא הסמוך לאיש, ומעתה דנים בה ל\u0003גופא\u0004 \u0005[עצמה].\u0006 למדנו בדין המופלא הסמוך לאיש ש\u0003הקדיש ואכלו אחרים\u0004 את הקדשו, ש\u0003רב כהנא אמר: אין לוקין, ר'\u0004 \u0003יוחנן וריש לקיש דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003לוקין.\u0004 ומבררים: \u0003במאי קמיפלגי\u0004 \u0005[במה הם חולקים]?\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' יוחנן וריש לקיש, \u0005סבור]\u0006 כי דין ה\u0003מופלא\u0004 ה\u0003סמוך לאיש\u0004 הריהו \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 ולכן לוקים אחרים על הקדשו. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 רב כהנא \u0005סבור]\u0006 כי דין ה\u0003מופלא\u0004 ה\u0003סמוך לאיש\u0004 הריהו \u0003מדרבנן\u0004 \u0005[מ\u0006דברי \u0005חכמים],\u0006 ולכן אין אחרים לוקים על הקדשו.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב ירמיה:\u0004 הקטנה שהיא \u0003יתומה\u0004 מאביה, שהשיאוה אמה ואחיה לפי תקנת חכמים, \u0003שנדרה\u0004 — \u0003בעלה מפר לה,\u0004 כדינו של כל בעל, אף שאין הנישואין הללו אלא מתקנת חכמים. ומעתה יש לדון בדבר: \u0003אי אמרת בשלמא\u0004 \u0005[זה נוח,\u0006 מובן, \u0005אם אומר אתה]\u0006 שדין ה\u0003מופלא\u0004 ה\u0003סמוך לאיש\u0004 הריהו \u0003דרבנן\u0004 \u0005[\u0006מדברי \u0005חכמים],\u0006 אפשר איפוא לומר כי \u0003אתו\u0004 \u0005[באו]\u0006 \u0003נשואין\u0004 שתוקפם \u0003דרבנן\u0004 \u0005[\u0006מדברי \u0005חכמים]\u0006 \u0003ומבטלי נדרא\u0004 \u0005[ומבטלים נדר]\u0006 שתוקפו \u0003דרבנן\u0004 \u0005[\u0006מדברי \u0005חכמים].\u0006 \u0003אלא אי אמרת דאורייתא\u0004 \u0005[אם אומר אתה\u0006 שתוקף הנדר במופלא הסמוך לאיש \u0005מן התורה],\u0006 וכי \u0003אתו\u0004 \u0005[באו]\u0006 \u0003נשואין\u0004 שתוקפם \u0003דרבנן\u0004 \u0005[\u0006מדברי \u0005חכמים]\u0006 \u0003ומבטלי נדרא\u0004 \u0005[ומבטלים נדר]\u0006 שתוקפו \u0003דאורייתא\u0004 \u0005[מן התורה]?\u0006","\u0003אמר רב יהודה, אמר שמואל: בעלה מפר לה ממה נפשך\u0004 (מכל צד שתרצה), שכן \u0003אי\u0004 \u0005[אם]\u0006 תוקף הנדר של המופלא הסמוך לאיש הוא רק \u0003דרבנן\u0004 \u0005[\u0006מדברי \u0005חכמים]\u0006 — הרי גם תוקף נשואיה רק \u0003דרבנן\u0004 \u0005[\u0006מדברי \u0005חכמים]\u0006 \u0003הוא.\u0004 \u0003אי\u0004 \u0005[אם]\u0006 תוקף הנדר של המופלא הסמוך לאיש הוא \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 והריהו עובר על איסור תורה — הרי בכלל \u0003קטן אוכל נבלות הוא, ו\u0004בכגון זה \u0003אין בית דין מצווין עליו להפרישו.\u0004","ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 עדיין יכול להיות מכשול בהפרתו זו של הבעל, שכן \u0003כי גדלה\u0004 \u0005[כאשר תגדל]\u0006 אשתו זו שהיתה קטנה בזמן ההפרה ואין להפרה זו תוקף אלא מדברי חכמים, \u0003אכלה\u0004 \u0005[תאכל]\u0006 \u0003ב\u0004הסתמך על \u0003הפרה קמייתא\u0004 \u0005[קודמת]\u0006 זו, והרי אין הפרתו הפרה, ואז היא בגדר גדול האוכל נבילות שודאי מפרישים אותו!","ומשיבים: \u0003אמר רבה בר ליואי:\u0004 אין מקום לחשש זה, משום ש\u0003בעלה מפר לה כל שעה ושעה,\u0004 ונמצא שכאשר תגדל, יפר לה הפרה שתוקפה מן התורה. \u0003והוא\u0004 (ובלבד) \u0003שבעל\u0004 אותה בעלה כשהגיעה לגיל גדלות, ותוקפם של הנישואין יהיה מן התורה.","ושואלים על כך: \u0003והא\u0004 \u0005[והרי]\u0006 הלכה היא ש\u0003אין\u0004 ה\u0003בעל מפר\u0004 לאשתו \u0003ב\u0004נדרים ש\u0003קודמין\u0004 לנישואיהם, ומשבגרה והריהי נחשבת כנשואה מן התורה לכל דבר, נחשבים נישואיה בקטנותה ביחס להיום כלפני נישואין. ומשיבים: הסבר הדבר, \u0003כ\u0004שיטת \u0003רב פנחס\u0004 שאמר \u0003משמיה\u0004 \u0005[בשמו]\u0006 של \u0003רבא.\u0004 שכך \u0003אמר רב פנחס משמיה\u0004 \u0005[בשמו]\u0006 של \u0003רבא: כל\u0004 אשה \u0003הנודרת\u0004 נדר — \u0003על דעת בעלה היא נודרת,\u0004 אם יסכים לנדרה, ולכן יכול הוא להפר את נדרה. ואף הקטנה נדרה על דעת בעלה, ולכן יכול הוא להפר את נדרה אף לאחר שבגרה.","ועוד בענין תוקף נדרו של המופלא הסמוך לאיש \u0003אמר אביי: תא שמע\u0004 \u0005[בוא\u0006 ושמע] ראיה ממה ששנינו במשנה במסכת תרומות: \u0003קטן שלא הביא שתי שערות, ר'\u0004 \u0003יהודה אומר: אין תרומתו תרומה.\u0004 \u0003ר'\u0004 \u0003יוסי אומר: עד שלא בא לעונת נדרים\u0004 (שאין הוא עדיין בגדר מופלא הסמוך לאיש) — \u0003אין תרומתו תרומה,\u0004 ואולם \u0003משבא לעונת נדרים\u0004 — \u0003תרומתו תרומה.\u0004","\u0003סברוה\u0004 \u0005[הניחו\u0006 החכמים\u0005]\u0006 כי \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 \u0003ר' יוסי\u0004 בדין התרומה כי \u0003תרומה בזמן הזה\u0004 היא \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 ומעתה יש לדון בדבר: \u0003אי אמרת בשלמא\u0004 \u0005[זה טוב,\u0006 מובן דינו של ר' יוסי שמופלא הסמוך לאיש תורם, \u0005אם אומר אתה]\u0006 שדינו של ה\u0003מופלא\u0004 ה\u0003סמוך לאיש\u0004 הוא \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 לכן יש מקום לומר כי \u0003אתי גברא\u0004 \u0005[בא אדם]\u0006 שיש לו כח החלה לענין נדרים \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 כגון זה המופלא הסמוך לאיש, \u0003ומתקן\u0004 בתרומתו שתרם תבואה המוגדרת כ\u0003טבלא דאורייתא\u0004 \u0005[טבל,\u0006 שלא הופרשו ממנו תרומות ומעשרות, \u0005מן התורה].\u0006 \u0003אלא אי אמרת דרבנן\u0004 \u0005[אם אומר אתה\u0006 שדין מופלא הסמוך לאיש הוא רק מדברי \u0005חכמים],\u0006 וכי \u0003אתי גברא דרבנן\u0004 \u0005[בא אדם\u0006 שכוח החלתו בנדרים הוא רק מדברי \u0005חכמים]\u0006 \u0003ומתקן טבלא דאורייתא\u0004 \u0005[טבל מן התורה]?\u0006 ודוחים: \u0003לא,\u0004 אין להביא ראיה מכאן שדין מופלא הסמוך לאיש בנדרים הוא מן התורה, שאפשר לומר שהטעם שמופלא הסמוך לאיש יכול לתרום אף שהוא בנדרים רק מדברי חכמים, משום ש\u0003קסבר\u0004 \u0005[סבור]\u0006 \u0003ר' יוסי\u0004 בדין \u0003תרומה בזמן הזה\u0004 שהוא רק \u0003דרבנן\u0004 \u0005[\u0006מדברי \u0005חכמים].\u0006","ותוהים על כך: \u0003ו\u0004כי סבר \u0005[סבור]\u0006 \u0003ר' יוסי\u0004 שדין \u0003תרומה בזמן הזה\u0004 הוא רק \u0003דרבנן\u0004 \u0005[\u0006מדברי \u0005חכמים]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנויה]\u0006 ברייתא \u0003בסדר עולם\u0004 על האמור בביאת הארץ \"והביאך ה' אלהיך אל הארץ \u0003אשר ירשו אבותיך וירשתה\"\u0004 (דברים ל, ה), ולמדנו מהכתוב המציין שתי לשונות ירושה כי","\u0003ירושה ראשונה\u0004 (שנכבשה הארץ בימי יהושע) והתקדשה לחיוב מצוות, \u0003ו\u0004כן ירושה \u0003שניה\u0004 שבימי עזרא — \u0003יש להן\u0004 לבני ישראל, ואילו ירושה \u0003שלישית\u0004 — \u0003אין להן.\u0004 שכן קדושת הארץ מירושה שניה לא פקעה ממנה.","\u0003ואמר ר'\u0004 \u0003יוחנן: מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 ששנה את \u0003סדר עולם\u0004 — \u0003ר' יוסי,\u0004 הרי שר' יוסי סבור שבזמן הזה לא פקעה קדושת הארץ, וחיוב תרומה בה הריהו מן התורה!","ומשיבים: אכן \u0003ר' יוסי תני לה\u0004 \u0005[שנה אותה],\u0006 את סדר עולם, \u0003ו\u0004אולם הוא עצמו \u0003לא סבר לה\u0004 \u0005[אינו סבור כמותה].\u0006 ומוכיחים זאת, \u0003הכי נמי מסתברא\u0004 \u0005[כך גם מסתבר]\u0006 לומר, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003עיסה\u0004 (בצק) \u0003שנדמעה\u0004 (שהתערב בה מן התרומה), \u0003או שנתחמצה בשאור של תרומה\u0004"],["\u0003חייבת\u0004 העיסה הזו \u0003ב\u0004הפרשת \u0003חלה, ו\u0004אף שנפלה לתוכה תרומה, אין דינה כתרומה (שהרי כבר התבטלה התרומה בעיסה, ברוב), ולכן \u0003אינה נפסלת\u0004 (נטמאת) \u0003בטבול יום,\u0004 אלו דברי ר' \u0003מאיר ור' יהודה.\u0004 ואילו \u0003ר' יוסי ור' שמעון פוטרין מן החלה,\u0004 שכן אין התרומה חייבת בהפרשת חלה, ונפטרת העיסה משום תערובת התרומה בה.","\u0003סברוה\u0004 \u0005[חשבו,\u0006 הניחו חכמים\u0005]\u0006 כי \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שחיוב \u0003תרומה\u0004 בזמן הזה הוא \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 סבור שאף חיוב הפרשת \u0003חלה\u0004 בזמן הזה הוא \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 ואילו \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 כי חיוב \u0003תרומה\u0004 בזמן הזה הוא \u0003דרבנן\u0004 \u0005[\u0006מדברי \u0005חכמים],\u0006 אף חיוב \u0003חלה\u0004 בזמן הזה הוא \u0003דרבנן\u0004 \u0005[\u0006מדברי \u0005חכמים].\u0006 ומעתה \u0003אי אמרת בשלמא\u0004 \u0005[זה נוח אם אומר אתה]\u0006 ש\u0003קסבר\u0004 \u0005[סבור]\u0006 \u0003ר' יוסי\u0004 כי חיוב \u0003חלה בזמן הזה,\u0004 וכן חיוב תרומה, הוא \u0003דרבנן\u0004 \u0005[\u0006מדברי \u0005חכמים],\u0006 אפשר לומר כי \u0003אתי\u0004 \u0005[בא]\u0006 \u0003דמוע\u0004 שהוא \u0003דרבנן\u0004 \u0005[\u0006מדברי \u0005חכמים]\u0006 (שהרי מן התורה יש ביטול ברוב, ובטלה התרומה שבעיסה), \u0003ומפקע\u0004 \u0005[ומפקיע]\u0006 את חיוב הפרשת ה\u0003חלה\u0004 שאף הוא \u0003דרבנן\u0004 \u0005[\u0006מדברי \u0005חכמים].\u0006","\u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי חיוב הפרשת \u0003חלה\u0004 בזמן הזה הוא \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 יש לשאול: וכי \u0003אתי\u0004 \u0005[בא]\u0006 \u0003דמוע\u0004 שהוא \u0003דרבנן\u0004 \u0005[\u0006מדברי \u0005חכמים]\u0006 \u0003ומפקע\u0004 \u0005[ומפקיע]\u0006 חיוב הפרשת \u0003חלה דאורייתא\u0004 \u0005[מן התורה]?\u0006 הרי שסבור ר' יוסי כי חיוב חלה בזמן הזה הוא מדברי חכמים, ואף חיוב תרומה בזמן הזה הוא מדברי חכמים, והרי זה מורה שמה שר' יוסי שנה בסדר עולם שחיוב תרומה בזמן הזה הוא מן התורה, הוא עצמו אינו סבור כן.","ודוחים את הראיה: \u0003ודלמא קסבר\u0004 \u0005[ושמא סבור הוא]\u0006 \u0003ר' יוסי\u0004 כי חיוב \u0003תרומה בזמן הזה\u0004 הוא \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 \u0003ו\u0004אילו חיוב הפרשת \u0003חלה\u0004 בזמן הזה הוא רק \u0003דרבנן\u0004 \u0005[\u0006מדברי \u0005חכמים],\u0006 ומשום כך עיסה זו פטורה מן החלה, משום שהדימוע שמדברי חכמים פוטר את העיסה החייבת בחלה מדברי חכמים.","\u0003וכ\u0004דרך \u0003דאהדר\u0004 \u0005[שהשיב,\u0006 השיג\u0005]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע\u0004 על דברי חכמים. שכך \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: אשכחתינהו לרבנן דבי רב דיתבי וקאמרי\u0004 \u0005[מצאתים את החכמים של בית המדרש, שיושבים ואומרים]:\u0006 \u0003אפילו למאן דאמר\u0004 \u0005[למי שאומר]\u0006 כי חיוב הפרשת \u0003תרומה בזמן הזה\u0004 הוא \u0003דרבנן\u0004 \u0005[\u0006מדברי \u0005חכמים],\u0006 חיוב הפרשת \u0003חלה\u0004 בזמן הזה הוא \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006","\u0003שהרי\u0004 ב\u0003שבע\u0004 השנים \u0003שכבשו\u0004 בני ישראל את הארץ בימי יהושע, \u0003ו\u0004ב\u0003שבע\u0004 שאחריהן, \u0003ש\u0004בהן \u0003חלקו\u0004 את הארץ לנחלות השבטים, \u0003נתחייבו\u0004 בני ישראל \u0003בחלה, ו\u0004עדיין \u0003לא נתחייבו במעשר.\u0004 ואף בזמן הזה, שאין כל יושבי הארץ נמצאים בה ולכן אין חובת תרומות ומעשרות מן התורה אלא רק מדברי חכמים — חיוב הפרשת חלה הריהו מן התורה, שהרי באו אל הארץ.","\u0003ואמינא להו אנא\u0004 \u0005[ואמרתי להם אני]:\u0006 \u0003אפילו למאן דאמר\u0004 \u0005[למי שאומר]\u0006 כי חיוב הפרשת \u0003תרומה בזמן הזה\u0004 הוא \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 חיוב הפרשת \u0003חלה\u0004 הוא \u0003דרבנן\u0004 \u0005[\u0006מדברי \u0005חכמים],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 נאמר במצות הפרשת החלה \"בבואכם אל הארץ אשר אני מביא אתכם שמה... ראשית עריסותכם חלה תרימו תרומה..\" (במדבר טו, יח—כ). ומדייקים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003\"בבאכם\"\u0004 חל חיוב הפרשת חלה, אם כן \u0003יכול משנכנסו לה שנים ושלשה מרגלים\u0004 בלבד, כבר יתחייבו בהפרשת חלה? \u0003תלמוד לומר \"בבאכם\"\u0004 — דווקא \u0003בביאת כולכם אמרתי\u0004 שתתחייבו בחלה, \u0003ולא בביאת מקצתכם.\u0004","\u0003וכי אסקינהו\u0004 \u0005[וכאשר העלה אותם,\u0006 את העולים מבבל לארץ ישראל\u0005]\u0006 \u0003עזרא, לא כולהו סלוק\u0004 \u0005[כולם עלו],\u0006 ולא היתה זו איפוא \"ביאת כולכם\", אלא \"ביאת מקצתכם\", ולכן חייבים בחלה בזמן הזה רק מדברי חכמים.","\u0003משל\u0004 מפרי התאנה \u0003משלו חכמים ב\u0004תיאור שלושת זמני התפתחותה של ה\u0003אשה,\u0004 קטנות, נערות, ובגרות: \u0003פגה\u0004 (הפרי טרם בישולו), \u0003בוחל\u0004 (הפרי הקרוב לבישולו), \u0003וצמל\u0004 (הפרי הבשל במילואו). ומסבירים: זו המכונה \u0003פגה\u0004 — הרי היא \u0003עודה תנוקת\u0004 (שמתחת לגיל שתים עשרה שנה, שעדיין לא הביאה כל סימני בגרות), זו המכונה \u0003בוחל\u0004 — \u0003אלו ימי נעוריה\u0004 (משתים עשרה שנה ויום אחד, שהביאה שתי שערות).","\u0003בזו\u0004 (הקטנה) \u0003ובזו\u0004 (הנערה) \u0003אמרו\u0004 חכמים: \u0003אביה זכאי במציאתה\u0004 (שמה שמצאו הן, שייך לו), \u0003ובמעשה ידיה, ובהפרת נדריה\u0004 (שיכול הוא להפר את נדרן). ואילו זו המכונה \u0003צמל,\u0004 שהריהי בת שתים עשרה שנה וששה חדשים, וסימני דדיה מעידים בה שבגרה — \u0003כיון שבגרה, שוב אין לאביה רשות בה.\u0004 ומעתה, אינו מפר לה את נדריה, ומציאתה ומעשה ידיה שייכים לה.","ומבררים: \u0003איזהו\u0004 (מהם) ה\u0003סימנין\u0004 של זו המכונה צמל? \u0003ר' יוסי הגלילי אומר: מ\u0004הזמן \u0003ש\u0004בו \u0003יעלה\u0004 (יגדל) הדד במידה כזו שנראה כמזדקר מעל הגוף, וגורם שייראה \u0003הקמט תחת הדד.\u0004 \u0003ר'\u0004 \u0003עקיבא אומר: מ\u0004הזמן שגדלו הדדים במידה כזו עד \u0003שיטו\u0004 (ינטו) \u0003הדדים\u0004 אל החזה. \u0003בן עזאי אומר: משישחיר הפיטומת\u0004 (הפיטמה) שבדדים. \u0003ר' יוסי אומר:\u0004 מהשלב בהתפתחות הדדים, שיש בהם \u0003כדי שיהא\u0004 אדם \u0003נותן ידו על העוקץ\u0004 שבדדים, \u0003והוא שוקע ושוהא\u0004 מ\u0003לחזור.\u0004","שנינו במשנתנו כי המכונה \u0003פגה\u0004 היא זו ש\u0003עודה תנוקת.\u0004 ומסבירים מה מקור כינוי זה: \u0003כדכתיב\u0004 \u0005[כמו שנאמר]\u0006 \u0003\"התאנה חנטה פגיה...\u0004 קומי לך רעיתי\" (שיר השירים ב, יג). ועוד נאמר כי הכינוי \u0003בוחל\u0004 בנשים \u0003אלו ימי הנעורים.\u0004 ומסבירים מה מקור כינוי זה: \u0003כדתנן\u0004 \u0005[כמו ששנינו\u0006 במשנה\u0005],\u0006 \u0003התאנים\u0004 חייבות בהפרשת מעשרות \u0003מ\u0004השלב בהתפתחותן \u0003ש\u0004בו הן \u0003יבחלו\u0004 (התחילו להבשיל), \u0003ואמר רבה בר בר חנה, אמר רב\u0004 בהמחשת שלב זה של הבחלת התאנים: \u0003מ\u0004זמן \u0003ש\u0004בו \u0003ילבין ראשיהן\u0004 של התאנים.","\u0003ואיבעית אימא מהכא\u0004 \u0005[ואם תרצה אמור\u0006 כי מכאן], מן המקרא הזה הוא מקור כינוי זה, שכן נאמר \u0003\"ותקצר נפשי בהם וגם נפשם בחלה בי\"\u0004 (זכריה יא, ח). שכן מורה צורה זו על גודל הדבר (\"בחלה בי\" — גדלה עלי). ועוד שנינו כינוי \u0003צמל,\u0004 ומסבירים את פשר השם: \u0003כמאן דאמר\u0004 \u0005[כמי שאומר,\u0006 כדברי הבריות\u0005]\u0006 \u0003\"יצתה\u0004 (יצאה) \u0003מלאה\",\u0004 שגדלה די צורכה.","ועוד שנינו במשנתנו בהגדרת המכונה צמל: \u0003ואיזהו סימנים? ר'\u0004 \u0003יוסי הגלילי אומר: משיעלה הקמט\u0004 תחת הדד. ובהסבר הדבר, \u0003אמר שמואל: לא משיעלה הקמט ממש\u0004 וייראה כך תמיד, \u0003אלא\u0004 כבר מהשלב שגדל הדד במידה כזו \u0003כדי ש\u0004אם היא \u0003תחזיר ידיה\u0004 (מותחת גופה) \u0003לאחוריה, ו\u0004היא \u0003נראית כמי שיעלה הקמט תחת הדד.\u0004","ומסופר כי \u0003שמואל בדק ב\u0004דדיה של \u0003אמתיה\u0004 \u0005[בשפחתו הכנענית],\u0006 את זמני ההתפתחות הללו הנזכרים במשנתנו, \u0003ו\u0004לאחר מכן \u0003יהב\u0004 \u0005[נתן]\u0006 \u0003לה ארבעה זוזי\u0004 \u0005[זוזים]\u0006 כ\u0003דמי בושתה.\u0004 ומסבירים: טעמו של שמואל ששילם לשפחתו על שבדקה כך, משום ש\u0003שמואל\u0004 נוהג \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005], ש\u0006\u0003אמר שמואל\u0004 על האמור בתורה ביחס לעבדים: \u0003\"לעלם בהם תעבדו\"\u0004 (ויקרא כה, מו) — \u0003לעבודה\u0004 בלבד \u0003נתתים\u0004 לך, \u0003ולא לבושה.\u0004 ואם בייש האדון את העבד, הרי הוא חייב בדמי בושתו.","ובענין היחס לשפחות נמסר כי \u0003שמואל\u0004 היה \u0003מייחד להן\u0004 לכל אחת משפחותיו גבר מסויים מעבדיו שישמש איתה, ולא היה מוסרה לכל. ואילו על \u0003רב נחמן\u0004 נמסר שהיה \u0003מחליף להן\u0004 \u0005[אותן],\u0006 בין עבדיו. ו\u0003רב ששת מסר להן\u0004 (אותן, את שפחותיו) \u0003לערבי, ואמר להן:\u0004 יכולות אתן להיבעל לכל, ואולם \u0003אזדהרו\u0004 \u0005[הזהרו]\u0006 \u0003מ\u0004להיבעל \u0003לישראל.\u0004","שנינו במשנתנו כי \u0003ר' יוסי אמר\u0004 כדי שיהא נותן ידו על העוקץ והוא שוקע ושוהא מלחזור. ומבררים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003עוקץ\u0004 זה? \u0003אמר שמואל: עוקצו\u0004 הוא החלק הבולט במרכזו \u0003של\u0004 ה\u0003דד\u0004 (הפיטמה).","ועוד בסימני הבגרות באשה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 \u0003אלו הן סימני בגרות? ר'\u0004 \u0003אלעזר בר' צדוק אומר: משיתקשקשו\u0004 (שיקישו זה בזה) \u0003הדדין\u0004 מחמת גודלם. \u0003ר' יוחנן בן ברוקה אומר: משיכסיף\u0004 (ישחיר) \u0003ראש החוטם\u0004 (הבליטה שבמרכזה הפיטמה). ותוהים: \u0003משיכסיף?\u0004 והרי בסימן זה \u0003אזקונה לה\u0004 \u0005[מזקינים אותה,\u0006 מאחרים בהרבה את ראשית זמן בגרותה\u0005]!\u0006 \u0003אלא אמר רב אשי: משיפציל\u0004 (שיתפצל) \u0003ראש החוטם.\u0004 \u0003ר'\u0004 \u0003יוסי אומר: משתקיף העטרה,\u0004 שעוקץ הפיטמה גדול במידה כזו, שהוא מוקף בעיגול מסביבו. \u0003ר' שמעון אומר: משנתמעך\u0004"],["\u0003הכף\u0004 (הבליטה המצויה מעל בית הרחם).","\u0003וכן היה ר'\u0004 \u0003שמעון (בן יוחי) אומר: שלשה סימנין נתנו חכמים באשה מלמטה\u0004 (במקום הערוה), \u0003וכנגדן\u0004 (במקביל להם) נתנו שלושה סימנים \u0003מלמעלה\u0004 (בדדים), מי שמוגדרת כ\u0003פגה\u0004 בהסתמך על הסימנים ש\u0003מלמעלה\u0004 — \u0003בידוע\u0004 (ברור) \u0003שלא הביאה שתי שערות.\u0004 ומי שמוגדרת כ\u0003בוחל\u0004 בהסתמך על הסימנים ש\u0003מלמעלה\u0004 — \u0003בידוע\u0004 (ברור) \u0003שהביאה שתי שערות.\u0004 ומי שמוגדרת כ\u0003צמל\u0004 על סמך הסימנים של \u0003מלמעלה\u0004 — \u0003בידוע\u0004 (ברור) \u0003שנתמעך הכף.\u0004","ומבררים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003כף? אמר רב הונא: מקום תפוח יש למעלה מאותו מקום\u0004 (כינוי בלשון נקיה לבית הרחם), שבתחילתו הוא קשה, ו\u0003כיון שמגדלת\u0004 הבת הריהו \u0003מתמעך\u0004 (מתרכך) \u0003והולך.\u0004 \u0003שאלו\u0004 התלמידים \u0003את רבי:\u0004 בסימני הבגרות של האשה, \u0003הלכה כדברי מי\u0004 מדברי החכמים ששנינו? \u0003שלח להו\u0004 \u0005[להם]\u0006 בתשובה: הלכה \u0003כדברי כולן להחמיר,\u0004 שכל שהופיע באשה אחד מהסימנים הללו שנתנו החכמים, יש להחמיר ולנהוג בה כבוגרת.","בדברי רבי שאמר שהלכה כדברי כל התנאים להחמיר, נחלקו \u0003רב פפא ורב חיננא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא,\u0004 באיזה ענין אמרו. \u0003חד מתני אהא\u0004 \u0005[אחד\u0006 מהם \u0005שונה\u0006 את דברי רבי \u0005על זה\u0006 ששנינו כאן, בסימני הבוגרת\u0005],\u0006 \u0003וחד מתני\u0004 \u0005[ואחד\u0006 מהם \u0005שונה\u0006 את דברי רבי\u0005]\u0006 בענין \u0003חצר צורית.\u0004 ומסבירים, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 בדין המעשרות, \u0003איזוהי חצר צורית שחייבת\u0004 (שמחייבת את התבואה הנכנסת אליה) \u0003במעשר? ר'\u0004 \u0003שמעון אומר: חצר הצורית,\u0004 זו החצר \u0003שהכלים נשמרים בתוכה.\u0004","ומבררים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"חצר הצורית\"?\u0004 \u0003אמר רבה בר בר חנה, אמר ר'\u0004 \u0003יוחנן:\u0004 חצר זו נקראת כך, \u0003שכן ב\u0004עיר \u0003צור\u0004 נוהגים ש\u0003מושיבין שומר על פתח החצר,\u0004 כדי שיישמרו הכלים שבתוכה. ומשום כך, כל חצר שנשמרים הכלים שבתוכה נקראת \"חצר צורית\". \u0003ר' עקיבא אומר: כל\u0004 חצר כזו \u0003ש\u0004אין בה שומר קבוע הפותח ונועל, אלא \u0003אחד\u0004 מהדרים בתוכה \u0003פותח\u0004 אותה \u0003ואחד נועל\u0004 אותה, וכגון חצר שיש לה כמה שותפים, שכל אחד נוהג בה כרצונו ובלא דעת חבירו — הרי זו \u0003פטורה\u0004 (אינה מחייבת) את התבואה הנמצאת בה במעשר, שאינה נחשבת כחצר שמורה.","\u0003ר' נחמיה אומר: כל\u0004 חצר \u0003ש\u0004נסתרת מעיניהם של הנמצאים מחוצה לה, וכך \u0003אין אדם בוש לאכול בתוכה\u0004 — הרי זו \u0003חייבת\u0004 (מחייבת) את התבואה הנמצאת בה במעשרות, שזוהי חצר שמורה. \u0003ר' יוסי אומר: כל\u0004 חצר \u0003ש\u0004כאשר \u0003נכנסים לה\u0004 (לתוכה) אנשים שאינם גרים בה, \u0003ואין אומרים לו\u0004 לנכנס \u0003\"מה אתה מבקש\"\u0004 — הרי זו \u0003פטורה\u0004 (אינה מחייבת) את התבואה שבה במעשרות, שאין זו נחשבת כחצר שמורה.","\u0003ר' יהודה אומר:\u0004 היו \u0003שתי חצרות זו לפנים מזו,\u0004 באופן שאין הגרים בחצר הפנימית יכולים להיכנס לביתם אלא כשהם עוברים בחצר החיצונית תחילה, ואולם הגרים בחצר החיצונית אינם נכנסים לחצר הפנימית — התבואה הנמצאת בחצר \u0003הפנימית חייבת\u0004 במעשרות, שהרי חצר זו הינה חצר שמורה (מפני אחרים), \u0003ו\u0004אילו התבואה הנמצאת בחצר \u0003החיצונה\u0004 — \u0003פטורה\u0004 מן המעשרות, שאין זו חצר שמורה, שהרי הגרים בחצר הפנימית עוברים בה.","ובענין זה \u0003שאלו\u0004 התלמידים \u0003את רבי: הלכה כדברי מי\u0004 מהחכמים הללו: \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003הלכה כדברי כולן, להחמיר.\u0004 שכל חצר שנחשבת כחצר המחייבת בהפרשת תרומה את התבואה הנמצאת בה, לפי כל אחת מהשיטות הללו, יש להחמיר בה, ולהפריש תרומה.","התינוקת שמלאו לה שתים עשרה שנה ויום אחד, והביאה שתי שערות באזור הערוה — הריהי נקראת מעתה נערה, ולאחר ששה חדשים — הריהי נחשבת כבוגרת. ואולם זו שהיא \u0003בת עשרים שנה שלא הביאה\u0004 עדיין \u0003שתי שערות\u0004 ולא חל עליה שם נערה — \u0003תביא ראיה שהיא\u0004 אכן \u0003בת עשרים שנה, ו\u0004מכאן ואילך \u0003היא\u0004 נחשבת כ\u0003איילונית\u0004 (שאינה מסוגלת ללדת), ואם נישאה ומת בעלה בלא בנים, הריהי \u0003לא חולצת ולא מתיבמת\u0004 מאחי בעלה, שהרי נאמר דין ייבום רק כשיכולה ללדת לאח זרע שייקרא על שם המת, והאיילונית אינה בכלל זה.","וכן בדיני האיש, שהוא \u0003בן עשרים שנה שלא הביא\u0004 עדיין \u0003שתי שערות\u0004 — \u0003יביאו ראיה שהוא בן עשרים שנה, ו\u0004מכאן ואילך \u0003הוא\u0004 נחשב כ\u0003סריס,\u0004 ואינו בכלל מצות ייבום, שאם מת אחיו בלא בנים — \u0003לא חולץ ולא מיבם\u0004 את אשת אחיו המת. \u0003אלו דברי בית הלל.\u0004 ואילו \u0003בית שמאי אומרים: זה וזה,\u0004 הן האשה והן האיש שלא הביאו שתי שערות \u0003בן שמונה עשרה\u0004 — יביאו ראיה שהם בני שמונה עשרה, ומעתה הם נחשבים כאיילונית (באשה) או סריס (באיש), ויחולו עליהם מעתה דינם של אלו.","ואילו \u0003ר' אליעזר אומר:\u0004 דין \u0003הזכר\u0004 הסריס — \u0003כדברי בית הלל,\u0004 שנחשב סריס רק בגיל עשרים, \u0003ו\u0004אילו דין \u0003הנקבה\u0004 האיילונית — \u0003כדברי בית שמאי,\u0004 שהריהי איילונית כבר בגיל שמונה עשרה. וטעמה של הבחנה זו: משום \u0003שהאשה ממהרת לבא\u0004 לכלל בגרות \u0003לפני האיש.\u0004","שנינו במשנתנו שהסריס אינו מייבם את אשת אחיו שמת, ואין אשת הסריס נזקקת לחליצה על מנת להיות מותרת להינשא לכל. \u0003ו\u0004על כך \u0003רמינהי\u0004 \u0005[משליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו במסכת יבמות: \u0003אחד לי\u0004 מי שהוא \u0003בן תשע שנים ויום אחד\u0004 שלא הביא שערות, \u0003ואחד לי\u0004 מי שהוא \u0003בן עשרים שלא הביא שתי שערות\u0004 — זה וזה שווים לענין ייבום, שאם באו על אשת אחיהם שמת בלא בנים — ביאתם נחשבת במקצת, וחייבת בגט ובחליצה!","\u0003אמר רב שמואל בר רב יצחק, אמר רב\u0004 בהסבר דין משנתנו: \u0003והוא שנולדו בו,\u0004 לזה שהיה בן עשרים ולא הביא שתי שערות, \u0003סימני סריס\u0004 אחרים. ולכן אין ביאתו נחשבת. ואילו במשנה במסכת יבמות מדובר במי שלא היו בו סימני סריס אחרים. \u0003אמר רבא: דיקא נמי, דקתני\u0004 \u0005[מדוייק גם כן\u0006 הסברו זה של רב\u0005, ש\u0006כן \u0005שנינו\u0006 שם\u0005]\u0006 \u0003\"והוא סריס\".\u0004 ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שמדובר כאן במי שברור לנו שהוא סריס.","ושואלים לעצם ההלכה: \u0003וכי\u0004 \u0005[וכאשר]\u0006 \u0003לא נולדו לו סימני סריס, עד כמה\u0004 שנים מחשיבים אותו כקטן? \u0003תני\u0004 \u0005[שנה]\u0006 החכם מבית מדרשו של \u0003ר' חייא: עד\u0004 שיגיע לכלל \u0003רוב שנותיו\u0004 של אדם, כלומר, עד שיהיה בן שלושים וחמש שנים (שהן מחציתן של שבעים שנה, שנות חיי אדם רגיל).","ומסופר עוד באותו ענין: \u0003כי אתו לקמיה\u0004 \u0005[כאשר היו באים לפני]\u0006 \u0003ר' חייא\u0004 לשאול על מי שהגיע לשנים הראויות לבגרות, ולא נראו בו סימני בגרות איך לדון בעניינו, כך היה נוהג: \u0003אי כחיש\u0004 \u0005[אם\u0006 אותו הנדון היה \u0005רזה],\u0006 היה ר' חייא \u0003אמר להו\u0004 \u0005[אומר להם]:\u0006 \u0003אבריוה\u0004 \u0005[השמינו אותו].\u0006 ו\u0003אי בריא\u0004 \u0005[אם\u0006 הוא היה \u0005שמן],\u0006 היה ר' חייא \u0003אמר להו\u0004 \u0005[אומר להם]:\u0006 \u0003אכחשוה\u0004 \u0005[הרזוהו]\u0006 תחילה. וטעם הדבר, משום \u0003דהני\u0004 \u0005[שאלו]\u0006 ה\u0003סימנים זימנין דאתו\u0004 \u0005[פעמים שבאים]\u0006 \u0003מחמת כחישותא\u0004 \u0005[רזון],\u0006 \u0003זימנין דאתו\u0004 \u0005[פעמים שבאים]\u0006 \u0003מחמת בריאותא\u0004 \u0005[שומן].\u0006 ושמא אם יגיע למצב גופני ראוי, יהיו בו סימני בגרות, ולא יצטרכו לדונו.","\u0003אמר רב: הלכתא בכולי\u0004 \u0005[ההלכה בכל]\u0006 העניינים הנזכרים ב\u0003פרקא\u0004 \u0005[פרק]\u0006 \"יוצא דופן\" שצויין בהם מניין שנים, ואף שלא צויין במפורש \"ויום אחד\" — הכוונה לשנים מלאות ובתוספת \u0003מעת לעת.\u0004 \u0003ועולא אמר:\u0004 בדבר \u0003דתנן\u0004 \u0005[שנינו]\u0006 בו \"ויום אחד\" — \u0003תנן\u0004 \u0005[שנינו],\u0006 \u0003ודלא תנן\u0004 \u0005[ו\u0006בדבר שלא שנינו] בו \"ויום אחד\", וכמו במשנתנו — \u0003לא תנן\u0004 \u0005[שנינו].\u0006 ודנים בשיטות אלה.","\u0003בשלמא\u0004 \u0005[נוח,\u0006 מובן\u0005]\u0006 \u0003ל\u0004שיטת \u0003עולא היינו דקתני\u0004 \u0005[זה שהוא\u0006 התנא \u0005שונה]\u0006 בפרקנו \u0003הכא\u0004 \u0005[כאן]\u0006 בענין זה \u0003\"יום אחד\" והכא\u0004 \u0005[וכאן]\u0006 בענין אחר \u0003לא קתני\u0004 \u0005[שונה]\u0006 \"ויום אחד\", \u0003אלא לרב\u0004 שלדעתו בכל העניינים שבפרק הכוונה ל\"ויום אחד\", \u0003ליתני\u0004 \u0005[שישנה]\u0006 התנא אף במשנתנו \"ויום אחד\" כמו ששנה בכל הפרק!","\u0003ועוד\u0004 יש לשאול על רב, ממה ש\u0003תני\u0004 \u0005[שנינו]:\u0006 \u0003ר' יוסי בן כיפר אומר משום\u0004 \u0005[בשם]\u0006 \u0003ר' אליעזר\u0004 בדין הסריס והאיילונית: \u0003שנת עשרים שיצאו ממנה\u0004 (שחלפו בתוכה) \u0003שלשים יום,\u0004 כלומר, מגיל תשע עשרה שנים ושלושים יום — \u0003הרי היא\u0004 נחשבת \u0003כשנת עשרים לכל דבריה, וכן הורה\u0004 הלכה למעשה \u0003רבי ב\u0004עיר \u0003לוד\u0004 כי \u0003שנת שמנה עשרה שיצאו ממנה שלשים יום\u0004 — \u0003הרי היא כשנת שמנה עשרה לכל דבריה.\u0004","ומעתה יש לשאול: \u0003בשלמא\u0004 \u0005[נוח,\u0006 מובן\u0005]\u0006 לשיטת עולא, הברייתא מובנת, וזה שצויין בה \u0003ל\u0004שיטת \u0003רבי\u0004 שנת שמונה עשרה, ולשיטת \u0003ר' יוסי בן כיפר\u0004 שנת עשרים \u0003לא קשיא\u0004 \u0005[קשה],\u0006 שכן \u0003הא\u0004 \u0005[זה]\u0006 שאמר רבי הוא \u0003כ\u0004שיטת \u0003בית שמאי\u0004 באשה, ואילו \u0003הא\u0004 \u0005[זה]\u0006 שאמר ר' יוסי בן כיפר הוא \u0003כ\u0004שיטת \u0003בית הילל.\u0004 \u0003אלא ל\u0004שיטת \u0003רב\u0004 המצריך בדין הסריס שנים מלאות ויום אחד, \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי רבי ור' יוסי בן כיפר!","ומשיבים: מחלוקת \u0003תנאי\u0004 \u0005[תנאים]\u0006 \u0005היא אם צריכים שנים מלאות ויום אחד.\u0006 \u0005ורב סבור כשיטת התנאים שצריך שנים מלאות ויום אחד.\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 בה נידונו הלכות שונות לענין הגדרת השנה האמורה בהן: \u0003שנה האמורה ב\u0004דין ה\u0003קדשים\u0004 (הקרבן הכשר להקרבה), וכן דין \u0003שנה האמורה ב\u0004גאולת \u0003בתי ערי חומה\u0004 שנמכרו (\"ואיש כי ימכור בית מושב עיר חומה והיתה גאולתו עד תום שנת ממכרו\". ויקרא כה, לא), וכן דין \u0003שתי שנים ש\u0004אמורות \u0003ב\u0004גאולת \u0003שדה אחוזה\u0004 (\"במספר שני תבואות ימכר לך\".","שם פסוק טו), וכן דין \u0003שש שנים ש\u0004אמורות \u0003ב\u0004משך זמן עבדותו של \u0003עבד עברי\u0004 (\"כי תקנה עבד עברי שש שנים יעבוד ובשביעית יצא לחפשי חנם\", שמות כא, ב). \u0003וכן\u0004 דין השנים \u0003ש\u0004אמורות \u0003בבן וש\u0004אמורות \u0003בבת\u0004 — \u0003כולן\u0004 הן שנים מלאות \u0003מעת לעת.\u0004 וכדעת תנא זה היא שיטת רב, שמנין השנים בבן ובבת לענין קביעת סריס ואיילונית, הוא שנה מלאה מעת לעת.","ומפרטים: \u0003שנה האמורה בקדשים מנא לן\u0004 \u0005[מנין לנו]\u0006 שכך הוא הגדרתה? \u0003אמר רב אחא בר יעקב,\u0004 כך \u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"כבש בן שנתו\"\u0004 (ויקרא יב, ו), ודיוק הכתוב: \u0003שנתו שלו, ולא שנה של מנין עולם.\u0004","\u0003שנה האמורה ב\u0004גאולת \u0003בתי ערי חומה מנלן\u0004 \u0005[מנין לנו]\u0006 שכך הוא הגדרתה? \u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \"והיתה גאולתו \u0003עד תום שנת ממכרו\u0004 ימים תהיה גאולתו\". שם כה, כט). ודיוק הכתוב: שנת \u0003ממכרו שלו, ולא שנת של מנין עולם.\u0004 \u0003שתי שנים ש\u0004אמורות \u0003ב\u0004גאולת \u0003שדה אחוזה מנלן\u0004 \u0005[מנין לנו]\u0006 שכך הוא הגדרתן? \u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \"במספר שנים אחר היובל תקנה מאת עמיתך \u0003במספר\u0004"],["\u0003שני תבואות ימכר לך\"\u0004 (ויקרא כה, טו), והרי ריבוי לשון זה (\"שני\" המורה על שתי שנים, ו\"תבואות\") בא להורות: כי \u0003פעמים\u0004 נמצא \u0003שאתה מוכר שלשה תבואות\u0004 (יבולים) \u0003ב\u0004תוך \u0003שתי שנים.\u0004 שכן אם מכר בסוף הקיץ שדה ובה יבול, והניבה יבול נוסף בשנה שלאחריה, ובשנה השלישית בסוף הקיץ שוב הניבה יבול, הרי זה שלושה יבולים בפחות משתי שנים מעת לעת. ומבררים עוד: \u0003שש שנה ש\u0004אמורות \u0003ב\u0004דינו של \u0003עבד עברי מנלן\u0004 \u0005[מנין לנו]\u0006 שהן שנים מלאות מעת לעת? \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 בדין העבד \"כי תקנה עבד עברי \u0003שש שנים יעבד\u0004 ובשביעית יצא לחפשי חנם\" (שמות כא, ב), ומורה וא\"ו החיבור של המלה \u0003\"ובשביעית\"\u0004 — \u0003וב\u0004שנה ה\u0003שביעית\u0004 (בסדר שנות עולם, אף שעדיין לא עברו שש שנים שלמות מאז נמכר) \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003יעבוד.\u0004 וכגון שנמכר בחודש ניסן, שאף שעברו חמש שנים וששה חודשים והגיע חודש תשרי של השנה השביעית (לסדר שנות עולם), כיון שעדיין לא השלים שש שנות עבדות, יעבוד אף בשנה זו עד ליום בחודש בו נמכר.","","מה ששנינו בהגדרת השנים \u0003שבבן ושבבת למאי הלכתא\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה]\u0006 נאמרו הדברים הללו? \u0003אמר רב גידל, אמר רב: לענין ערכין,\u0004 שכן משתנה ערכם של הזכר והנקבה בהתאם לשנותיהם. \u0003ורב יוסף אמר: ל\u0004ענין ההלכה האמורה ב\u0003פרקין\u0004 \u0005[פרקנו],\u0006 פרק \u0003\"יוצא דופן\"\u0004 שלא נאמר בה במפורש \"ויום אחד\", בהגדרת הגיל שבו הם נחשבים כסריס וכאיילונית.","","","","","","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרב יוסף: \u0003מי פליגת\u0004 \u0005[האם אתה חולק]\u0006 על רב בדין, שאתה סבור שהדין בבן ובבת אינו אלא בדין הסריס והאיילונית והוא סבור שאינו אלא בערכין? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף לאביי: \u0003לא,\u0004 אין זה כך, אלא ש\u0003הוא\u0004 רב \u0003אמר חדא\u0004 \u0005[\u0006דבר \u0005אחד],\u0006 \u0003ואנא אמינא חדא\u0004 \u0005[ואני אמרתי\u0006 דבר \u0005אחד],\u0006 \u0003ולא פליגינן\u0004 \u0005[ואין אנו חולקים].\u0006 שכל אחד מאתנו מסכים לדברי האחר. \u0003ו\u0004מעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לומר, שכן \u0003אי סלקא\u0004 \u0005[אם עולה]\u0006 על \u0003דעתך\u0004 לומר ש\u0003פליגי\u0004 \u0005[חולקים]\u0006 הם זה על זה, וכי \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שהאמור בברייתא \u0003לערכין לא אמר\u0004 שכך הדין אף \u0003ל\u0004ענין הנזכר בפרק \u0003\"יוצא דופן\"\u0004 (בדין הסריס והאיילונית)? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב: הלכתא בכולה פרקין\u0004 \u0005[הלכה בכל פרקנו]\u0006 בשנים מלאות, \u0003מעת לעת,\u0004 והרי שאף הוא סבור, כרב יוסף, לענין דין הבן והבת.","","","","","","","","","","\u0003אלא\u0004 מעתה יש לשאול: \u0003למאן דאמר\u0004 \u0005[למי שאומר,\u0006 לרב\u0005]\u0006 שכוונת האמור בברייתא \"שבבן ושבבת\" \u0003לערכין מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר\u0004 שדין זה נאמר ביחס לאמור בפרק \"\u0003יוצא דופן\"\u0004 לענין הסריס והאיילונית, שהרי גם הוא סבור כן להלכה? ומסבירים: ראוי להעמיד את האמור בברייתא לענין ערכין דווקא, משום שעניינם \u0003דומיא דהנך\u0004 \u0005[דומה לאלו]\u0006 העניינים האחרים הנזכרים בברייתא, שכן, \u0003מה הנך דכתיבן\u0004 \u0005[אלו\u0006 ענייני ערכין הם דברים שכתובים בפירוש בתורה\u0005],\u0006 \u0003אף הני נמי דכתיבן\u0004 \u0005[אלו גם\u0006 \"שבבן ושבבת\" הריהם דברים \u0005שכתובים\u0006 במפורש בתורה\u0005].\u0006 ושואלים: \u0003ואידך\u0004 \u0005[והאחר,\u0006 רב יוסף\u0005]\u0006 המפרש את האמור בברייתא ביחס לסריס ואיילונית, מה משיב הוא לדברי רב? לשיטתו מתאים לשון \u0003האי\u0004 \u0005[זה]\u0006 ששנינו בברייתא \u0003\"שבבן ושבבת\",\u0004 ואולם לשיטת רב שהברייתא עוסקת בערכין, לשון \u0003\"שבזכר ושבנקבה\" מבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר. \u0003אמר רב יצחק בר נחמני, אמר ר'\u0004 \u0003אלעזר: הלכה\u0004 היא \u0003כ\u0004שיטת \u0003ר' יוסי בן כיפר שאמר משום\u0004 (בשם) \u0003ר' אליעזר,\u0004 ומשחלפו שלושים יום בשנה העשרים, נחשב הוא לגדול. ובענין זה מסופר כי \u0003אמר ר'\u0004 \u0003זירא: אזכה ואיסק ואגמר לשמעתא מפומיה דמרא\u0004 \u0005[ואעלה\u0006 מבבל לארץ ישראל, \u0005ואלמד את הסוגיה מפי בעליה].\u0006 ונמסר: \u0003כי סליק\u0004 \u0005[כאשר עלה]\u0006 ר' זירא לארץ ישראל \u0003אשכחיה\u0004 \u0005[מצאו]\u0006 \u0003לר' אלעזר, אמר ליה\u0004 \u0005[לו]:\u0006 האמנם \u0003אמרת\u0004 ש\u0003הלכה כר' יוסי בן כיפר? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מסתברא אמרי\u0004 \u0005[מסתבר\u0006 ש\u0005אמרתי],\u0006 \u0003מדכוליה פירקין תני\u0004 \u0005[מ\u0006תוך ש\u0005כל פרקנו שונה]\u0006 \u0003\"יום אחד\", והכא\u0004 \u0005[וכאן\u0006 בדין הסריס והאיילונית\u0005]\u0006 \u0003לא קתני\u0004 \u0005[שונה],\u0006 \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 כי \u0003מסתברא כותיה\u0004 \u0005[מסתבר כמותו].\u0006 אם \u0003בא\u0004 (הופיע) אצל הבת ה\u0003סימן התחתון\u0004 (שתי שערות במקום הערוה) \u0003עד שלא\u0004 (בטרם) \u0003בא\u0004 הסימן \u0003העליון\u0004 (שבדדים) — הריהי נחשבת כגדולה שהרי הביאה שתי שערות, שהן סימן מובהק, ואם מת בעלה בלא שהניח אחריו זרע, ונפלה לפני אחי בעלה למצות ייבום — הריהי \u0003או חולצת או מתיבמת.\u0004 \u0003בא\u0004 הסימן \u0003העליון עד שלא בא\u0004 הסימן \u0003התחתון,\u0004 שעדיין לא הביאה שתי שערות, \u0003אף על פי ש\u0004במציאות \u0003אי אפשר\u0004 שכך יקרה. \u0003ר' מאיר אומר:\u0004 אפשר שיופיע הסימן העליון לפני הסימן התחתון, וכיון שלא נראה עדיין הסימן התחתון, יש לחשוש שעדיין לא הופיע כלל, והרי היא עדיין קטנה. ולכן אם נפלה לייבום, \u0003לא חולצת ולא מתיבמת.\u0004 \u0003וחכמים אומרים:\u0004 הריהי נחשבת גדולה, ומשום כך היא \u0003או חולצת או מתיבמת.\u0004 וטעמם \u0003מפני ש\u0004כך \u0003אמרו\u0004 חכמים: \u0003אפשר ל\u0004סימן ה\u0003תחתון לבא עד שלא בא\u0004 הסימן \u0003העליון, אבל אי אפשר ל\u0004סימן ה\u0003עליון לבא עד שלא בא ה\u0004סימן ה\u0003תחתון.\u0004 שנינו במשנתנו שנחלקו חכמים ור' מאיר בדינה של הבת שהופיע אצלה הסימן העליון בטרם נראה בה הסימן התחתון, וציינה המשנה \u0003אף על פי שאי אפשר\u0004 שיתרחש כדבר הזה. ותוהים על כך: \u0003והלא\u0004 שנינו במשנה, \u0003בא\u0004 העליון עד שלא בא התחתון, והרי שייתכן הדבר! ומשיבים: מה ששנינו ש\u0003בא\u0004 הסימן העליון לפני שבא הסימן התחתון, הרי זה \u0003ל\u0004דעת \u0003ר' מאיר\u0004 הסבור שדבר זה אפשר שיקרה, ואילו זה ששנינו \u0003אף על פי שאי אפשר\u0004 שדבר זה יקרה, הרי זה \u0003ל\u0004דעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 הסבורים שלא ייתכן שיופיע הסימן העליון בלא שהופיע כבר הסימן התחתון. ושואלים על כך: מדוע בכלל יש צורך לשנות \"אף על פי שאי אפשר \u0003ולתני\u0004 \u0005[ושישנה]\u0006 התנא כך: \u0003\"בא\u0004 הסימן \u0003העליון\u0004 בלא שבא הסימן התחתון. \u0003ר' מאיר אומר: לא חולצת ולא מתיבמת,\u0004 משום שאפשר שיבוא הסימן העליון בלא שיבוא קודם הסימן התחתון, ועדיין קטנה היא. \u0003וחכמים אומרים: א\u0004 \u0003ו חולצת או מתיבמת.\u0004 \u0003ואנא ידענא\u0004 \u0005[ואני\u0006 בעצמי \u0005אדע]\u0006 שטעמם של חכמים, \u0003משום\u0004 ש\u0003אי אפשר\u0004 שיבוא הסימן העליון בלא הסימן התחתון, \u0003הוא!\u0004 ומשיבים: \u0003אי לא תנא\u0004 \u0005[אם לא היה שונה]\u0006 \u0003\"אף על פי שאי אפשר\", הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 כי אמנם אצל \u0003רוב נשים\u0004 הסימן ה\u0003תחתון אתי ברישא\u0004 \u0005[בא בתחילה]\u0006 ולאחר מכן בא הסימן העליון, \u0003ו\u0004אולם אצל \u0003מיעוט\u0004 נשים, הסימן ה\u0003עליון אתי ברישא\u0004 \u0005[בא בתחילה],\u0006 \u0003ור' מאיר\u0004 במשנתנו, המחמיר בה כבדין קטנה, שלא תחלוץ ולא תתייבם, הולך בהלכה זו \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 \u0003דחייש למיעוטא\u0004 \u0005[שחושש למיעוט],\u0006 שהיא ממיעוט נשים שאצלן הסימן העליון בא לפני הסימן התחתון, ועדיין קטנה היא. \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 אף הם הולכים \u0003לטעמייהו\u0004 \u0005[לטעמם,\u0006 לשיטתם\u0005],\u0006 \u0003דלא חיישי למיעוטא\u0004 \u0005[שאינם חוששים למיעוט],\u0006 ולכן הריהי כגדולה. \u0003ו\u0004אולם \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא \u0003בסתמא\u0004 \u0005[בסתם],\u0006 כשלא נבדקה אם יש בה סימן תחתון, שאז סומכים על רוב זה, ואין חוששים למיעוט. \u0003אבל היכא דבדקן\u0004 \u0005[היכן\u0006 במקרה \u0005שבדקנו]\u0006 אותה אם יש בה סימן תחתון, \u0003ולא אשכחן\u0004 \u0005[ולא מצאנו]\u0006 בה, במקרה שכזה \u0003אימר\u0004 \u0005[אמור]\u0006 ש\u0003מודו ליה רבנן\u0004 \u0005[מודים לו חכמים]\u0006 \u0003לר' מאיר\u0004 שהסימן ה\u0003עליון קדים\u0004 \u0005[קדם]\u0006 לסימן התחתון, ולא תתייבם ולא תחלוץ. לכן \u0003קא משמע לן\u0004 \u0005[הוא,\u0006 התנא \u0005משמיע לנו]\u0006 ש\u0003אי אפשר\u0004 לעליון לבוא כל עוד לא בא התחתון, ואף אם נבדקה ולא נמצא בה סימן תחתון, יש לומר שב\u0003ודאי אתי\u0004 \u0005[באו]\u0006 שתי השערות, שהן הסימן התחתון, \u0003ו\u0004אולם \u0003מנתר\u0004 \u0005[לנשור]\u0006 \u0003הוא דנתר\u0004 \u0005[שנשר].\u0006","ומבררים עוד: \u0003בשלמא\u0004 \u0005[זה נוח,\u0006 מובן\u0005]\u0006 \u0003ל\u0004שיטת \u0003ר' מאיר,\u0004 הסבור שאפשרי הדבר שיופיע הסימן העליון לפני שיופיע הסימן התחתון, \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 בתיאור הבת הגדלה: \"ותרבי ותגדלי ותבואי בעדי עדיים \u0003שדים נכנו ושערך צמח\"\u0004 (יחזקאל טז, ז), הרי שהסימן העליון (\"שדים נכונו\") מתואר לפני הסימן התחתון (\"ושערך צמח\"), \u0003אלא ל\u0004שיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003איפכא מבעי ליה\u0004 \u0005[ההיפך היה צריך לו]\u0006 לומר: תחילה \"שערך צמח\" ואחר כך \"שדים נכונו\"! ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך הוא\u0006 הנביא \u0005אומר]:\u0006 \u0003כיון ש\"שדים נכנו\"\u0004 — \u0003בידוע ש\"שערך צמח\".\u0004 ושואלים עוד: \u0003בשלמא\u0004 \u0005[זה נוח,\u0006 מובן\u0005]\u0006 \u0003ל\u0004שיטת \u0003ר' מאיר,\u0004 שאפשר שיופיע הסימן העליון לפני שיופיע הסימן התחתון, \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 \u0003\"בעשות ממצרים דדיך למען שדי נעוריך\"\u0004 (שם כג, כא), כלומר, שהיו המצרים משחקים בבת המזנה (ככינוי לעם ישראל) וממעכים דדיה (\"בעשות מצרים דדיך\") בעת שהיא עדיין קטנה, על מנת לזנות עמה כשתהיה כאשה, שתבוא לימי נערות, כשיושלכו, ייבקעו, בה חוצה (\"שדי\") שערות סימן נערותה (\"נעוריך\"). הרי איפוא שהסימן העליון יכול להופיע לפני הסימן התחתון, \u0003אלא לרבנן\u0004 \u0005[לחכמים],\u0006 \u0003איפכא מבעי ליה\u0004 \u0005[ההיפך היה צריך לו]\u0006 לומר! ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך הוא\u0006 הנביא \u0005אומר]:\u0006 \u0003כיון שבאו דדיך\u0004 — \u0003בידוע שבאו נעוריך.\u0004 \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר זה בכתוב: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"שדי\u0004 נעוריך\" האמור בכתוב — אין הכוונה לשערות, הסימן התחתון, אלא לסימן העליון, ו\u0003כולה\u0004 \u0005[כל\u0006 הפסוק\u0005] בדדי כתיב\u0006 \u0005[בדדים נאמר],\u0006 \u0003והכי קאמר\u0004 \u0005[וכך אמר]\u0006 \u0003הקדוש ברוך הוא לישראל:\u0004",""],["אף ש\u0003איכרפו\u0004 \u0005[שהחלו לגדול]\u0006 \u0003דדיך,\u0004 עדיין \u0003לא הדרת\u0004 \u0005[לא חזרת]\u0006 \u0003בך\u0004 מדרך הזנות. ועוד זאת, שכבר \u0003אישתדו\u0004 \u0005[גדלו ביותר]\u0006 \u0003דדיך, נמי\u0004 \u0005[גם כן ]\u0006 עדיין \u0003לא הדרת\u0004 \u0005[לא חזרת]\u0006 \u0003בך.\u0004","ושואלים: \u0003דכולי עלמא מיהא\u0004 \u0005[על כל פנים לכולם,\u0006 לכל השיטות, בין לחכמים ובין לר' מאיר\u0005]\u0006 על הסימן ה\u0003תחתון סמכינן\u0004 \u0005[אנו סומכים],\u0006 ועל כך שואלים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 שסומכים עליו בלבד, ואין מצריכים שיהיה גם הסימן העליון? \u0003אמר רב יהודה, אמר רב, וכן תנא דבי\u0004 \u0005[שנה\u0006 החכם של \u0005בית]\u0006 מדרשו של \u0003ר' ישמעאל: אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"איש או אשה כי יעשו מכל חטאת האדם\"\u0004 (במדבר ה, ו) — \u0003השוה הכתוב\u0004 דינה של ה\u0003אשה ל\u0004דינו של ה\u0003איש לכל עונשין שבתורה.\u0004 ומכאן נסיק, \u0003מה\u0004 (כשם) דינו של ה\u0003איש\u0004 הנחשב לגדול — הריהו \u0003בסימן אחד\u0004 (והוא הסימן התחתון, שתי שערות במקום הערוה), \u0003אף\u0004 דינה של ה\u0003אשה,\u0004 שתיחשב כגדולה לחיוב עונשים — הריהו \u0003בסימן אחד,\u0004 והוא הסימן התחתון.","ושואלים על מסקנה זו: \u0003ואימא\u0004 \u0005[ואמור]:\u0006 שדינה של האשה יהיה אמנם בסימן אחד כבאיש, אבל \u0003או האי\u0004 \u0005[זה,\u0006 התחתון\u0005]\u0006 \u0003או האי\u0004 \u0005[זה,\u0006 העליון\u0005,\u0006 ומנין לנו שדווקא בתחתון היא נחשבת לגדולה? ומשיבים: הושווה דין האשה להיות \u0003כ\u0004דינו של ה\u0003איש, מה איש\u0004 — נחשב לגדול בסימן ה\u0003תחתון ולא\u0004 בסימן \u0003עליון\u0004 (שהרי אין לו סימן שכזה), \u0003אף אשה\u0004 — נחשבת כגדולה בסימן ה\u0003תחתון ולא\u0004 בסימן ה\u0003עליון.\u0004","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך],\u0006 שדי בסימן התחתון באשה להחשיבה כגדולה, \u0003אמר ר'\u0004 \u0003אליעזר בר' צדוק: כך היו\u0004 חכמים \u0003מפרשין\u0004 בבית המדרש ש\u0003ביבנה, ואמרו: כיון שבא\u0004 הסימן ה\u0003תחתון\u0004 — \u0003שוב אין משגיחין על\u0004 הופעתו של הסימן ה\u0003עליון\u0004 כדי לקבוע את גדלותה של האשה, שכן הריהי כבר גדולה.","ועוד בענין סדר הופעת הסימנים אצל הבנות, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003רבן שמעון בן גמליאל אומר:\u0004 אצל \u0003בנות\u0004 ה\u0003כרכים\u0004 — הסימן ה\u0003תחתון ממהר\u0004 (מקדים) \u0003לבא\u0004 לפני הופעתו של הסימן העליון, וטעם הדבר, \u0003מפני שרגילות במרחצאות,\u0004 ורחצה מרובה זו מזרזת את צמיחת השערות. ואילו אצל \u0003בנות\u0004 ה\u0003כפרים\u0004 — הסימן ה\u0003עליון ממהר לבא\u0004 לפני התחתון, \u0003מפני שטוחנות ברחים,\u0004 ועבודה קשה זו מאיצה את צמיחת דדיהן.","\u0003ר' שמעון בן אלעזר אומר:\u0004 אף בזמני צמיחת הדדים עצמם, של ימין ושל שמאל, יש להבחין, שכן אצל \u0003בנות עשירים\u0004 — הדד שב\u0003צד ימין\u0004 של גופן \u0003ממהר לבא,\u0004 מפני \u0003שנישוף\u0004 (מתחכך) \u0003באפקריסותן\u0004 (לבוש עליון של בנות עשירים). ואילו אצל \u0003בנות עניים\u0004 — הדד שב\u0003צד שמאל\u0004 של גופן הוא ה\u0003ממהר לבא, מפני ששואבות כדי מים עליהן.\u0004 \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר מדוע הדד שבצד שמאל מקדים לצמוח אצל בנות עניים לפני הדד שבצד ימין, \u0003מפני ש\u0004הבנות הללו \u0003נושאין\u0004 את \u0003אחיהן\u0004 הקטנים \u0003על גססיהן\u0004 \u0005[צידן]\u0006 השמאלי.","ועוד בענין זה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 הדד שב\u0003צד שמאל\u0004 צומח \u0003קודם ל\u0004דד שב\u0003צד ימין.\u0004 \u0003ר'\u0004 \u0003חנינא בן אחי ר'\u0004 \u0003יהושע אומר: מעולם לא קדם צד שמאל לצד ימין, ח\u0004 \u0003וץ מ\u0004בת \u0003אחת שהיתה בשכונתי, שקדם\u0004 אצלה צמיחתו של הדד שב\u0003צד שמאל ל\u0004דד שב\u0003צד ימין, וחזר לאיתנו,\u0004 שחזר הימני לצמוח כדרכו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כל ה\u0004בנות ה\u0003נבדקות\u0004 אם הופיעו סימניהן — \u0003נבדקות על פי נשים,\u0004 שיש נאמנות לנשים להעיד על הבדיקה. ונמסר ש\u0003כן היה\u0004 נוהג למעשה \u0003ר' אליעזר,\u0004 שהיה \u0003מוסר\u0004 את הבנות \u0003ל\u0004בדיקה אצל \u0003אשתו, ו\u0004אילו \u0003ר' ישמעאל\u0004 היה \u0003מוסר\u0004 את הבנות \u0003ל\u0004בדיקה אצל \u0003אמו.\u0004","\u0003ר'\u0004 \u0003יהודה אומר: לפני הפרק\u0004 (לפני שהבת היא בת אחת עשרה שנים ויום אחד), שאף אם תימצאנה שערות אצלה, הריהי עדיין קטנה, שאין השערות אלא שומה בלבד, \u0003ו\u0004כמו כן \u0003לאחר הפרק\u0004 (אחר שהגיעה הבת לשתים עשרה שנה ויום אחד), וכרגיל הבנות מביאות שערות — \u0003נשים בודקות אותן,\u0004 ונאמנות הן על כך. ואולם \u0003תוך הפרק\u0004 (בתקופת הזמן שבין אחת עשרה שנים ויום אחד לשתים עשרה שנים ויום אחד) — \u0003אין נשים בודקות אותן.\u0004 וטעם הדבר, משום \u0003שאין משיאין\u0004 (פותרים) \u0003ספקות על פי נשים.\u0004 \u0003ר'\u0004 \u0003שמעון אומר: אף תוך הפרק\u0004 — \u0003נשים בודקות אותן.\u0004 \u0003ונאמנת אשה להחמיר אבל לא להקל.\u0004","ומסבירים: \u0003כיצד\u0004 (באיזה אופן) נאמנת אשה לבדוק סימני בגרות, להחמיר אבל לא להקל? אם העידה שהבת \u0003\"גדולה היא\"\u0004 — עדותה מתקבלת רק לענין להחמיר עליה \u0003שלא תמאן\u0004 בבעל שהשיאו לה אמה ואחיותיה, וכדין הקטנה הרשאית למאן (אבל לא להקל עליה, שתחלוץ או שתיבם). ולהיפך, אם הנשים הבודקות העידו ש\u0003\"קטנה היא\"\u0004 — מתקבלת עדותן לענין זה \u0003שלא תחלוץ.\u0004","\u0003אבל אין נאמנת לומר \"קטנה היא\"\u0004 להקל עליה, \u0003שתמאן, ו\u0004כן אין עדותן של הנשים הבודקות האומרות ש\u0003\"גדולה היא\"\u0004 מתקבלת לענין להקל עליה \u0003שתחלוץ\u0004 על סמך בדיקה ועדות זו.","ומבררים את הדברים שבברייתא זו. \u0003אמר מר\u0004 \u0005[החכם],\u0006 \u0003ר' יהודה אומר: לפני הפרק ולאחר הפרק\u0004 — \u0003נשים בודקות אותן.\u0004 ועל כך שואלים: \u0003בשלמא\u0004 \u0005[זה נוח,\u0006 מובן\u0005]\u0006 ש\u0003לפני הפרק בעי\u0004 \u0005[צריך]\u0006 \u0003בדיקה,\u0004 \u0003דאי משתכחי\u0004 \u0005[ש\u0006כן אם יימצאו] השערות שנראו בבדיקה שלפני הפרק גם \u0003לאחר הפרק\u0004 — נדע שאין שערות אלו סימן בגרות, אלא \u0003שומא נינהו\u0004 \u0005[הן].\u0006","\u0003אלא לאחר הפרק, למה לי בדיקה? והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא: קטנה שהגיעה לכלל שנותיה\u0004 — \u0003אינה צריכה בדיקה,\u0004 שכן \u0003חזקה\u0004 ש\u0003הביאה סימנין!\u0004 ומשיבים: \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר רבא חזקה\u0004 זו מועילה \u0003ל\u0004ענין \u0003מיאון\u0004 בלבד, \u0003אבל ל\u0004ענין \u0003חליצה בעיא\u0004 \u0005[צריכה]\u0006 \u0003בדיקה.\u0004","עוד שנינו בברייתא זו, שר' יהודה סבור שדווקא לפני הפרק ולאחר הפרק נשים בודקות אותן, אבל ב\u0003תוך הפרק\u0004 — \u0003אין נשים בודקות אותן,\u0004 ומסבירים: \u0003קסבר\u0004 \u0005[סבור הוא,\u0006 ר' יהודה\u0005]\u0006 כי \u0003תוך הפרק כלאחר הפרק (דמי\u0004 [נחשב]\u0003).\u0004 ומשום כך, הסימנים שהביאה בתוך הפרק, הריהם סימני גדלות, והריהי נחשבת גדולה לפני היותה בת שתים עשרה שנים ויום אחד. ואם תתקבל עדותן של הנשים על כך, הרי תחלוץ או תתייבם זו כגדולה. ומשום כך אין לסמוך עליהן על בדיקה שבתוך הפרק.","\u0003ו\u0004מעתה נאמר, \u0003לאחר הפרק, דאיכא\u0004 \u0005[שיש כאן]\u0006 בזמן זה ה\u0003חזקה\u0004 של \u0003רבא\u0004 שהביאה סימנים — משום כך אף \u0003סמכינן\u0004 \u0005[סומכים אנו]\u0006 על ה\u0003נשים ובדקי\u0004 \u0005[ובודקות].\u0006 ואילו \u0003תוך הפרק, דליכא\u0004 \u0005[שאין כאן]\u0006 את ה\u0003חזקה\u0004 של \u0003רבא\u0004 — \u0003לא סמכינן\u0004 \u0005[אין סומכים אנו]\u0006 על ה\u0003נשים ולא בדקי\u0004 \u0005[ולא בודקות]\u0006 אותן \u0003נשים.\u0004","ואילו \u0003ר' שמעון אומר: אף תוך הפרק\u0004 — \u0003נשים בודקות אותן,\u0004 ומסבירים, \u0003קסבר\u0004 \u0005[הוא סבור]:\u0006 \u0003תוך הפרק\u0004 — \u0003כלפני הפרק,\u0004 והרי היא איפוא קטנה וודאי, ואין הבדיקה יכולה להפקיעה מכלל קטנות. \u0003ו\u0004אולם בכל זאת הריהי \u0003בעיא\u0004 \u0005[צריכה]\u0006 \u0003בדיקה,\u0004 משום \u0003דאי משתכחי\u0004 \u0005[שאם יימצאו]\u0006 אותן שערות שנמצאו בבדיקה שבתוך הפרק אף \u0003לאחר הפרק\u0004 — נדע שאין אלו סימני בגרות אלא \u0003שומא נינהו\u0004 \u0005[הם].\u0006","\u0003ו\u0004עוד שנינו בברייתא זו כי \u0003נאמנת אשה\u0004 בבדיקה זו \u0003להחמיר\u0004 בדינה של הנבדקת \u0003אבל לא להקל\u0004 עליה בדינה. ודנים בדברים הללו, \u0003האי\u0004 \u0005[\u0006הלכה \u0005זו]\u0006 \u0003מאן קתני לה\u0004 \u0005[מי\u0006 התנא ש\u0005שנה אותה]?\u0006 ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 כי הלכה זו שנה אותה \u0003ר' יהודה, ו\u0004על \u0003תוך הפרק,\u0004"],["\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר, שהתנא שאמרה הוא \u0003ר' שמעון, ו\u0004בדיקה זו האמורה בה הריהי \u0003לאחר הפרק, ולית ליה\u0004 \u0005[ואין לו,\u0006 ר' שמעון אינו סבור\u0005]\u0006 שיש \u0003חזקה,\u0004 כשיטת \u0003רבא\u0004 שחזקה שהביאה כבר שערות.","שנינו במשנתנו בהסבר שיטת חכמים שכאשר בא הסימן העליון הריהי נחשבת כגדולה, ואם נפלה לייבום לפני אחי בעלה שמת, הריהי חולצת או מתייבמת, \u0003מפני שאמרו\u0004 חכמים ש\u0003אפשר\u0004 לסימן התחתון להופיע לפני הסימן העליון, אבל אי אפשר לסימן העליון להופיע לפני הסימן התחתון. ושואלים: \u0003הא תו\u0004 \u0005[עוד זאת]\u0006 \u0003למה לי\u0004 שוב לשנות, \u0003הא תנא ליה רישא\u0004 \u0005[הרי שנה אותו\u0006 כבר ב\u0005תחילת\u0006 המשנה\u0005]\u0006 שאי אפשר לסימן העליון להופיע בלא שהופיע כבר הסימן התחתון?","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שחזר התנא במשנתנו ושנה כלל זה \u0003משום דקא בעי למסתמה כרבנן\u0004 \u0005[שהוא רצה לסותמה,\u0006 לציין את המשנה בסתם, ללא ציון שם, וכשיטת \u0005חכמים],\u0006 להורות שהלכה כמותם במחלוקתם עם ר' מאיר. ויש לדחות: לשם פסיקת הלכה אין צורך בחזרה זו, שהרי \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר שהלכה כחכמים, שהרי כלל הלכתי הוא: \u0003יחיד ורבים\u0004 — \u0003הלכה כרבים!\u0004","ומשיבים: על סמך הכלל \"יחיד ורבים — הלכה כרבים\" כשלעצמו לא הייתי פוסק הלכה כחכמים, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003מסתברא טעמא\u0004 \u0005[מסתבר הטעם]\u0006 של \u0003ר' מאיר, דקא מסייע ליה קראי\u0004 \u0005[שכן מסייעים לו מקראות\u0006 \"שדים נכונו ושערך צמח\", \"בעשות מצרים דדיך למען שדי נעוריך\"\u0005],\u0006 לכן \u0003קא משמע לן\u0004 \u0005[\u0006התנא שסתם כחכמים, משמיע לנו], שאין הלכה כר' מאיר. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר מדוע חזר התנא ושנה שאי אפשר לסימן העליון לבוא לפני הסימן התחתון, \u0003משום דקא בעי למתני\u0004 \u0005[שהוא רוצה לשנות]\u0006 את המשנה הבאה, שאף בה יש כלל דומה לזה של סדר הופעת הסימנים, בלשון \u0003\"כיוצא בו\",\u0004 המורה על השוואת שני הכללים הללו.","\u0003כיוצא בו\u0004 בסדר הופעת סימני הבגרות אצל הבת, שאי אפשר שיופיע הסימן העליון בלא שהופיע כבר הסימן התחתון, כלל דומה בענין התלות בין שני דברים: \u0003כל כלי חרס\u0004 שיש בו נקב, \u0003שהוא מכניס,\u0004 שדרך נקב זה חודר משקה פנימה אל תוך הכלי — ודאי הוא שנקב זה אף \u0003מוציא\u0004 משקה מן הכלי החוצה. והריהו חדל מלהיקרא \"כלי\" לענין שיהא כשר לקדש בו מי פרה אדומה. \u0003ו\u0004אולם \u0003יש\u0004 נקב בכלי חרס \u0003ש\u0004הריהו \u0003מוציא\u0004 משקה מן הכלי החוצה, \u0003ו\u0004אולם הוא \u0003אינו מכניס\u0004 משקה מבחוץ אל תוך הכלי. ולא יצא בכך מגדר \"כלי\".","ועוד כלל דומה: \u0003כל אבר\u0004 מאברי הגוף \u0003שיש בו צפורן\u0004 — ודאי ש\u0003יש בו\u0004 גם \u0003עצם,\u0004 ואם הוא מן המת, הריהו מטמא במגע ובמשא ובאוהל (ואפילו אין בו כשיעור זית). \u0003ו\u0004אולם \u0003יש\u0004 אבר מאברי הגוף \u0003שיש בו עצם, ואין בו צפורן.\u0004 ואבר כזה אינו נחשב לטמא אף בפחות מכזית בטומאת אוהל.","ועוד כלל בענין תלות בין שני דברים: \u0003כל המטמא\u0004 (הראוי להיטמא) בטומאת \u0003מדרס\u0004 הזב — הריהו \u0003מטמא\u0004 (ראוי גם להיות) \u0003טמא מת.\u0004 \u0003ו\u0004אולם \u0003יש שמטמא טמא מת, ואינו מטמא מדרס.\u0004","שנינו במשנתנו בכלי חרס שניקב באופן שמכניס משקה אל תוך הכלי הריהו גם מוציא משקה מתוכו, וכלי שניקב באופן שמוציא משקה מתוכו, אין בו כשלעצמו בדווקא כדי להכניס משקה לתוכו. ומסבירים מה ענין הבחנה זו להלכה: כלי שיש בו נקב ה\u0003מכניס\u0004 משקה אל תוכו — חדל להיקרא \"כלי\" ומשום כך הוא \u0003פסול ל\u0004קדש בתוכו \u0003מי חטאת\u0004 (מי אפר פרה אדומה), \u0003ופסול\u0004 גם \u0003משום גסטרא\u0004 (שבר כלי הראוי לשימוש ומקבל טומאה). ואילו כלי חרס שיש בו נקב ה\u0003מוציא\u0004 משקה מתוכו החוצה ואינו מכניס — \u0003כשר ל\u0004קדש בתוכו \u0003מי חטאת.\u0004 \u0003ו\u0004אולם \u0003פסול\u0004 הוא \u0003משום גסטרא.\u0004","\u0003אמר רב אסי,\u0004 כך חכמים \u0003שונין: כלי חרס שיעורו\u0004 של הנקב הפוסלו הוא \u0003בכונס משקה.\u0004 \u0003ולא אמרו\u0004 חכמים שאף נקב קטן ה\u0003מוציא משקה\u0004 פסול מלקדש מי חטאת בתוכו \u0003אלא לענין גסטרא בלבד.\u0004 ומבררים: \u0003מאי טעמא\u0004 \u0005[מה טעם]?\u0006 \u0003אמר מר זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחמן: לפי שאין אומרים\u0004 אנשים \u0003\"הבא גסטרא\" לגסטרא\u0004 שניקבה, כדי שלא תיזל, אבל אומרים אנשים \"הבא גסטרא לכלי חרס שניקב\".","ועוד בענין זה של נקב בכלי חרס, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כיצד בודקין כלי חרס\u0004 על מנת \u0003לידע אם ניקב ב\u0004שיעור שיש בו כדי \u0003כונס משקה אם לאו\u0004 \u0005[לא]?\u0006 \u0003יביא עריבה\u0004 (גיגית) \u0003מלאה מים, ונותן\u0004 את ה\u0003קדרה\u0004 שניקבה \u0003לתוכה.\u0004 ומתבוננים: \u0003אם כנסה\u0004 (חדרו מי העריבה אל תוך הקדירה) — \u0003בידוע ש\u0004הנקב הוא בשיעור של \u0003כונס משקה, ואם לאו\u0004 \u0005[לא]\u0006 חדרו המים אל הקדירה — \u0003בידוע ש\u0004הנקב אינו אלא בשיעור של \u0003מוציא משקה.\u0004"],["\u0003ר' יהודה אומר:\u0004 כך היא הדרך בה בודקים כלי חרס אם הנקב שבו ככונס משקה (ופסול לשמש לקידוש מי חטאת) או כמוציא משקה (וכשר לקדש מי חטאת בתוכו) — \u0003כופף אזני קדרה לתוכה,\u0004 כלומר, הופך את הקדירה הנקובה על פיה ומניח אותה כך בתוך גיגית ריקה ממשקה, \u0003ו\u0004לאחר מכן \u0003מציף עליה מים.\u0004 \u0003ו\u0004מתבוננים עתה, \u0003אם כונס\u0004 (חדרו מים אל תוך הקדירה) — \u0003בידוע ש\u0004הנקב הוא בשיעור של \u0003כונס משקה, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003בידוע ש\u0004הנקב הוא רק בשיעור של \u0003מוציא משקה.\u0004","\u0003או\u0004 אפשרות בדיקה נוספת: \u0003שופתה\u0004 (מעמידה) את הקדירה הנקובה כשבתוכה משקה \u0003על גבי האור\u0004 (האש). ומתבוננים: \u0003אם האור מעמידה\u0004 (עוצר) את יציאת המשקה שבתוכה החוצה — \u0003בידוע ש\u0004אין הנקב הזה אלא כ\u0003מוציא משקה, ואם לאו\u0004 \u0005[לא]\u0006 נעצרת יציאת המשקה מהקדירה, אף שהיא עומדת על האש — \u0003בידוע ש\u0004הנקב הוא בשיעור כ\u0003מכניס משקה.\u0004","\u0003ר'\u0004 \u0003יוסי אומר:\u0004 \u0003אף לא שופתה על גבי האור\u0004 כדי לבדוק את שיעור הנקב, שאין זו שיטת בדיקה טובה, \u0003מפני ש\u0004יתכן שהנקב הוא כשיעור כונס משקה, ואולם אין המשקה יוצא החוצה משום ש\u0003האור\u0004 הוא ש\u0003מעמידה,\u0004 ולא מחמת שיעורו הקטן של הנקב. \u0003אלא\u0004 עושה כך: \u0003שופתה על גבי הרמץ\u0004 (אפר חם, גחלים עמומות), ומתבוננים מעתה: \u0003אם\u0004 הרמץ \u0003מעמידה\u0004 (עוצרה) — \u0003בידוע ש\u0004הנקב הוא רק בשיעור \u0003מוציא משקה, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003בידוע ש\u0004הנקב הוא בשיעור \u0003כונס משקה.\u0004 ואופן הבדיקה: ממלא את הכלי משקה, ואם \u0003היה\u0004 המשקה \u0003טורד\u0004 (דולף החוצה) בטפטוף \u0003טיפה אחר טיפה\u0004 — \u0003בידוע ש\u0004שיעור הנקב בכונס \u0003משקה.\u0004","ומבררים: \u0003מאי איכא\u0004 \u0005[מה,\u0006 איזה הבדל להלכה \u0005יש]\u0006 \u0003בין\u0004 שיטת הבדיקה של \u0003תנא קמא\u0004 \u0005[התנא הראשון]\u0006 הנעשית על ידי הכנסת הקדירה אל תוך גיגית מים, \u0003ל\u0004שיטת הבדיקה של \u0003ר' יהודה\u0004 על ידי הכנסת הקדירה תחילה כשהיא הפוכה, ולאחר מכן להציף אותה במים? \u0003אמר עולא:\u0004 בדין \u0003כינוס\u0004 (כניסה) של מים לתוך הכלי הנבדק \u0003על ידי הדחק\u0004 (כתוצאה מהפעלת כוח), האם נחשב הדבר לכניסה, \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל. שלדעת ר' יהודה הכנסה של קדירה לתוך גיגית מלאה מים, כרוכה בהפעלת כוח מסויים, ואם יכנסו כתוצאה מכך מים לקדירה — אין זו נחשבת כניסה. ואילו לשיטת התנא הראשון, אף כניסה כזו — נחשבת כניסה.","שנינו במשנתנו כי \u0003כל אבר שיש בו צפורן\u0004 בודאי יש בו גם עצם, ואולם יש אפשרות של אבר שיש בו עצם אך אין בו צפורן. ומסבירים מה עניינה להלכה של הבחנה זו: אבר ש\u0003יש בו צפורן\u0004 (וכאמור, בודאי שיש בו אף עצם) — הריהו נחשב כאבר לכל דבר, ודינו שהוא \u0003מטמא ב\u0004טומאת \u0003מגע וב\u0004טומאת \u0003משא וב\u0004טומאת \u0003אהל,\u0004 ואפילו אין בו כשיעור זית. ויש אפשרות של אבר ש\u0003יש בו עצם ואין בו צפורן\u0004 — ודינו של זה שהוא \u0003מטמא ב\u0004טומאת \u0003מגע וב\u0004טומאת \u0003משא,\u0004 אף שאין בו כשיעור כזית, \u0003ואינו מטמא באהל\u0004 אלא אם כן היה בו שיעור כזית.","\u0003אמר רב חסדא, דבר זה\u0004 שייאמר להלן \u0003רבינו הגדול\u0004 (=רב) \u0003אמרו, המקום יהיה בעזרו:\u0004 אם היתה בגוף \u0003אצבע יתרה\u0004 יתירה על מנין האצבעות הקבוע, \u0003שיש בו עצם, ו\u0004אולם \u0003אין בו צפורן\u0004 — \u0003מטמא ב\u0004טומאת \u0003מגע וב\u0004טומאת \u0003משא, ואינו מטמא ב\u0004טומאת \u0003אהל.\u0004","\u0003אמר רבה בר בר חנה\u0004 שכך \u0003אמר ר'\u0004 \u0003יוחנן\u0004 בהגדרת הדברים הללו: \u0003ו\u0004דין זה שאצבע יתירה נחשבת כאבר דווקא כשיש בה עצם וציפורן, אמור רק \u0003כשאינה נספרת על גב היד,\u0004 כלומר, שהיא חורגת מקו שאר אצבעות היד, אבל אם היתה האצבע הנוספת נתונה בצד שאר האצבעות, בקו אחד, הרי זו כשאר אברים, ומטמאה בטומאת אהל גם אם אין בה צפורן ועצם.","עוד שנינו במשנתנו כי \u0003כל\u0004 כלי \u0003המטמא\u0004 (הראוי להיטמא) בטומאת \u0003מדרס\u0004 הזב — הריהו ראוי להיטמא אף בטומאת טמא מת. ואולם יש שראוי להיטמא בטומאת מת, ואינו מיטמא בטומאת מדרס הזב. ודנים בדבר: \u0003כל דחזי\u0004 \u0005[שראוי]\u0006 \u0003ל\u0004טומאת \u0003מדרס\u0004 הזב — הריהו גם \u0003מטמא\u0004 (ראוי להיטמא) ב\u0003טמא מת,\u0004","\u0003ויש שמטמא טמא מת ואין מטמא מדרס, לאתויי מאי\u0004 \u0005[לרבות מה]?\u0006 ומשיבים: \u0003לאתויי\u0004 \u0005[לרבות]\u0006 אף כלי מדידה, כגון כלי מדידה בשיעור של \u0003סאה ו\u0004כלי מדידה בשיעור של \u0003תרקב\u0004 (חצי סאה).","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 ברייתא\u0005]\u0006 על האמור בטומאת מדרס הזב \u0003\"והיושב על הכלי\u0004 אשר ישב עליו הזב... וטמא עד הערב\" (ויקרא טו, ו): \u0003יכול\u0004 גם אם הזב \u0003כפה\u0004 (הפך על פניו) כלי למדידת \u0003סאה וישב עליה, או\u0004 כלי למדידת \u0003תרקב וישב עליו יהא טמא\u0004 אותו כלי מדידה, ככל מושב הזב?","\u0003תלמוד לומר \"אשר ישב עליו הזב\"\u0004 — ללמדנו: רק \u0003מי שמיוחד לישיבה\u0004 הוא המושב הנטמא בזב, \u0003יצא\u0004 מכלל אלו, כלי \u0003זה שאומרים לו\u0004 לאדם היושב עליו: \"\u0003עמוד\u0004 קום מכלי זה, \u0003ונעשה\u0004 בו, בכלי הזה את \u0003מלאכתנו,\u0004 המדידה\", שאין הוא בהגדרתו כלי מושב, אלא כלי למלאכה מסויימת.","\u0003כל\u0004 אדם הראוי (הכשר) \u0003לדון דיני נפשות\u0004 — \u0003ראוי לדון\u0004 אף \u0003דיני ממונות.\u0004 \u0003ויש\u0004 מי \u0003שראוי לדון דיני ממונות ואינו ראוי לדון דיני נפשות.\u0004","על האמור במשנתנו כי יש הכשרים לדון דיני ממונות ואין הם כשרים לדון דיני נפשות, \u0003אמר רב יהודה\u0004 הלכה זו באה \u0003לאתויי\u0004 \u0005[להביא,\u0006 לרבות] אף את ה\u0003ממזר,\u0004 שאין הוא אמנם ראוי לדון בדיני נפשות, ואולם רשאי הוא לדון דיני ממונות.","ושואלים על כך: והרי כבר \u0003תנינא חדא זימנא\u0004 \u0005[שנינו\u0006 זאת \u0005פעם אחת],\u0006 שכן שנינו במשנה במסכת סנהדרין כי \u0003הכל כשרין לדון דיני ממונות ואין הכל כשרין לדון דיני נפשות, והוינן\u0004 \u0005[ושאלנו]\u0006 \u0003בה,\u0004 בלשון \"הכל כשרין\" שבמשנה זו \u0003לאתויי מאי\u0004 \u0005[להביא,\u0006 לרבות את \u0005מה]\u0006 באה הלכה זו? \u0003ואמר רב יהודה\u0004 בהסבר הדבר: \u0003לאתויי\u0004 \u0005[להביא,\u0006 לרבות] \u0003ממזר!\u0004 ומשיבים: \u0003חדא\u0004 \u0005[\u0006משנה \u0005אחת]\u0006 באה \u0003לאתויי\u0004 \u0005[להביא,\u0006 לרבות] \u0003גר, וחדא\u0004 \u0005[ו\u0006משנה \u0005אחת]\u0006 באה \u0003לאתויי\u0004 \u0005[להביא,\u0006 לרבות] \u0003ממזר.\u0004","ומסבירים עוד: \u0003וצריכי\u0004 \u0005[ונצרכו]\u0006 שני הריבויים הללו, משום \u0003דאי אשמעינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 רק ש\u0003גר\u0004 כשר לדון בדיני ממונות, הייתי אומר שהקילו בו \u0003משום\u0004 ש\u0003ראוי לבא בקהל\u0004 (לשאת בת ישראל), \u0003אבל ממזר\u0004 ש\u0003אין ראוי לבא בקהל\u0004 (שאסור הוא בבת ישראל), \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 כשר הוא לדין דיני ממונות.","\u0003ו\u0004מן הצד האחר, \u0003אי אשמעינן\u0004 \u0005[אם היה משמיע לנו]\u0006 רק ש\u0003ממזר\u0004 כשר לדון דיני ממונות, הייתי אומר שהקילו בו \u0003משום דקאתי\u0004 \u0005[שהוא בא,\u0006 נוצר\u0005]\u0006 \u0003מטפה כשרה,\u0004 שהרי אביו מולידו (בעבירה) הינו יהודי, \u0003אבל גר, דקאתי\u0004 \u0005[שבא]\u0006 \u0003מטפה פסולה\u0004 (שכן נולד מאביו הגוי), \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 כשר הוא לדון אף בדיני ממונות. משום כך \u0003צריכא\u0004 \u0005[צריך]\u0006 את שני הריבויים הללו.","\u0003כל הכשר לדון\u0004 (לשמש כדיין), \u0003כשר\u0004 אף \u0003להעיד\u0004 בדין. \u0003ו\u0004אולם \u0003יש\u0004 מי \u0003שכשר להעיד, ואינו כשר לדון.\u0004","שנינו במשנתנו כי יש שאדם כשר להעיד אך אינו כשר לדון, ושואלים: \u0003לאתויי מאי\u0004 \u0005[להביא,\u0006 לרבות את מה] באה המשנה? \u0003אמר ר'\u0004 \u0003יוחנן:\u0004 משנתנו באה \u0003לאתויי\u0004 \u0005[להביא,\u0006 לרבות] את ה\u0003סומא באחת מעיניו,\u0004 שאף שכשר הוא להעיד, אין הוא כשר לדון. \u0003ו\u0004כשיטת \u0003מני\u0004 \u0005[מי היא]?\u0006"]]};
